-- ===========================================================================
-- The master value lists could not be uploaded at all.
--
--   there is no unique or exclusion constraint matching the ON CONFLICT
--   specification — this register matches on name,value
--
-- The uniqueness masters carries is (name, value, stage, product), and the last
-- two are EXPRESSIONS over `extra` (0021, widened by 0044). `on conflict` cannot
-- infer an expression index, so the upsert was refused outright — the eighth
-- time this project has met that wall, and the first on a table where the
-- expressions were the point.
--
-- The fix is the same one 0076 used for the party key: STORED generated columns
-- that hold what the expressions computed, and a unique index on plain columns.
-- Nothing about the rule changes — "Calibration" may still exist for MONNAL T60
-- and for T75, and a Spare Approval Reason may still exist at two stages.
--
-- Filed under daily_review, not masters: 0044 owns the index this replaces, and
-- a migration that redefines something a LATER module owns is overwritten by it
-- on a fresh apply.
-- ===========================================================================

alter table public.masters
  add column if not exists stage_key   text generated always as (coalesce(extra->>'stage', ''))   stored,
  add column if not exists product_key text generated always as (coalesce(extra->>'product', '')) stored;

do $$
begin
  if exists (
    select 1 from public.masters
     group by name, value, coalesce(extra->>'stage', ''), coalesce(extra->>'product', '')
    having count(*) > 1
  ) then
    raise notice 'masters holds duplicate (name, value, stage, product) rows — de-duplicate, then re-run this file to build masters_name_value_keys_uniq.';
    return;
  end if;
  create unique index if not exists masters_name_value_keys_uniq
    on public.masters (name, value, stage_key, product_key);
  -- The expression index it replaces guarantees the same thing and can no
  -- longer be inferred by anything.
  drop index if exists public.masters_name_value_product_idx;
end $$;

-- ------------------------------------------------------------------------
-- 0047_daily_review_report_context.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0047 — What the reviewer needs from the REPORT, on the review row.
--
-- Reviewing a call means judging what the engineer actually found and did, so
-- the register carries the report alongside the three stages:
--
--   VISIT DETAILS      every visit, newest first, as "date : what was done" —
--                      the register's VISIT REMARKS column.
--   CALL STATUS        the latest visit's own status, and the call's open state.
--   SPARES CONSUMED    every spare booked against the call.
--   AGE OF THE PRODUCT how old the machine was when it failed — the days from
--                      warranty start to the complaint, and the register's
--                      banding of it ("With in 1 yr" … "More than 5 yrs").
--   SOFTWARE VERSION   as recorded on the latest visit.
--
-- All of it is DERIVED — nothing new is stored, and nothing has to be kept in
-- step by hand. `field_call_review` is rebuilt (dropped and created, not
-- replaced: replacing cannot reorder or drop a view's columns).
--
-- Idempotent.
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- 1. The register's own banding of a product's age at failure. Whole years
--    from warranty start, capped at 5 — the buckets the DCCR has always used.
-- ---------------------------------------------------------------------------
create or replace function public.failure_age_group(p_days integer)
returns text language sql immutable set search_path = public as $$
  select case
    when p_days is null or p_days < 0 then ''
    when p_days <  365 then 'With in 1 yr'
    when p_days <  730 then 'More than 1 yr'
    when p_days < 1095 then 'More than 2 yrs'
    when p_days < 1460 then 'More than 3 yrs'
    when p_days < 1825 then 'More than 4 yrs'
    else                    'More than 5 yrs'
  end;
$$;

-- ---------------------------------------------------------------------------
-- 2. The lookups the view makes per call, one index each.
--
--    The register is read NEWEST FIRST and a page at a time, so this index is
--    what keeps it cheap: without it the whole register is sorted before the
--    page is cut, and the per-call lookups below run for every row rather than
--    for the 500 being shown. (Measured on 25k calls / 50k visits: a page goes
--    from 13.7 s to 0.25 s.)
--    reports already has (ucn); the latest visit is picked by ENTRY —
--    updated_at desc, id desc — the same rule as sync_call_last_visit()
--    (0032_call_state_by_entry.sql), so this index serves that order directly.
-- ---------------------------------------------------------------------------
create index if not exists field_calls_reg_date_idx
  on public.field_calls (reg_date desc nulls last, id desc);
create index if not exists reports_ucn_entry_idx
  on public.reports (ucn, updated_at desc, id desc);
create index if not exists spare_consumption_ucn_idx
  on public.spare_consumption (ucn);
create index if not exists spare_consumption_call_number_idx
  on public.spare_consumption (call_number);

-- ---------------------------------------------------------------------------
-- 3. The register, with the report on the row.
-- ---------------------------------------------------------------------------
drop view if exists public.field_call_review;
create view public.field_call_review as
select
  c.id,
  c.ucn,
  c.call_number,
  c.reg_date,
  c.complaint_date,
  c.party_name,
  c.city,
  c.state,
  c.product_name,
  c.serial,
  c.item_status,
  c.call_type,
  c.standard_complaint,
  c.complaint_reported,
  c.allocated_to,
  c.allocated_to_email,
  c.warranty_number,
  c.warranty_start,
  c.status,
  c.open_state,
  c.last_status,
  c.last_visit_at,

  -- ---- age of the product at failure -------------------------------------
  -- Warranty start to the complaint (the call's registration date when there
  -- is no complaint date). Null when the machine has no warranty start on it.
  age.age_days,
  public.failure_age_group(age.age_days) as age_group,

  -- ---- from the report ----------------------------------------------------
  coalesce(h.visit_details, '')  as visit_details,   -- every visit, newest first
  coalesce(h.visit_count, 0)     as visit_count,
  coalesce(v.sw_version, '')     as sw_version,
  coalesce(v.observation, '')    as observation,     -- latest visit's finding
  coalesce(v.job_done, '')       as job_done,
  coalesce(v.pending_reason, '') as pending_reason,
  coalesce(v.visit_engineer, '') as visit_engineer,
  coalesce(sp.spares_consumed, '') as spares_consumed,
  coalesce(sp.spares_count, 0)     as spares_count,

  -- ---- Review 1 — from the call itself ------------------------------------
  c.public_health_threat,
  c.death,
  c.serious_incident,
  c.reg_date as review1_at,
  (btrim(coalesce(c.public_health_threat, '')) <> ''
   and btrim(coalesce(c.death, '')) <> ''
   and btrim(coalesce(c.serious_incident, '')) <> '') as review1_done,
  -- ---- Review 2 -----------------------------------------------------------
  coalesce(r.risk_to_patient, '')     as risk_to_patient,
  coalesce(r.warranty_failure, '')    as warranty_failure,
  coalesce(r.frequent_failure, '')    as frequent_failure,
  r.review2_at,
  coalesce(r.review2_by, '')          as review2_by,
  coalesce(r.review2_done, false)     as review2_done,
  -- ---- Review 3 -----------------------------------------------------------
  coalesce(r.complaint_grouping, '')  as complaint_grouping,
  coalesce(r.root_cause_keyword, '')  as root_cause_keyword,
  coalesce(r.spare_category, '')      as spare_category,
  coalesce(r.service_observation, '') as service_observation,
  r.review3_at,
  coalesce(r.review3_by, '')          as review3_by,
  coalesce(r.review3_done, false)     as review3_done,
  -- ---- Derived ------------------------------------------------------------
  coalesce(r.any_potential_effect, '') as any_potential_effect,
  coalesce(r.action_taken, '')         as action_taken,
  case
    when not (btrim(coalesce(c.public_health_threat, '')) <> ''
              and btrim(coalesce(c.death, '')) <> ''
              and btrim(coalesce(c.serious_incident, '')) <> '') then 'Review 1 Pending'
    when not coalesce(r.review2_done, false) then 'Review 2 Pending'
    when not coalesce(r.review3_done, false) then 'Review 3 Pending'
    else 'Review Completed'
  end as review_status
from public.field_calls c
left join public.call_reviews r on r.ucn = c.ucn

-- Age at failure.
left join lateral (
  select (coalesce(c.complaint_date, c.reg_date) - c.warranty_start)::int as age_days
) age on true

-- The LATEST visit, by entry (updated_at desc, id desc) — the same visit the
-- call's status comes from.
left join lateral (
  select nullif(btrim(coalesce(rp.data->>'Software Version', '')), '')      as sw_version,
         nullif(btrim(coalesce(rp.data->>'Complaint Observation', '')), '') as observation,
         nullif(btrim(coalesce(rp.data->>'Job Done', '')), '')              as job_done,
         nullif(btrim(coalesce(rp.pending_reason, '')), '')                 as pending_reason,
         nullif(btrim(coalesce(rp.engineer, '')), '')                       as visit_engineer
    from public.reports rp
   where rp.ucn = c.ucn
   order by rp.updated_at desc nulls last, rp.id desc
   limit 1
) v on true

-- EVERY visit, as the register writes them: "date : what was done", newest
-- first. A visit with nothing written still shows its date, so a call that was
-- attended and left blank does not read as never visited.
left join lateral (
  select string_agg(
           to_char(coalesce(rp.visit_at, rp.updated_at), 'DD-Mon-YYYY') || ' : ' ||
           coalesce(
             nullif(btrim(coalesce(rp.data->>'Job Done', '')), ''),
             nullif(btrim(coalesce(rp.data->>'Complaint Observation', '')), ''),
             ''),
           E'\n' order by rp.visit_at desc nulls last, rp.id desc) as visit_details,
         count(*) as visit_count
    from public.reports rp
   where rp.ucn = c.ucn
) h on true

-- Every spare booked against the call, with the quantity when it is not one.
left join lateral (
  select string_agg(
           btrim(s.part) || case
             when coalesce(s.qty, 1) = 1 then ''
             -- A whole number reads as "x 2", not "x 2." (FM keeps the point).
             when s.qty = trunc(s.qty) then ' x ' || trunc(s.qty)::bigint::text
             else ' x ' || trim(to_char(s.qty, 'FM999999.999'))
           end,
           ', ' order by s.id) as spares_consumed,
         count(*) as spares_count
    from public.spare_consumption s
   where s.ucn = c.ucn and btrim(coalesce(s.part, '')) <> ''
) sp on true;

alter view public.field_call_review set (security_invoker = on);
grant select on public.field_call_review to authenticated;

-- ---------------------------------------------------------------------------
-- 4. The same register WITHOUT the per-call report lookups.
--
--    The module's stage counters ask "how many of the whole filtered set are
--    at each stage", which the full view cannot answer cheaply: the report and
--    spares lookups would run for every row counted, not just the page shown
--    (3 s over a year of calls). This carries only what a count filters on and
--    groups by, so counting is a plain scan of the two tables.
-- ---------------------------------------------------------------------------
drop view if exists public.field_call_review_summary;
create view public.field_call_review_summary as
select
  c.id,
  c.ucn,
  c.reg_date,
  c.product_name,
  c.allocated_to,
  c.party_name,
  c.serial,
  coalesce(r.any_potential_effect, '') as any_potential_effect,
  case
    when not (btrim(coalesce(c.public_health_threat, '')) <> ''
              and btrim(coalesce(c.death, '')) <> ''
              and btrim(coalesce(c.serious_incident, '')) <> '') then 'Review 1 Pending'
    when not coalesce(r.review2_done, false) then 'Review 2 Pending'
    when not coalesce(r.review3_done, false) then 'Review 3 Pending'
    else 'Review Completed'
  end as review_status
from public.field_calls c
left join public.call_reviews r on r.ucn = c.ucn;

alter view public.field_call_review_summary set (security_invoker = on);
grant select on public.field_call_review_summary to authenticated;

-- ------------------------------------------------------------------------
-- 0048_daily_review_map_by_call_number.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0048 — Map the visits and the spares to a call by CALL NUMBER.
--
-- 0047 matched `reports` and `spare_consumption` to a call on `ucn` alone, so
-- a call whose visits and consumption are keyed by Call Number read as though
-- it had never been attended: "no visit reported yet" and "no spare booked"
-- on a call the Field Call view shows two visits and a consumed spare for.
--
-- Call Number is what associates them. It is what the Field Call view's own
-- panels read (reportsByCall / spareConsumptionByCall in src/lib/supabase.ts
-- both filter on call_number), and what CallReporting writes against.
--
-- So both lookups now match on EITHER key: the call number when the call has
-- one, or the UCN. A row written by the app carries both; a row that came in
-- from the register may carry only one, and either way it belongs to the call.
-- Blank keys never match — an empty call_number would otherwise sweep in every
-- other row that also has none.
--
-- Idempotent.
-- ===========================================================================

-- The call-number side of both lookups, so matching on either key stays cheap.
-- (reports already has (ucn) and (call_number); this adds the entry ordering
-- the latest-visit pick uses, keyed by call number.)
create index if not exists reports_call_number_entry_idx
  on public.reports (call_number, updated_at desc, id desc);

drop view if exists public.field_call_review;
create view public.field_call_review as
select
  c.id,
  c.ucn,
  c.call_number,
  c.reg_date,
  c.complaint_date,
  c.party_name,
  c.city,
  c.state,
  c.product_name,
  c.serial,
  c.item_status,
  c.call_type,
  c.standard_complaint,
  c.complaint_reported,
  c.allocated_to,
  c.allocated_to_email,
  c.warranty_number,
  c.warranty_start,
  c.status,
  c.open_state,
  c.last_status,
  c.last_visit_at,

  -- ---- age of the product at failure -------------------------------------
  -- Warranty start to the complaint (the call's registration date when there
  -- is no complaint date). Null when the machine has no warranty start on it.
  age.age_days,
  public.failure_age_group(age.age_days) as age_group,

  -- ---- from the report ----------------------------------------------------
  coalesce(h.visit_details, '')  as visit_details,   -- every visit, newest first
  coalesce(h.visit_count, 0)     as visit_count,
  coalesce(v.sw_version, '')     as sw_version,
  coalesce(v.observation, '')    as observation,     -- latest visit's finding
  coalesce(v.job_done, '')       as job_done,
  coalesce(v.pending_reason, '') as pending_reason,
  coalesce(v.visit_engineer, '') as visit_engineer,
  coalesce(sp.spares_consumed, '') as spares_consumed,
  coalesce(sp.spares_count, 0)     as spares_count,

  -- ---- Review 1 — from the call itself ------------------------------------
  c.public_health_threat,
  c.death,
  c.serious_incident,
  c.reg_date as review1_at,
  (btrim(coalesce(c.public_health_threat, '')) <> ''
   and btrim(coalesce(c.death, '')) <> ''
   and btrim(coalesce(c.serious_incident, '')) <> '') as review1_done,
  -- ---- Review 2 -----------------------------------------------------------
  coalesce(r.risk_to_patient, '')     as risk_to_patient,
  coalesce(r.warranty_failure, '')    as warranty_failure,
  coalesce(r.frequent_failure, '')    as frequent_failure,
  r.review2_at,
  coalesce(r.review2_by, '')          as review2_by,
  coalesce(r.review2_done, false)     as review2_done,
  -- ---- Review 3 -----------------------------------------------------------
  coalesce(r.complaint_grouping, '')  as complaint_grouping,
  coalesce(r.root_cause_keyword, '')  as root_cause_keyword,
  coalesce(r.spare_category, '')      as spare_category,
  coalesce(r.service_observation, '') as service_observation,
  r.review3_at,
  coalesce(r.review3_by, '')          as review3_by,
  coalesce(r.review3_done, false)     as review3_done,
  -- ---- Derived ------------------------------------------------------------
  coalesce(r.any_potential_effect, '') as any_potential_effect,
  coalesce(r.action_taken, '')         as action_taken,
  case
    when not (btrim(coalesce(c.public_health_threat, '')) <> ''
              and btrim(coalesce(c.death, '')) <> ''
              and btrim(coalesce(c.serious_incident, '')) <> '') then 'Review 1 Pending'
    when not coalesce(r.review2_done, false) then 'Review 2 Pending'
    when not coalesce(r.review3_done, false) then 'Review 3 Pending'
    else 'Review Completed'
  end as review_status
from public.field_calls c
left join public.call_reviews r on r.ucn = c.ucn

-- Age at failure.
left join lateral (
  select (coalesce(c.complaint_date, c.reg_date) - c.warranty_start)::int as age_days
) age on true

-- The LATEST visit, by entry (updated_at desc, id desc) — the same visit the
-- call's status comes from (sync_call_last_visit, 0032).
left join lateral (
  select nullif(btrim(coalesce(rp.data->>'Software Version', '')), '')      as sw_version,
         nullif(btrim(coalesce(rp.data->>'Complaint Observation', '')), '') as observation,
         nullif(btrim(coalesce(rp.data->>'Job Done', '')), '')              as job_done,
         nullif(btrim(coalesce(rp.pending_reason, '')), '')                 as pending_reason,
         nullif(btrim(coalesce(rp.engineer, '')), '')                       as visit_engineer
    from public.reports rp
   where (btrim(coalesce(c.call_number, '')) <> '' and rp.call_number = c.call_number)
      or (btrim(coalesce(c.ucn, '')) <> '' and rp.ucn = c.ucn)
   order by rp.updated_at desc nulls last, rp.id desc
   limit 1
) v on true

-- EVERY visit, as the register writes them: "date : what was done", newest
-- first. A visit with nothing written still shows its date, so a call that was
-- attended and left blank does not read as never visited.
left join lateral (
  select string_agg(
           to_char(coalesce(rp.visit_at, rp.updated_at), 'DD-Mon-YYYY') || ' : ' ||
           coalesce(
             nullif(btrim(coalesce(rp.data->>'Job Done', '')), ''),
             nullif(btrim(coalesce(rp.data->>'Complaint Observation', '')), ''),
             ''),
           E'\n' order by rp.visit_at desc nulls last, rp.id desc) as visit_details,
         count(*) as visit_count
    from public.reports rp
   where (btrim(coalesce(c.call_number, '')) <> '' and rp.call_number = c.call_number)
      or (btrim(coalesce(c.ucn, '')) <> '' and rp.ucn = c.ucn)
) h on true

-- Every spare booked against the call, with the quantity when it is not one.
left join lateral (
  select string_agg(
           btrim(s.part) || case
             when coalesce(s.qty, 1) = 1 then ''
             -- A whole number reads as "x 2", not "x 2." (FM keeps the point).
             when s.qty = trunc(s.qty) then ' x ' || trunc(s.qty)::bigint::text
             else ' x ' || trim(to_char(s.qty, 'FM999999.999'))
           end,
           ', ' order by s.id) as spares_consumed,
         count(*) as spares_count
    from public.spare_consumption s
   where btrim(coalesce(s.part, '')) <> ''
     and ((btrim(coalesce(c.call_number, '')) <> '' and s.call_number = c.call_number)
       or (btrim(coalesce(c.ucn, '')) <> '' and s.ucn = c.ucn))
) sp on true;

alter view public.field_call_review set (security_invoker = on);
grant select on public.field_call_review to authenticated;

-- ------------------------------------------------------------------------
-- 0010_reports_ordering.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Reports ordering. `public.reports` has no `created_at` column — the visit
-- history is ordered by `visit_at` (newest visit first), with the identity
-- `id` as the tiebreaker for rows that share a date or have none. These
-- indexes back that sort so the register and the per-call/per-UCN lookups
-- stay fast. Run in the Supabase SQL Editor as postgres.
-- ===========================================================================

create index if not exists reports_visit_at_idx on public.reports (visit_at desc nulls last, id desc);
create index if not exists reports_call_number_idx on public.reports (call_number);

-- ------------------------------------------------------------------------
-- 0071_report_source_ref.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Bulk report → call mapping: keep what a link was DERIVED FROM.
--
-- Reports recovered from an AppSheet export arrive carrying AppSheet file
-- references, not Drive links — `Reports_Images/foo.png`, or a
-- gettablefileurl?... URL. The import turns those into Drive links and stores
-- them in `manual_report`, which is what the app opens.
--
-- `source_ref` keeps the ORIGINAL reference alongside it. Without that, a link
-- that resolved to the wrong file is unprovable and unfixable: you cannot tell
-- what it was meant to point at, and a re-run has nothing to re-resolve from.
-- For a quality record that is the difference between a recoverable mistake and
-- a permanent one, which is why it is a column and not a note in `data`.
--
-- `mapped_at` says the row came in through the bulk mapping rather than from an
-- engineer in the field — so a recovered visit is never mistaken for one
-- reported live.
-- ===========================================================================

alter table public.reports add column if not exists source_ref text not null default '';
alter table public.reports add column if not exists mapped_at  timestamptz;

comment on column public.reports.source_ref is
  'The original AppSheet file reference this row''s manual_report was derived from. Kept so a wrong link can be re-resolved.';
comment on column public.reports.mapped_at is
  'Set when the row was loaded by the bulk report → call mapping, not reported live.';

-- The mapping looks a call up by UCN and by call number; both already have
-- their index (0002, 0010). This one is for finding what the bulk run touched.
create index if not exists reports_mapped_at_idx on public.reports (mapped_at desc) where mapped_at is not null;

-- ---------------------------------------------------------------------------
-- Make `uid` usable as an UPSERT target.
--
-- 0002 created it as a PARTIAL unique index (`where uid is not null`).
-- Postgres will not infer a partial index from a bare `on conflict (uid)`, so
-- the bulk mapping's upsert failed outright with "there is no unique or
-- exclusion constraint matching the ON CONFLICT specification" — which is what
-- makes re-running a recovery sheet correct its rows instead of doubling the
-- visit history.
--
-- A FULL unique index is equivalent here and does infer: NULLs are distinct in
-- a unique index, so the rows with no uid (the sheet-era ones) still coexist
-- exactly as they did under the partial index.
-- ---------------------------------------------------------------------------
create unique index if not exists reports_uid_uniq on public.reports (uid);
drop index if exists public.reports_uid_key;

-- ------------------------------------------------------------------------
-- 0006_spare_workflow.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Spare approval workflow on spare_requests:
--   RM → Commercial → NSM → Stores(dispatch/DC).
-- Commercial & NSM auto-approve unless the item is AMC or OGP (item_status).
-- ===========================================================================

alter table public.spare_requests
  add column if not exists rm_approval        text default 'Pending',
  add column if not exists rm_by              text,
  add column if not exists rm_at              timestamptz,
  add column if not exists commercial_approval text default 'Pending',
  add column if not exists commercial_by      text,
  add column if not exists commercial_at      timestamptz,
  add column if not exists nsm_approval        text default 'Pending',
  add column if not exists nsm_by             text,
  add column if not exists nsm_at             timestamptz,
  add column if not exists stores_status       text default 'Pending',
  add column if not exists dc_number          text,
  add column if not exists dispatched_by      text,
  add column if not exists dispatched_at      timestamptz,
  add column if not exists stage              text default 'RM Approval';

-- Approvers update spare_requests (buttons are RBAC-gated in the app).
drop policy if exists sr_update on public.spare_requests;
create policy sr_update on public.spare_requests for update
  using (auth.role() = 'authenticated') with check (auth.role() = 'authenticated');

-- ------------------------------------------------------------------------
-- 0009_spare_receipt.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Spare request module — phase 3.
--   • Reject reasons captured at every approval stage.
--   • Dispatch details (courier / remarks) alongside the DC number.
--   • Engineer acknowledgement, closing the loop: Dispatched → Received.
--
-- Runs after 0008_rbac_enforcement.sql and extends the RBAC it installed:
-- the new receipt columns get their own stage in the guard, and the raiser
-- (who holds none of the approval permissions) is allowed to write them.
-- ===========================================================================

alter table public.spare_requests
  add column if not exists reject_reason     text,
  add column if not exists rejected_stage    text,
  add column if not exists courier           text,
  add column if not exists dispatch_remarks  text,
  add column if not exists received_by       text,
  add column if not exists received_at       timestamptz,
  add column if not exists receipt_remarks   text;

-- The register filters and sorts by workflow stage, so index it.
create index if not exists spare_requests_stage_idx      on public.spare_requests (stage);
create index if not exists spare_requests_created_at_idx on public.spare_requests (created_at desc);

-- ---------------------------------------------------------------------------
-- created_by was never populated: the app inserts spare_requests without it
-- and the column has no default, so it is NULL on every row. 0008's policies
-- test `created_by = auth.uid()`, which therefore never matches — that blocks
-- srl_insert (a non-admin raising a request could not write its lines) as well
-- as the acknowledgement added here. Defaulting it fixes both for new rows.
-- ---------------------------------------------------------------------------
alter table public.spare_requests alter column created_by set default auth.uid();

-- The raiser must be able to update their own request to acknowledge receipt,
-- and they hold none of the approval permissions. Identify them the same way
-- sr_read already does: by created_by, or by the engineer_email on the row.
create or replace function public.is_spare_requester(r public.spare_requests)
returns boolean language sql stable as $$
  select r.created_by = auth.uid()
      or (nullif(trim(r.engineer_email), '') is not null
          and lower(trim(r.engineer_email)) = lower(auth.email()));
$$;
grant execute on function public.is_spare_requester(public.spare_requests) to authenticated;

drop policy if exists sr_update on public.spare_requests;
create policy sr_update on public.spare_requests for update
  using (public.can_approve_spares() or public.is_spare_requester(spare_requests))
  with check (public.can_approve_spares() or public.is_spare_requester(spare_requests));

-- ---------------------------------------------------------------------------
-- Stage guard, extended. Keeps 0008's per-stage column rules and adds:
--   • the receipt columns, which need spare.receive AND being the raiser;
--   • courier / dispatch_remarks, which belong to the dispatch stage;
--   • reject_reason / rejected_stage, which only an approver may write;
--   • the Received stage transition, which the raiser may make.
-- ---------------------------------------------------------------------------
create or replace function public.spare_requests_stage_guard()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  changed boolean;
begin
  if public.is_admin() then return new; end if;

  changed := new.rm_approval is distinct from old.rm_approval
          or new.rm_by       is distinct from old.rm_by
          or new.rm_at       is distinct from old.rm_at;
  if changed and not public.has_perm('spare.approve_rm') then
    raise exception 'RBAC: RM approval requires the spare.approve_rm permission';
  end if;

  changed := new.commercial_approval is distinct from old.commercial_approval
          or new.commercial_by       is distinct from old.commercial_by
          or new.commercial_at       is distinct from old.commercial_at;
  if changed and not public.has_perm('spare.approve_commercial') then
    raise exception 'RBAC: Commercial approval requires the spare.approve_commercial permission';
  end if;

  changed := new.nsm_approval is distinct from old.nsm_approval
          or new.nsm_by       is distinct from old.nsm_by
          or new.nsm_at       is distinct from old.nsm_at;
  if changed and not public.has_perm('spare.approve_nsm') then
    raise exception 'RBAC: NSM approval requires the spare.approve_nsm permission';
  end if;

  changed := new.stores_status    is distinct from old.stores_status
          or new.dc_number        is distinct from old.dc_number
          or new.dispatched_by    is distinct from old.dispatched_by
          or new.dispatched_at    is distinct from old.dispatched_at
          or new.courier          is distinct from old.courier
          or new.dispatch_remarks is distinct from old.dispatch_remarks;
  if changed and not public.has_perm('spare.dispatch') then
    raise exception 'RBAC: dispatch / DC requires the spare.dispatch permission';
  end if;

  -- A rejection reason is only meaningful from whoever rejected the request.
  changed := new.reject_reason  is distinct from old.reject_reason
          or new.rejected_stage is distinct from old.rejected_stage;
  if changed and not public.can_approve_spares() then
    raise exception 'RBAC: recording a rejection requires an approval permission';
  end if;

  -- Receipt: the engineer who raised the request acknowledges the parts.
  changed := new.received_by     is distinct from old.received_by
          or new.received_at     is distinct from old.received_at
          or new.receipt_remarks is distinct from old.receipt_remarks;
  if changed then
    if not public.has_perm('spare.receive') then
      raise exception 'RBAC: acknowledging receipt requires the spare.receive permission';
    end if;
    if not public.is_spare_requester(old) then
      raise exception 'RBAC: only the engineer who raised the request may acknowledge it';
    end if;
    if old.stores_status is null or old.stores_status !~* 'dispatch' then
      raise exception 'RBAC: a request can only be acknowledged after it is dispatched';
    end if;
  end if;

  -- The workflow stage moves as a side effect of an approval, or of the
  -- raiser acknowledging receipt.
  if new.stage is distinct from old.stage
     and not public.can_approve_spares()
     and not (new.stage = 'Received' and public.has_perm('spare.receive') and public.is_spare_requester(old)) then
    raise exception 'RBAC: advancing the approval stage requires an approval permission';
  end if;

  return new;
end $$;

drop trigger if exists spare_requests_stage_guard on public.spare_requests;
create trigger spare_requests_stage_guard
  before update on public.spare_requests
  for each row execute function public.spare_requests_stage_guard();

-- ---------------------------------------------------------------------------
-- has_perm() reads app_roles, and 0008's seed deliberately leaves an existing
-- role's permissions alone — so spare.receive, which did not exist then, is on
-- no role. Append it to the roles that raise or handle requests, without
-- disturbing any other permission an admin has since edited.
-- ---------------------------------------------------------------------------
update public.app_roles
   set permissions = coalesce(permissions, '[]'::jsonb) || '["spare.receive"]'::jsonb,
       updated_at  = now()
 where role in ('admin', 'engineer', 'rm', 'rgm', 'spare_coordinator')
   and not coalesce(permissions, '[]'::jsonb) ? 'spare.receive';

-- ------------------------------------------------------------------------
-- 0011_spare_intake.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Spare request intake — the register's own numbering and dates.
--   • OR NO: a running number per request, starting at OR47042.
--   • RowNo: the part's position within its request, restarting at 1 per OR.
--   • OR Req Date: today's date; TimeStamp is the existing created_at.
--   • Qty is at least 1, and a request carries at most 20 parts.
-- ===========================================================================

alter table public.spare_requests
  add column if not exists or_no       text,
  add column if not exists or_req_date date;

alter table public.spare_request_lines
  add column if not exists row_no int;

create unique index if not exists spare_requests_or_no_idx on public.spare_requests (or_no);
create index if not exists spare_request_lines_request_uid_idx on public.spare_request_lines (request_uid);

-- ---------------------------------------------------------------------------
-- OR numbers continue the sheet's series, which had reached OR47042.
-- ---------------------------------------------------------------------------
create sequence if not exists public.spare_or_no_seq as bigint start with 47042 minvalue 47042;

-- If rows were already imported, start the sequence past the highest OR number
-- present so a re-run never hands out one that is taken.
do $$
declare hi bigint;
begin
  select max((regexp_replace(or_no, '\D', '', 'g'))::bigint) into hi
    from public.spare_requests where or_no ~ '^OR\d+$';
  if hi is not null and hi >= 47042 then
    perform setval('public.spare_or_no_seq', hi + 1, false);
  end if;
end $$;

create or replace function public.spare_requests_assign_or_no()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.or_no is null or trim(new.or_no) = '' then
    new.or_no := 'OR' || nextval('public.spare_or_no_seq');
  end if;
  if new.or_req_date is null then
    new.or_req_date := current_date;
  end if;
  return new;
end $$;

drop trigger if exists spare_requests_assign_or_no on public.spare_requests;
create trigger spare_requests_assign_or_no
  before insert on public.spare_requests
  for each row execute function public.spare_requests_assign_or_no();

-- The OR number and its date identify the request downstream (DC, stores,
-- Tally), so they are assigned once and then fixed.
create or replace function public.spare_requests_number_immutable()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if public.is_admin() then return new; end if;
  if new.or_no is distinct from old.or_no then
    raise exception 'The OR number is assigned once and cannot be changed';
  end if;
  if new.or_req_date is distinct from old.or_req_date then
    raise exception 'The OR request date is assigned once and cannot be changed';
  end if;
  return new;
end $$;

drop trigger if exists spare_requests_number_immutable on public.spare_requests;
create trigger spare_requests_number_immutable
  before update on public.spare_requests
  for each row execute function public.spare_requests_number_immutable();

-- ---------------------------------------------------------------------------
-- RowNo restarts at 1 for each OR, and a request carries at most 20 parts.
-- ---------------------------------------------------------------------------
create or replace function public.spare_request_lines_assign_row_no()
returns trigger language plpgsql security definer set search_path = public as $$
declare next_no int;
begin
  if coalesce(new.qty, 0) < 1 then
    raise exception 'Quantity must be at least 1';
  end if;
  if new.row_no is null then
    select coalesce(max(row_no), 0) + 1 into next_no
      from public.spare_request_lines where request_uid = new.request_uid;
    new.row_no := next_no;
  end if;
  if new.row_no > 20 then
    raise exception 'A spare request may carry at most 20 parts';
  end if;
  return new;
end $$;

drop trigger if exists spare_request_lines_assign_row_no on public.spare_request_lines;
create trigger spare_request_lines_assign_row_no
  before insert on public.spare_request_lines
  for each row execute function public.spare_request_lines_assign_row_no();

-- Backfill anything already loaded, so old rows sort alongside new ones.
update public.spare_requests
   set or_req_date = created_at::date
 where or_req_date is null;

with numbered as (
  select id, row_number() over (partition by request_uid order by id) as rn
    from public.spare_request_lines where row_no is null
)
update public.spare_request_lines l
   set row_no = numbered.rn
  from numbered where numbered.id = l.id;

-- ---------------------------------------------------------------------------
-- A request is its parts: if the lines fail to insert, the client deletes the
-- header it just created rather than leaving a partial record (and a burnt OR
-- number) behind. No DELETE policy existed, so that cleanup silently did
-- nothing. Allow it only while the approval chain has not touched the request.
-- ---------------------------------------------------------------------------
drop policy if exists sr_delete on public.spare_requests;
create policy sr_delete on public.spare_requests for delete
  using (
    (public.is_admin() or public.is_spare_requester(spare_requests))
    and coalesce(stage, 'RM Approval') = 'RM Approval'
    and coalesce(rm_approval, 'Pending') = 'Pending'
    and received_at is null
  );

-- ------------------------------------------------------------------------
-- 0012_spare_auto_approval.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Fix: the RM's approval of a non-AMC/OGP item is refused by the stage guard.
--
-- The business rule is that Commercial and NSM only review AMC or OGP items;
-- for anything else they auto-approve. The app implements that by writing
-- commercial_approval / nsm_approval = 'Auto-Approved' in the SAME update that
-- records the RM's approval (src/lib/spareflow.ts, buildPatch).
--
-- 0008_rbac_enforcement.sql's guard sees those columns change and demands
-- spare.approve_commercial / spare.approve_nsm, which an RM does not hold — so
-- the whole update is rejected and the common path cannot be approved at all.
--
-- The guard is reissued here allowing exactly that case: the auto-approval
-- literal, written by someone who may approve at the RM stage, on an item that
-- is not AMC or OGP. A manual 'Approved' still needs the stage's own action.
-- ===========================================================================

create or replace function public.spare_needs_review(item_status text)
returns boolean language sql immutable as $$
  select coalesce(trim(item_status), '') ~* '^(amc|ogp)$';
$$;
grant execute on function public.spare_needs_review(text) to authenticated;

create or replace function public.spare_requests_stage_guard()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  changed   boolean;
  auto_ok   boolean;
begin
  if public.is_admin() then return new; end if;

  -- Commercial and NSM auto-approve alongside the RM's approval when the item
  -- needs no review. Anyone who may approve at the RM stage may write that.
  auto_ok := not public.spare_needs_review(new.item_status)
             and public.has_perm('spare.approve_rm');

  changed := new.rm_approval is distinct from old.rm_approval
          or new.rm_by       is distinct from old.rm_by
          or new.rm_at       is distinct from old.rm_at;
  if changed and not public.has_perm('spare.approve_rm') then
    raise exception 'RBAC: RM approval requires the spare.approve_rm permission';
  end if;

  changed := new.commercial_approval is distinct from old.commercial_approval
          or new.commercial_by       is distinct from old.commercial_by
          or new.commercial_at       is distinct from old.commercial_at;
  if changed
     and not public.has_perm('spare.approve_commercial')
     and not (auto_ok and new.commercial_approval = 'Auto-Approved'
              and new.commercial_by is not distinct from old.commercial_by
              and new.commercial_at is not distinct from old.commercial_at) then
    raise exception 'RBAC: Commercial approval requires the spare.approve_commercial permission';
  end if;

  changed := new.nsm_approval is distinct from old.nsm_approval
          or new.nsm_by       is distinct from old.nsm_by
          or new.nsm_at       is distinct from old.nsm_at;
  if changed
     and not public.has_perm('spare.approve_nsm')
     and not (auto_ok and new.nsm_approval = 'Auto-Approved'
              and new.nsm_by is not distinct from old.nsm_by
              and new.nsm_at is not distinct from old.nsm_at) then
    raise exception 'RBAC: NSM approval requires the spare.approve_nsm permission';
  end if;

  changed := new.stores_status    is distinct from old.stores_status
          or new.dc_number        is distinct from old.dc_number
          or new.dispatched_by    is distinct from old.dispatched_by
          or new.dispatched_at    is distinct from old.dispatched_at
          or new.courier          is distinct from old.courier
          or new.dispatch_remarks is distinct from old.dispatch_remarks;
  if changed and not public.has_perm('spare.dispatch') then
    raise exception 'RBAC: dispatch / DC requires the spare.dispatch permission';
  end if;

  changed := new.reject_reason  is distinct from old.reject_reason
          or new.rejected_stage is distinct from old.rejected_stage;
  if changed and not public.can_approve_spares() then
    raise exception 'RBAC: recording a rejection requires an approval permission';
  end if;

  changed := new.received_by     is distinct from old.received_by
          or new.received_at     is distinct from old.received_at
          or new.receipt_remarks is distinct from old.receipt_remarks;
  if changed then
    if not public.has_perm('spare.receive') then
      raise exception 'RBAC: acknowledging receipt requires the spare.receive permission';
    end if;
    if not public.is_spare_requester(old) then
      raise exception 'RBAC: only the engineer who raised the request may acknowledge it';
    end if;
    if old.stores_status is null or old.stores_status !~* 'dispatch' then
      raise exception 'RBAC: a request can only be acknowledged after it is dispatched';
    end if;
  end if;

  if new.stage is distinct from old.stage
     and not public.can_approve_spares()
     and not (new.stage = 'Received' and public.has_perm('spare.receive') and public.is_spare_requester(old)) then
    raise exception 'RBAC: advancing the approval stage requires an approval permission';
  end if;

  return new;
end $$;

-- ------------------------------------------------------------------------
-- 0016_spare_line_approvals.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Spare approvals move from the REQUEST to the LINE.
--
-- The RM must decide each spare individually — a request for five parts may
-- warrant three of them — so the approval state belongs on spare_request_lines,
-- not on the request header. The later stages (Commercial, NSM, Stores,
-- receipt) also live on the line, which is what lets them be actioned either
-- per spare or, by updating every open line of a request at once, per OR.
--
-- The request header keeps stage/status as a ROLL-UP of its lines, maintained
-- by trigger, so existing reads and filters stay meaningful. Nothing writes
-- those columns directly any more.
-- ===========================================================================

alter table public.spare_request_lines
  add column if not exists rm_by               text,
  add column if not exists rm_at               timestamptz,
  add column if not exists commercial_approval text default 'Pending',
  add column if not exists commercial_by       text,
  add column if not exists commercial_at       timestamptz,
  add column if not exists nsm_approval        text default 'Pending',
  add column if not exists nsm_by              text,
  add column if not exists nsm_at              timestamptz,
  add column if not exists dc_number           text,
  add column if not exists courier             text,
  add column if not exists dispatch_remarks    text,
  add column if not exists dispatched_by       text,
  add column if not exists dispatched_at       timestamptz,
  add column if not exists received_by         text,
  add column if not exists received_at         timestamptz,
  add column if not exists receipt_remarks     text,
  add column if not exists reject_reason       text,
  add column if not exists rejected_stage      text,
  add column if not exists stage               text default 'RM Approval';

-- Everything below writes data. The RBAC guard installed at the end of this
-- migration is dropped first: these are data migrations, not somebody
-- approving spares, and they must not be judged against whoever is running
-- them. In the Supabase SQL Editor auth.uid() is NULL, so is_admin() is false
-- and every stage check would refuse. Recreating the guard at the end also
-- makes this migration safe to re-run.
drop trigger if exists spare_request_lines_guard on public.spare_request_lines;

-- rm_approval / stores_status / status already exist on the line (0001) but
-- were never used; normalise them (and the column defaults) to the header's
-- vocabulary, so new lines need no normalising on a later re-run.
alter table public.spare_request_lines alter column rm_approval   set default 'Pending';
alter table public.spare_request_lines alter column stores_status set default 'Pending';
update public.spare_request_lines set rm_approval   = 'Pending' where coalesce(rm_approval, '') = '';
update public.spare_request_lines set stores_status = 'Pending' where coalesce(stores_status, '') = '';

-- ---------------------------------------------------------------------------
-- Carry each existing request's decisions down onto its lines, so requests
-- already part-way through the chain keep their state.
-- ---------------------------------------------------------------------------
update public.spare_request_lines l
   set rm_approval         = coalesce(nullif(r.rm_approval, ''), l.rm_approval),
       rm_by               = coalesce(l.rm_by, r.rm_by),
       rm_at               = coalesce(l.rm_at, r.rm_at),
       commercial_approval = coalesce(nullif(r.commercial_approval, ''), l.commercial_approval),
       commercial_by       = coalesce(l.commercial_by, r.commercial_by),
       commercial_at       = coalesce(l.commercial_at, r.commercial_at),
       nsm_approval        = coalesce(nullif(r.nsm_approval, ''), l.nsm_approval),
       nsm_by              = coalesce(l.nsm_by, r.nsm_by),
       nsm_at              = coalesce(l.nsm_at, r.nsm_at),
       stores_status       = coalesce(nullif(r.stores_status, ''), l.stores_status),
       dc_number           = coalesce(l.dc_number, r.dc_number),
       courier             = coalesce(l.courier, r.courier),
       dispatch_remarks    = coalesce(l.dispatch_remarks, r.dispatch_remarks),
       dispatched_by       = coalesce(l.dispatched_by, r.dispatched_by),
       dispatched_at       = coalesce(l.dispatched_at, r.dispatched_at),
       received_by         = coalesce(l.received_by, r.received_by),
       received_at         = coalesce(l.received_at, r.received_at),
       receipt_remarks     = coalesce(l.receipt_remarks, r.receipt_remarks),
       reject_reason       = coalesce(l.reject_reason, r.reject_reason),
       rejected_stage      = coalesce(l.rejected_stage, r.rejected_stage),
       stage               = coalesce(nullif(r.stage, ''), l.stage)
  from public.spare_requests r
 where r.uid = l.request_uid
   and l.rm_at is null;   -- only lines never decided on their own

-- ---------------------------------------------------------------------------
-- One line's stage — the same rule the app applies (src/lib/spareflow.ts).
-- ---------------------------------------------------------------------------
create or replace function public.spare_line_stage(
  rm text, commercial text, nsm text, stores text, received timestamptz, item_status text
) returns text language sql immutable as $$
  select case
    when rm ~* 'reject' or commercial ~* 'reject' or nsm ~* 'reject' then 'Rejected'
    when received is not null                                        then 'Received'
    when stores ~* 'dispatch'                                        then 'Dispatched'
    when rm !~* 'approv|auto'                                        then 'RM Approval'
    when public.spare_needs_review(item_status)
     and commercial !~* 'approv|auto'                                then 'Commercial'
    when public.spare_needs_review(item_status)
     and nsm !~* 'approv|auto'                                       then 'NSM'
    else 'Stores'
  end;
$$;
grant execute on function public.spare_line_stage(text, text, text, text, timestamptz, text) to authenticated;

-- ---------------------------------------------------------------------------
-- Keep each line's own stage column current.
-- ---------------------------------------------------------------------------
create or replace function public.spare_request_lines_set_stage()
returns trigger language plpgsql security definer set search_path = public as $$
declare item text;
begin
  select r.item_status into item from public.spare_requests r where r.uid = new.request_uid;
  new.stage := public.spare_line_stage(
    coalesce(new.rm_approval, 'Pending'), coalesce(new.commercial_approval, 'Pending'),
    coalesce(new.nsm_approval, 'Pending'), coalesce(new.stores_status, 'Pending'),
    new.received_at, item);
  new.status := new.stage;
  return new;
end $$;

drop trigger if exists spare_request_lines_set_stage on public.spare_request_lines;
create trigger spare_request_lines_set_stage
  before insert or update on public.spare_request_lines
  for each row execute function public.spare_request_lines_set_stage();

-- ---------------------------------------------------------------------------
-- Roll the lines up onto the request: the least-advanced stage among the lines
-- still alive, or Rejected when every line was rejected.
-- ---------------------------------------------------------------------------
create or replace function public.spare_request_rollup(p_uid text)
returns void language plpgsql security definer set search_path = public as $$
declare roll text;
begin
  select case
           when count(*) = 0                              then 'RM Approval'
           when count(*) filter (where stage <> 'Rejected') = 0 then 'Rejected'
           else min(case stage
                      when 'RM Approval' then 1 when 'Commercial' then 2
                      when 'NSM'         then 3 when 'Stores'     then 4
                      when 'Dispatched'  then 5 when 'Received'   then 6
                    end) filter (where stage <> 'Rejected')::text
         end
    into roll
    from public.spare_request_lines where request_uid = p_uid;

  roll := coalesce(case roll
            when '1' then 'RM Approval' when '2' then 'Commercial'
            when '3' then 'NSM'         when '4' then 'Stores'
            when '5' then 'Dispatched'  when '6' then 'Received'
            else roll end, 'RM Approval');

  -- Written by this function only; the header guard below allows it via a flag.
  perform set_config('app.spare_rollup', '1', true);
  update public.spare_requests
     set stage  = roll,
         status = case when roll = 'Stores' then 'Awaiting Dispatch' else roll end
   where uid = p_uid and (stage is distinct from roll);
  perform set_config('app.spare_rollup', '', true);
end $$;

create or replace function public.spare_request_lines_rollup()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  perform public.spare_request_rollup(coalesce(new.request_uid, old.request_uid));
  return null;
end $$;

drop trigger if exists spare_request_lines_rollup on public.spare_request_lines;
create trigger spare_request_lines_rollup
  after insert or update or delete on public.spare_request_lines
  for each row execute function public.spare_request_lines_rollup();

-- ---------------------------------------------------------------------------
-- The per-stage guard moves to the line. Same rules as 0012 held on the
-- header: each stage's columns may only change if the actor holds that stage's
-- action; Commercial/NSM auto-approve alongside the RM on a non-AMC item; the
-- receipt needs spare.receive, the raiser, and a dispatched line.
-- ---------------------------------------------------------------------------
create or replace function public.spare_request_lines_guard()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  changed boolean;
  auto_ok boolean;
  req     public.spare_requests;
begin
  if public.is_admin() then return new; end if;
  select * into req from public.spare_requests where uid = new.request_uid;

  auto_ok := not public.spare_needs_review(req.item_status)
             and public.has_perm('spare.approve_rm');

  changed := new.rm_approval is distinct from old.rm_approval
          or new.rm_by       is distinct from old.rm_by
          or new.rm_at       is distinct from old.rm_at;
  if changed and not public.has_perm('spare.approve_rm') then
    raise exception 'RBAC: RM approval requires the spare.approve_rm permission';
  end if;

  changed := new.commercial_approval is distinct from old.commercial_approval
          or new.commercial_by       is distinct from old.commercial_by
          or new.commercial_at       is distinct from old.commercial_at;
  if changed
     and not public.has_perm('spare.approve_commercial')
     and not (auto_ok and new.commercial_approval = 'Auto-Approved'
              and new.commercial_by is not distinct from old.commercial_by) then
    raise exception 'RBAC: Commercial approval requires the spare.approve_commercial permission';
  end if;

  changed := new.nsm_approval is distinct from old.nsm_approval
          or new.nsm_by       is distinct from old.nsm_by
          or new.nsm_at       is distinct from old.nsm_at;
  if changed
     and not public.has_perm('spare.approve_nsm')
     and not (auto_ok and new.nsm_approval = 'Auto-Approved'
              and new.nsm_by is not distinct from old.nsm_by) then
    raise exception 'RBAC: NSM approval requires the spare.approve_nsm permission';
  end if;

  changed := new.stores_status    is distinct from old.stores_status
          or new.dc_number        is distinct from old.dc_number
          or new.dispatched_by    is distinct from old.dispatched_by
          or new.dispatched_at    is distinct from old.dispatched_at
          or new.courier          is distinct from old.courier
          or new.dispatch_remarks is distinct from old.dispatch_remarks;
  if changed and not public.has_perm('spare.dispatch') then
    raise exception 'RBAC: dispatch / DC requires the spare.dispatch permission';
  end if;

  changed := new.reject_reason  is distinct from old.reject_reason
          or new.rejected_stage is distinct from old.rejected_stage;
  if changed and not public.can_approve_spares() then
    raise exception 'RBAC: recording a rejection requires an approval permission';
  end if;

  changed := new.received_by     is distinct from old.received_by
          or new.received_at     is distinct from old.received_at
          or new.receipt_remarks is distinct from old.receipt_remarks;
  if changed then
    if not public.has_perm('spare.receive') then
      raise exception 'RBAC: acknowledging receipt requires the spare.receive permission';
    end if;
    if not public.is_spare_requester(req) then
      raise exception 'RBAC: only the engineer who raised the request may acknowledge it';
    end if;
    if old.stores_status is null or old.stores_status !~* 'dispatch' then
      raise exception 'RBAC: a spare can only be acknowledged after it is dispatched';
    end if;
  end if;

  -- The part and quantity are the request; they are fixed once submitted.
  if (new.part is distinct from old.part or new.qty is distinct from old.qty)
     and not public.is_spare_requester(req) then
    raise exception 'RBAC: only the engineer who raised the request may change its parts';
  end if;

  return new;
end $$;

drop trigger if exists spare_request_lines_guard on public.spare_request_lines;
create trigger spare_request_lines_guard
  before update on public.spare_request_lines
  for each row execute function public.spare_request_lines_guard();

-- ---------------------------------------------------------------------------
-- The header no longer carries decisions. Its stage/status change only through
-- the roll-up; its approval columns are legacy and frozen for non-admins.
-- ---------------------------------------------------------------------------
create or replace function public.spare_requests_stage_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if public.is_admin() then return new; end if;
  if coalesce(current_setting('app.spare_rollup', true), '') = '1' then return new; end if;

  if new.stage  is distinct from old.stage
  or new.status is distinct from old.status
  or new.rm_approval         is distinct from old.rm_approval
  or new.commercial_approval is distinct from old.commercial_approval
  or new.nsm_approval        is distinct from old.nsm_approval
  or new.stores_status       is distinct from old.stores_status
  or new.received_at         is distinct from old.received_at then
    raise exception 'Spare approvals are recorded per spare — update spare_request_lines, not the request';
  end if;
  return new;
end $$;

-- ---------------------------------------------------------------------------
-- Approvers already update lines; the raiser must too, to acknowledge receipt.
-- ---------------------------------------------------------------------------
drop policy if exists srl_update on public.spare_request_lines;
create policy srl_update on public.spare_request_lines for update
  using (
    public.can_approve_spares()
    or exists (select 1 from public.spare_requests r
                where r.uid = spare_request_lines.request_uid and public.is_spare_requester(r))
  )
  with check (
    public.can_approve_spares()
    or exists (select 1 from public.spare_requests r
                where r.uid = spare_request_lines.request_uid and public.is_spare_requester(r))
  );

-- Bring every existing request's header into line with its lines.
do $$
declare u text;
begin
  for u in select uid from public.spare_requests loop
    perform public.spare_request_rollup(u);
  end loop;
end $$;

-- ------------------------------------------------------------------------
-- 0017_spare_or_number_monthly.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- OR numbers become OR-YY/MM/N, restarting at 1 every month.
--
-- 0011 issued a single running series (OR47042…) continuing the sheet's. The
-- required format is per-month instead: OR-26/08/1, OR-26/08/2, … and the
-- first request of September is OR-26/09/1.
--
-- Numbers already issued are NOT rewritten — they are quoted on DCs and in
-- Tally, so the old series stays as history and the new format starts here.
-- ===========================================================================

-- One counter per YY/MM period. Written only by next_spare_or_no().
create table if not exists public.spare_or_counters (
  period  text primary key,          -- 'YY/MM', e.g. '26/08'
  last_no integer not null default 0
);
alter table public.spare_or_counters enable row level security;  -- definer-only

-- Hand out the next number for a month. The upsert is atomic, so two requests
-- submitted at the same moment cannot take the same number.
create or replace function public.next_spare_or_no(p_on date default current_date)
returns text language plpgsql security definer set search_path = public as $$
declare
  p text := to_char(p_on, 'YY/MM');
  n integer;
begin
  insert into public.spare_or_counters (period, last_no) values (p, 1)
  on conflict (period) do update set last_no = public.spare_or_counters.last_no + 1
  returning last_no into n;
  return 'OR-' || p || '/' || n;
end $$;
grant execute on function public.next_spare_or_no(date) to authenticated;

-- If this month already has numbers in the new format (a re-run, or a partial
-- rollout), continue past the highest rather than colliding with it.
insert into public.spare_or_counters (period, last_no)
select to_char(coalesce(or_req_date, created_at::date), 'YY/MM'),
       max((regexp_replace(or_no, '^OR-\d\d/\d\d/', ''))::integer)
  from public.spare_requests
 where or_no ~ '^OR-\d\d/\d\d/\d+$'
 group by 1
on conflict (period) do update
  set last_no = greatest(public.spare_or_counters.last_no, excluded.last_no);

create or replace function public.spare_requests_assign_or_no()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.or_req_date is null then
    new.or_req_date := current_date;
  end if;
  if new.or_no is null or trim(new.or_no) = '' then
    -- Numbered in the month the request is raised in.
    new.or_no := public.next_spare_or_no(new.or_req_date);
  end if;
  return new;
end $$;

-- The old single running series is no longer used by anything.
drop sequence if exists public.spare_or_no_seq;

-- ------------------------------------------------------------------------
-- 0018_spare_or_number_padded.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- OR numbers pad the counter to three digits: OR-26/08/001.
--
-- 0017 wrote the counter bare (OR-26/08/1), which sorts wrongly as text once a
-- month passes nine requests — OR-26/08/10 lands before OR-26/08/2 in the
-- register and in CSV exports. Three digits sorts correctly to 999 a month.
--
-- Past 999 the number simply grows (OR-26/08/1000) and text ordering breaks
-- again at that point; no month is expected to come close.
-- ===========================================================================

create or replace function public.next_spare_or_no(p_on date default current_date)
returns text language plpgsql security definer set search_path = public as $$
declare
  p text := to_char(p_on, 'YY/MM');
  n integer;
begin
  insert into public.spare_or_counters (period, last_no) values (p, 1)
  on conflict (period) do update set last_no = public.spare_or_counters.last_no + 1
  returning last_no into n;
  return 'OR-' || p || '/' || lpad(n::text, 3, '0');
end $$;

-- ---------------------------------------------------------------------------
-- Restate the few numbers 0017 issued unpadded. This is the same number in the
-- required format, not a renumbering: OR-26/08/1 becomes OR-26/08/001, same
-- month, same position in the series. The unpadded form was only ever live
-- between 0017 and this migration.
--
-- The immutability trigger is dropped first: it refuses any or_no change from
-- a non-admin, and in the Supabase SQL Editor auth.uid() is NULL so is_admin()
-- is false. It is recreated below, which also makes this safe to re-run.
-- ---------------------------------------------------------------------------
drop trigger if exists spare_requests_number_immutable on public.spare_requests;

update public.spare_requests r
   set or_no = 'OR-' || substring(or_no from 4 for 5) || '/'
               || lpad(substring(or_no from 10), 3, '0')
 where or_no ~ '^OR-\d\d/\d\d/\d{1,2}$'
   -- never write over a number that already exists in the padded form
   and not exists (
     select 1 from public.spare_requests x
      where x.or_no = 'OR-' || substring(r.or_no from 4 for 5) || '/'
                      || lpad(substring(r.or_no from 10), 3, '0')
        and x.uid <> r.uid);

create trigger spare_requests_number_immutable
  before update on public.spare_requests
  for each row execute function public.spare_requests_number_immutable();

-- Re-seed the counters from the padded numbers, so a re-run cannot hand out
-- one that is taken (0017's seeding only matched the unpadded form).
insert into public.spare_or_counters (period, last_no)
select to_char(coalesce(or_req_date, created_at::date), 'YY/MM'),
       max((regexp_replace(or_no, '^OR-\d\d/\d\d/', ''))::integer)
  from public.spare_requests
 where or_no ~ '^OR-\d\d/\d\d/\d+$'
 group by 1
on conflict (period) do update
  set last_no = greatest(public.spare_or_counters.last_no, excluded.last_no);

-- ------------------------------------------------------------------------
-- 0019_spare_or_number_format.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- OR numbers become OR-YYMM-NNNN: OR-2608-0001.
--
-- Third and final shape for this identifier:
--   0017  OR-26/08/1     monthly series, bare counter
--   0018  OR-26/08/001   padded to three
--   0019  OR-2608-0001   slashes replaced by a dash, counter padded to four
--
-- Still one series per month, restarting at 0001. Four digits sorts correctly
-- to 9999 a month, which no month will approach.
--
-- Numbers from the ORIGINAL sheet series (OR47042…) are left alone — they are
-- quoted on DCs and in Tally. The OR-26/08/… forms only ever existed between
-- these migrations, so they are restated into the new shape.
-- ===========================================================================

create or replace function public.next_spare_or_no(p_on date default current_date)
returns text language plpgsql security definer set search_path = public as $$
declare
  p text := to_char(p_on, 'YY/MM');   -- counters stay keyed by YY/MM
  n integer;
begin
  insert into public.spare_or_counters (period, last_no) values (p, 1)
  on conflict (period) do update set last_no = public.spare_or_counters.last_no + 1
  returning last_no into n;
  return 'OR-' || to_char(p_on, 'YYMM') || '-' || lpad(n::text, 4, '0');
end $$;

-- ---------------------------------------------------------------------------
-- Restate the slashed numbers. Same month, same position in the series — only
-- the rendering changes.
--
-- The immutability trigger is dropped first: it refuses any or_no change from
-- a non-admin, and in the Supabase SQL Editor auth.uid() is NULL so is_admin()
-- is false. Recreated below, which also makes this safe to re-run.
-- ---------------------------------------------------------------------------
drop trigger if exists spare_requests_number_immutable on public.spare_requests;

update public.spare_requests r
   set or_no = 'OR-' || substring(or_no from 4 for 2) || substring(or_no from 7 for 2)
               || '-' || lpad(regexp_replace(or_no, '^OR-\d\d/\d\d/', ''), 4, '0')
 where or_no ~ '^OR-\d\d/\d\d/\d+$'
   and not exists (
     select 1 from public.spare_requests x
      where x.or_no = 'OR-' || substring(r.or_no from 4 for 2) || substring(r.or_no from 7 for 2)
                      || '-' || lpad(regexp_replace(r.or_no, '^OR-\d\d/\d\d/', ''), 4, '0')
        and x.uid <> r.uid);

create trigger spare_requests_number_immutable
  before update on public.spare_requests
  for each row execute function public.spare_requests_number_immutable();

-- Re-seed the counters from the new shape, so a re-run cannot reissue a number
-- that is taken (earlier seeding only matched the slashed forms).
insert into public.spare_or_counters (period, last_no)
select substring(or_no from 4 for 2) || '/' || substring(or_no from 6 for 2),
       max((regexp_replace(or_no, '^OR-\d{4}-', ''))::integer)
  from public.spare_requests
 where or_no ~ '^OR-\d{4}-\d+$'
 group by 1
on conflict (period) do update
  set last_no = greatest(public.spare_or_counters.last_no, excluded.last_no);

-- ------------------------------------------------------------------------
-- 0022_spare_line_uid.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Every spare gets its own ID: <OR number>-<RowNo>, e.g. OR-2608-0001-01.
--
-- The approval chain has been per-spare since 0016 — each line carries its own
-- RM decision, DC number and dispatch date, so two spares on one OR can be
-- dispatched days apart. What was missing is a stable identifier to quote for
-- one of them: the RM approves against it, Stores dispatches against it, and
-- it is what goes on the DC.
--
-- Derived from the OR number and the row's position, so it reads as the OR it
-- belongs to. Assigned once and then fixed, and unique across the register.
-- ===========================================================================

alter table public.spare_request_lines
  add column if not exists line_uid text;

-- Two digits is enough: a request carries at most 20 parts (0011).
create or replace function public.spare_line_uid(p_or_no text, p_row_no int)
returns text language sql immutable as $$
  select case
           when coalesce(trim(p_or_no), '') = '' or p_row_no is null then null
           else trim(p_or_no) || '-' || lpad(p_row_no::text, 2, '0')
         end;
$$;
grant execute on function public.spare_line_uid(text, int) to authenticated;

-- ---------------------------------------------------------------------------
-- Assigned on insert. The trigger name puts it after
-- spare_request_lines_assign_row_no (which sets row_no) and before
-- spare_request_lines_set_stage — BEFORE triggers fire in name order.
-- ---------------------------------------------------------------------------
create or replace function public.spare_request_lines_set_line_uid()
returns trigger language plpgsql security definer set search_path = public as $$
declare or_no text;
begin
  if new.line_uid is null or trim(new.line_uid) = '' then
    select r.or_no into or_no from public.spare_requests r where r.uid = new.request_uid;
    -- Requests imported before 0011 have no OR number; fall back to the UID so
    -- every line still has something unique to quote.
    new.line_uid := coalesce(public.spare_line_uid(or_no, new.row_no),
                             new.request_uid || '-' || lpad(coalesce(new.row_no, 1)::text, 2, '0'));
  end if;
  return new;
end $$;

drop trigger if exists spare_request_lines_line_uid on public.spare_request_lines;
create trigger spare_request_lines_line_uid
  before insert on public.spare_request_lines
  for each row execute function public.spare_request_lines_set_line_uid();

-- ---------------------------------------------------------------------------
-- Backfill. The RBAC guard is dropped around it: this is a data migration, and
-- in the SQL Editor auth.uid() is NULL so is_admin() is false and the guard
-- would judge it as an ordinary edit. Recreated after, which also makes this
-- migration safe to re-run.
-- ---------------------------------------------------------------------------
drop trigger if exists spare_request_lines_guard on public.spare_request_lines;

update public.spare_request_lines l
   set line_uid = coalesce(public.spare_line_uid(r.or_no, l.row_no),
                           l.request_uid || '-' || lpad(coalesce(l.row_no, 1)::text, 2, '0'))
  from public.spare_requests r
 where r.uid = l.request_uid
   and coalesce(l.line_uid, '') = '';

create trigger spare_request_lines_guard
  before update on public.spare_request_lines
  for each row execute function public.spare_request_lines_guard();

create unique index if not exists spare_request_lines_line_uid_idx
  on public.spare_request_lines (line_uid);

-- The ID is quoted on the DC and in the approval trail, so it is fixed once
-- assigned — like the OR number it derives from.
create or replace function public.spare_request_lines_uid_immutable()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if public.is_admin() then return new; end if;
  if new.line_uid is distinct from old.line_uid then
    raise exception 'The spare ID is assigned once and cannot be changed';
  end if;
  if new.row_no is distinct from old.row_no then
    raise exception 'The spare row number is assigned once and cannot be changed';
  end if;
  return new;
end $$;

drop trigger if exists spare_request_lines_uid_immutable on public.spare_request_lines;
create trigger spare_request_lines_uid_immutable
  before update on public.spare_request_lines
  for each row execute function public.spare_request_lines_uid_immutable();

-- ------------------------------------------------------------------------
-- 0025_spare_dropped_stage.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Dropped — a spare Stores did not send.
--
-- Stores can drop a line instead of dispatching it (short supply, part no
-- longer needed, superseded). That is a different outcome from a rejection:
-- an approver refuses the request, Stores drops a part that was already
-- approved. The imported history carries 272 of them, 254 approved by the RM
-- first, so folding them into Rejected would misreport who ended the line.
--
-- Terminal, like Dispatched and Rejected. Checked after Rejected: if an
-- approver refused the line, that decision is the one that closed it.
-- ===========================================================================

create or replace function public.spare_line_stage(
  rm text, commercial text, nsm text, stores text, received timestamptz, item_status text
) returns text language sql immutable as $$
  select case
    when rm ~* 'reject' or commercial ~* 'reject' or nsm ~* 'reject' then 'Rejected'
    when received is not null                                        then 'Received'
    when stores ~* 'drop'                                            then 'Dropped'
    when stores ~* 'dispatch'                                        then 'Dispatched'
    when rm !~* 'approv|auto'                                        then 'RM Approval'
    when public.spare_needs_review(item_status)
     and commercial !~* 'approv|auto'                                then 'Commercial'
    when public.spare_needs_review(item_status)
     and nsm !~* 'approv|auto'                                       then 'NSM'
    else 'Stores'
  end;
$$;

-- The request's rolled-up stage: a dropped line is closed, so it no longer
-- holds the request open. A request is Dropped only when every line is.
create or replace function public.spare_request_rollup(p_uid text)
returns void language plpgsql security definer set search_path = public as $$
declare roll text;
begin
  select case
           when count(*) = 0 then 'RM Approval'
           when count(*) filter (where stage not in ('Rejected', 'Dropped')) = 0
             then case when count(*) filter (where stage = 'Dropped') > 0
                       then 'Dropped' else 'Rejected' end
           else min(case stage
                      when 'RM Approval' then 1 when 'Commercial' then 2
                      when 'NSM'         then 3 when 'Stores'     then 4
                      when 'Dispatched'  then 5 when 'Received'   then 6
                    end) filter (where stage not in ('Rejected', 'Dropped'))::text
         end
    into roll
    from public.spare_request_lines where request_uid = p_uid;

  roll := coalesce(case roll
            when '1' then 'RM Approval' when '2' then 'Commercial'
            when '3' then 'NSM'         when '4' then 'Stores'
            when '5' then 'Dispatched'  when '6' then 'Received'
            else roll end, 'RM Approval');

  perform set_config('app.spare_rollup', '1', true);
  update public.spare_requests
     set stage  = roll,
         status = case when roll = 'Stores' then 'Awaiting Dispatch' else roll end
   where uid = p_uid and (stage is distinct from roll);
  perform set_config('app.spare_rollup', '', true);
end $$;

-- Recompute every line and request against the new rule. The RBAC guard is
-- dropped around it: this is a data migration, and in the SQL Editor
-- auth.uid() is NULL so is_admin() is false and the guard would refuse it.
drop trigger if exists spare_request_lines_guard on public.spare_request_lines;

update public.spare_request_lines l
   set stage = public.spare_line_stage(
                 coalesce(l.rm_approval, 'Pending'), coalesce(l.commercial_approval, 'Pending'),
                 coalesce(l.nsm_approval, 'Pending'), coalesce(l.stores_status, 'Pending'),
                 l.received_at, r.item_status),
       status = public.spare_line_stage(
                 coalesce(l.rm_approval, 'Pending'), coalesce(l.commercial_approval, 'Pending'),
                 coalesce(l.nsm_approval, 'Pending'), coalesce(l.stores_status, 'Pending'),
                 l.received_at, r.item_status)
  from public.spare_requests r
 where r.uid = l.request_uid;

create trigger spare_request_lines_guard
  before update on public.spare_request_lines
  for each row execute function public.spare_request_lines_guard();

do $$
declare u text;
begin
  for u in select uid from public.spare_requests loop
    perform public.spare_request_rollup(u);
  end loop;
end $$;

-- ------------------------------------------------------------------------
-- 0026_spare_approval_data.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Answers from the approval forms, kept whole.
--
-- The Commercial (formerly ADMIN) step is a branching form, not a yes/no:
-- a status, then either a clearing reason — with an MC/SA number or a
-- four-step Direct PO checklist behind it — or a pending reason. NSM's form
-- is the same shape.
--
-- Storing the answers as jsonb keyed by stage means the forms can gain or
-- lose questions without a migration each time, while the decision itself
-- stays in the columns the workflow already reads (commercial_approval and
-- friends), so nothing about stage derivation changes.
--
--   approval_data = { "commercial": { ... }, "nsm": { ... } }
-- ===========================================================================

alter table public.spare_request_lines
  add column if not exists approval_data jsonb not null default '{}'::jsonb;

-- Answers are gated like the decision they belong to: a Commercial answer
-- needs spare.approve_commercial, an NSM answer needs spare.approve_nsm.
-- A separate trigger from the stage guard, so that one stays untouched.
create or replace function public.spare_request_lines_answer_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if public.is_admin() then return new; end if;
  if new.approval_data is not distinct from old.approval_data then return new; end if;

  if new.approval_data -> 'commercial' is distinct from old.approval_data -> 'commercial'
     and not public.has_perm('spare.approve_commercial') then
    raise exception 'RBAC: recording a Commercial answer requires the spare.approve_commercial permission';
  end if;

  if new.approval_data -> 'nsm' is distinct from old.approval_data -> 'nsm'
     and not public.has_perm('spare.approve_nsm') then
    raise exception 'RBAC: recording an NSM answer requires the spare.approve_nsm permission';
  end if;

  -- Anything else under approval_data still needs a seat in the chain.
  if not public.can_approve_spares() then
    raise exception 'RBAC: recording an approval answer requires an approval permission';
  end if;
  return new;
end $$;

drop trigger if exists spare_request_lines_answer_guard on public.spare_request_lines;
create trigger spare_request_lines_answer_guard
  before update on public.spare_request_lines
  for each row execute function public.spare_request_lines_answer_guard();

-- Lines still sitting with Commercial because the answer was "Admin Process
-- in Progress" — the queue the team works from.
create index if not exists spare_request_lines_commercial_pending_idx
  on public.spare_request_lines ((approval_data -> 'commercial' ->> 'pending_reason'))
  where approval_data -> 'commercial' ->> 'pending_reason' is not null;

-- ------------------------------------------------------------------------
-- 0027_spare_dispatch.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Stores dispatch — one stock-out, many spares, one engineer.
--
-- Dispatch is decided per SPARE (0016), but it HAPPENS in batches: the Stores
-- incharge picks everything waiting for one engineer and books it out in one
-- go. That batch is a real document, so it gets a row of its own:
--
--   spare_dispatches   — one row per stock-out. Carries the STOCK OUT number
--                        and the DC number, both generated here, and the
--                        engineer everything in it is going to.
--   spare_request_lines.dispatch_uid / stock_out_no
--                      — the line's link back to it. dc_number already existed
--                        and keeps its meaning, so hand stock, the register,
--                        the trail and the imported history all still read.
--
-- Numbering follows the OR / ST convention already in the app — a monthly
-- counter, upserted atomically, so concurrent dispatches cannot collide:
--   SO-YYMM-NNNN   stock out
--   DC-YYMM-NNNN   delivery challan
--
-- NB: the DC FORMAT is still to be confirmed by the business. It is produced
-- in exactly one place — next_dc_number() — so changing it later is a one
-- function change and touches no other object.
--
-- Nothing here changes what a dispatch MEANS downstream: stores_status stays
-- 'Dispatched' and dispatched_at is still the moment it left, so
-- handstock_movements (0023) counts it as stock in the engineer's hands from
-- the stock-out, with no acknowledgement needed — which is what puts it in
-- the call report's spare-consumption picker.
-- ===========================================================================

alter table public.spare_request_lines
  add column if not exists dispatch_uid text,
  add column if not exists stock_out_no text;

create table if not exists public.spare_dispatches (
  id             bigint generated always as identity primary key,
  uid            text unique not null,           -- SO-YYMM-NNNN (stock out)
  dc_number      text,                           -- DC-YYMM-NNNN
  dc_date        date not null default current_date,
  engineer       text not null,
  engineer_email text default '',
  courier        text default '',
  remarks        text default '',
  line_count     integer not null default 0,
  total_qty      numeric not null default 0,
  dispatched_by  text default '',
  dispatched_at  timestamptz not null default now(),
  created_at     timestamptz not null default now(),
  created_by     uuid references auth.users (id) default auth.uid()
);
create index if not exists spare_dispatches_engineer_idx on public.spare_dispatches (lower(btrim(engineer)));
create index if not exists spare_dispatches_at_idx       on public.spare_dispatches (dispatched_at desc);
create index if not exists spare_request_lines_dispatch_uid_idx on public.spare_request_lines (dispatch_uid);

-- ---------------------------------------------------------------------------
-- Numbers. One counter table, two series, both restarting each month. The
-- upsert is what makes them safe under concurrency: the row is locked by the
-- ON CONFLICT, so two dispatchers in the same millisecond get 0007 and 0008,
-- never 0007 twice.
-- ---------------------------------------------------------------------------
create table if not exists public.spare_dispatch_counters (
  series  text not null,
  period  text not null,
  last_no integer not null default 0,
  primary key (series, period)
);
alter table public.spare_dispatch_counters enable row level security;  -- definer-only

create or replace function public.next_dispatch_no(p_series text, p_on date)
returns integer language plpgsql security definer set search_path = public as $$
declare n integer;
begin
  insert into public.spare_dispatch_counters (series, period, last_no)
       values (p_series, to_char(p_on, 'YYMM'), 1)
  on conflict (series, period)
    do update set last_no = public.spare_dispatch_counters.last_no + 1
  returning last_no into n;
  return n;
end $$;

create or replace function public.next_stock_out_no(p_on date default current_date)
returns text language sql security definer set search_path = public as $$
  select 'SO-' || to_char(p_on, 'YYMM') || '-'
      || lpad(public.next_dispatch_no('stock_out', p_on)::text, 4, '0');
$$;

-- The one place a DC number is made. Format pending business confirmation.
create or replace function public.next_dc_number(p_on date default current_date)
returns text language sql security definer set search_path = public as $$
  select 'DC-' || to_char(p_on, 'YYMM') || '-'
      || lpad(public.next_dispatch_no('dc', p_on)::text, 4, '0');
$$;

grant execute on function public.next_stock_out_no(date) to authenticated;
grant execute on function public.next_dc_number(date)    to authenticated;

create or replace function public.spare_dispatches_assign_no()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.dc_date is null then new.dc_date := current_date; end if;
  if new.uid is null or btrim(new.uid) = '' then
    new.uid := public.next_stock_out_no(new.dc_date);
  end if;
  if new.dc_number is null or btrim(new.dc_number) = '' then
    new.dc_number := public.next_dc_number(new.dc_date);
  end if;
  return new;
end $$;
drop trigger if exists spare_dispatches_assign_no on public.spare_dispatches;
create trigger spare_dispatches_assign_no
  before insert on public.spare_dispatches
  for each row execute function public.spare_dispatches_assign_no();

-- ---------------------------------------------------------------------------
-- What Stores is waiting to send. One row per spare that has cleared every
-- approval and has not been dispatched or dropped, with the engineer it is
-- going to — which is what the screen groups by.
--
-- security_invoker, so the rows a user sees are exactly the lines they may
-- already read in the register.
-- ---------------------------------------------------------------------------
-- Guarded: 0055_partial_dispatch.sql OWNS this view now and appended
-- requested_qty / dispatched_qty to it. `create or replace view` cannot drop
-- columns, so re-running this file over a fully-migrated project failed with
-- "cannot drop columns from view" and took the rest of all.sql down with it.
-- The later definition supersedes this one, so skipping is a no-op.
do $spd$
begin
  if exists (select 1 from information_schema.columns
              where table_schema = 'public' and table_name = 'spare_pending_dispatch'
                and column_name = 'dispatched_qty') then
    return;
  end if;

  execute $view$
    create or replace view public.spare_pending_dispatch as
    select
      l.id                                        as line_id,
      l.line_uid,
      l.request_uid,
      r.or_no,
      r.or_req_date,
      l.row_no,
      l.part,
      -- part_code() / handstock_key() (0023) say the same thing, but the hand
      -- stock module applies AFTER this one in all.sql — so the expressions are
      -- inlined rather than making the spare bundle depend on that one.
      upper(btrim(split_part(coalesce(l.part, ''), '|', 1)))
                                                  as part_code,
      l.qty,
      r.req_type,
      r.item_status,
      coalesce(r.engineer, '')                    as engineer,
      lower(btrim(coalesce(r.engineer, '')))      as engineer_key,
      coalesce(r.engineer_email, '')              as engineer_email,
      coalesce(r.ucn, '')                         as ucn,
      coalesce(r.call_number, '')                 as call_number,
      coalesce(r.party_name, '')                  as party_name,
      coalesce(r.product_name, '')                as product_name,
      coalesce(r.serial, '')                      as serial,
      coalesce(r.handstock_reason, '')            as handstock_reason,
      coalesce(r.remarks, '')                     as remarks,
      l.rm_by, l.rm_at, l.commercial_by, l.commercial_at, l.nsm_by, l.nsm_at,
      coalesce(l.created_at, r.created_at)        as raised_at,
      -- how long it has been sitting in the Stores queue
      greatest(coalesce(l.nsm_at, l.commercial_at, l.rm_at, l.created_at, r.created_at),
               coalesce(l.created_at, r.created_at))                       as waiting_since
    from public.spare_request_lines l
    join public.spare_requests r on r.uid = l.request_uid
    where l.stage = 'Stores' and coalesce(l.dispatch_uid, '') = ''
  $view$;
end $spd$;


alter view public.spare_pending_dispatch set (security_invoker = on);
grant select on public.spare_pending_dispatch to authenticated;

-- ---------------------------------------------------------------------------
-- Dispatch a batch, atomically.
--
-- Everything the Stores incharge ticked goes out under ONE stock-out and ONE
-- DC, so the whole batch either lands or none of it does. The checks are here
-- rather than in the screen because the screen is not the only way in:
--   • the caller must hold spare.dispatch;
--   • every line must still be waiting at Stores (not already sent, dropped
--     or rejected while the screen was open);
--   • every line must be going to the SAME engineer — a DC is one delivery to
--     one person.
-- ---------------------------------------------------------------------------
create or replace function public.dispatch_spare_lines(
  p_line_ids bigint[],
  p_courier  text default '',
  p_remarks  text default '',
  p_dc_date  date default current_date,
  p_actor    text default ''
) returns public.spare_dispatches
language plpgsql security definer set search_path = public as $$
declare
  eng   text;
  n     integer;
  qty   numeric;
  head  public.spare_dispatches;
  email text;
begin
  if not (public.is_admin() or public.has_perm('spare.dispatch')) then
    raise exception 'RBAC: dispatch requires the spare.dispatch permission';
  end if;
  if p_line_ids is null or array_length(p_line_ids, 1) is null then
    raise exception 'Nothing to dispatch: no spares selected';
  end if;

  select count(*), sum(v.qty), min(v.engineer), min(v.engineer_email)
    into n, qty, eng, email
    from public.spare_pending_dispatch v
   where v.line_id = any (p_line_ids);

  if coalesce(n, 0) <> array_length(p_line_ids, 1) then
    raise exception
      'Only % of the % selected spares are still waiting at Stores — refresh and try again',
      coalesce(n, 0), array_length(p_line_ids, 1);
  end if;
  if (select count(distinct v.engineer_key) from public.spare_pending_dispatch v
       where v.line_id = any (p_line_ids)) <> 1 then
    raise exception 'A stock out goes to one engineer — select spares for a single engineer';
  end if;

  insert into public.spare_dispatches
    (dc_date, engineer, engineer_email, courier, remarks, line_count, total_qty, dispatched_by)
  values
    (coalesce(p_dc_date, current_date), eng, coalesce(email, ''), coalesce(p_courier, ''),
     coalesce(p_remarks, ''), n, coalesce(qty, 0), coalesce(nullif(btrim(p_actor), ''), ''))
  returning * into head;

  update public.spare_request_lines l
     set stores_status    = 'Dispatched',
         dispatch_uid     = head.uid,
         stock_out_no     = head.uid,
         dc_number        = head.dc_number,
         courier          = coalesce(p_courier, ''),
         dispatch_remarks = coalesce(p_remarks, ''),
         dispatched_by    = head.dispatched_by,
         dispatched_at    = head.dispatched_at
   where l.id = any (p_line_ids);

  return head;
end $$;
grant execute on function public.dispatch_spare_lines(bigint[], text, text, date, text) to authenticated;

-- ---------------------------------------------------------------------------
-- The batch columns belong to the dispatch stage: same permission as the DC.
-- Re-stated in full (0016's guard predates these columns).
-- ---------------------------------------------------------------------------
create or replace function public.spare_request_lines_dispatch_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if public.is_admin() then return new; end if;
  if (new.dispatch_uid is distinct from old.dispatch_uid
      or new.stock_out_no is distinct from old.stock_out_no)
     and not public.has_perm('spare.dispatch') then
    raise exception 'RBAC: recording a stock out requires the spare.dispatch permission';
  end if;
  return new;
end $$;
drop trigger if exists spare_request_lines_dispatch_guard on public.spare_request_lines;
-- Triggers fire in name order, so this one runs BEFORE
-- spare_request_lines_guard ('d' < 'g'). Either order is fine: both only
-- raise, neither changes the row.
create trigger spare_request_lines_dispatch_guard
  before update on public.spare_request_lines
  for each row execute function public.spare_request_lines_dispatch_guard();

-- ---------------------------------------------------------------------------
-- RLS. A dispatch is readable by anyone who can see the spares in it — the
-- engineer it went to, their line management, and Stores; only spare.dispatch
-- can write one (the RPC above is the supported route).
-- ---------------------------------------------------------------------------
alter table public.spare_dispatches enable row level security;

drop policy if exists sd_read on public.spare_dispatches;
create policy sd_read on public.spare_dispatches for select
  using (public.is_admin() or created_by = auth.uid()
      or public.has_perm('spare.dispatch')
      or lower(btrim(engineer)) in (select lower(btrim(n)) from public.visible_engineer_names() as v(n)));

drop policy if exists sd_insert on public.spare_dispatches;
create policy sd_insert on public.spare_dispatches for insert
  with check (public.is_admin() or public.has_perm('spare.dispatch'));

drop policy if exists sd_update on public.spare_dispatches;
create policy sd_update on public.spare_dispatches for update
  using (public.is_admin() or public.has_perm('spare.dispatch'))
  with check (public.is_admin() or public.has_perm('spare.dispatch'));

-- ---------------------------------------------------------------------------
-- Access. The screen is for whoever already dispatches; append additively so
-- an admin's later edits to a role are left alone.
-- ---------------------------------------------------------------------------
update public.app_roles
   set permissions = coalesce(permissions, '[]'::jsonb) || '["mod:/spare-dispatch"]'::jsonb,
       updated_at  = now()
 where coalesce(permissions, '[]'::jsonb) ? 'spare.dispatch'
   and not coalesce(permissions, '[]'::jsonb) ? 'mod:/spare-dispatch';

-- Lines dispatched before this migration have a DC but no stock out. Give them
-- their DC number as the stock-out reference so the register is not half
-- blank; a real SO number only exists for batches booked out through the
-- screen. Runs with the guard dropped: this is a data migration, not somebody
-- dispatching, and auth.uid() is NULL in the SQL editor.
drop trigger if exists spare_request_lines_guard          on public.spare_request_lines;
drop trigger if exists spare_request_lines_dispatch_guard on public.spare_request_lines;
update public.spare_request_lines
   set stock_out_no = dc_number
 where coalesce(stores_status, '') ~* 'dispatch'
   and coalesce(stock_out_no, '') = ''
   and coalesce(dc_number, '') <> '';
create trigger spare_request_lines_guard
  before update on public.spare_request_lines
  for each row execute function public.spare_request_lines_guard();
create trigger spare_request_lines_dispatch_guard
  before update on public.spare_request_lines
  for each row execute function public.spare_request_lines_dispatch_guard();

-- ------------------------------------------------------------------------
-- 0028_dc_number_is_stock_out.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- One number on a delivery: the STOCK OUT number.
--
-- 0027 minted two series, SO- and DC-, on the assumption that the challan
-- carried a document number of its own. The DC template says otherwise: the
-- printed challan identifies itself by **Stock Out No.** and **Stock Out
-- Date**, and has no DC-number field at all. The sheet-era history says the
-- same — its column is `SO NO`, and that is what the import loaded into
-- `dc_number`.
--
-- So there is one number. `spare_dispatches.uid` is it, `dc_number` mirrors it
-- (keeping every existing read — hand stock's movement ref, the approval
-- trail, the register column, the imported history — working unchanged), and
-- the separate DC series is retired.
--
-- If a distinct challan series is ever wanted, this is where it comes back:
-- give next_dc_number() its own counter again and stop mirroring below.
-- ===========================================================================

create or replace function public.spare_dispatches_assign_no()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.dc_date is null then new.dc_date := current_date; end if;
  if new.uid is null or btrim(new.uid) = '' then
    new.uid := public.next_stock_out_no(new.dc_date);
  end if;
  -- The challan is the stock out. Not a second series.
  if new.dc_number is null or btrim(new.dc_number) = '' then
    new.dc_number := new.uid;
  end if;
  return new;
end $$;

-- next_dc_number() is retired rather than left as a live second series that
-- nothing calls. Dropped only if 0027 created it, so this is re-runnable.
drop function if exists public.next_dc_number(date);
delete from public.spare_dispatch_counters where series = 'dc';

-- Re-point anything 0027 already minted. Only the auto-generated DC- series is
-- touched; a number typed or imported from the sheet era is left exactly as it
-- is. Guards are dropped first — this is a data migration, not somebody
-- dispatching, and auth.uid() is NULL in the SQL editor.
drop trigger if exists spare_request_lines_guard          on public.spare_request_lines;
drop trigger if exists spare_request_lines_dispatch_guard on public.spare_request_lines;

update public.spare_request_lines l
   set dc_number = d.uid
  from public.spare_dispatches d
 where l.dispatch_uid = d.uid
   and l.dc_number ~ '^DC-\d{4}-\d{4}$'
   and l.dc_number is distinct from d.uid;

update public.spare_dispatches
   set dc_number = uid
 where dc_number ~ '^DC-\d{4}-\d{4}$';

create trigger spare_request_lines_guard
  before update on public.spare_request_lines
  for each row execute function public.spare_request_lines_guard();
create trigger spare_request_lines_dispatch_guard
  before update on public.spare_request_lines
  for each row execute function public.spare_request_lines_dispatch_guard();

-- ------------------------------------------------------------------------
-- 0031_pending_dispatch_live_stage.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- The dispatch queue computes the stage; it no longer trusts the column.
--
-- Two screens disagreed: Spare Requests showed three spares at **Stores**
-- while Pending Dispatch showed an empty queue. They were asking different
-- questions.
--
--   • The register derives the stage in the app, from the approval columns
--     (src/lib/spareflow.ts, deriveStage).
--   • The queue filtered on `spare_request_lines.stage` — a column maintained
--     by trigger, i.e. a CACHE of that same derivation.
--
-- A cache can go stale. Anything that writes a line without the trigger
-- recomputing — a load with triggers disabled, a row last written before a
-- stage rule changed (0025 added Dropped; 0016 introduced the rule itself) —
-- leaves `stage` saying one thing while the approvals say another. The
-- register reads the approvals and shows Stores; the queue reads the stale
-- column and shows nothing. Exactly the reported symptom.
--
-- So the queue now applies spare_line_stage() to the columns, the same way the
-- app does. A spare that has cleared its approvals appears in the queue even
-- if its cached stage was never refreshed.
--
-- The column is repaired too, since the register's stage chips and KPI tiles
-- and the request-header roll-up all still read it.
-- ===========================================================================

-- Guarded: 0055_partial_dispatch.sql OWNS this view now and appended
-- requested_qty / dispatched_qty to it. `create or replace view` cannot drop
-- columns, so re-running this file over a fully-migrated project failed with
-- "cannot drop columns from view" and took the rest of all.sql down with it.
-- The later definition supersedes this one, so skipping is a no-op.
do $spd$
begin
  if exists (select 1 from information_schema.columns
              where table_schema = 'public' and table_name = 'spare_pending_dispatch'
                and column_name = 'dispatched_qty') then
    return;
  end if;

  execute $view$
    create or replace view public.spare_pending_dispatch as
    select
      l.id                                        as line_id,
      l.line_uid,
      l.request_uid,
      r.or_no,
      r.or_req_date,
      l.row_no,
      l.part,
      upper(btrim(split_part(coalesce(l.part, ''), '|', 1)))
                                                  as part_code,
      l.qty,
      r.req_type,
      r.item_status,
      coalesce(r.engineer, '')                    as engineer,
      lower(btrim(coalesce(r.engineer, '')))      as engineer_key,
      coalesce(r.engineer_email, '')              as engineer_email,
      coalesce(r.ucn, '')                         as ucn,
      coalesce(r.call_number, '')                 as call_number,
      coalesce(r.party_name, '')                  as party_name,
      coalesce(r.product_name, '')                as product_name,
      coalesce(r.serial, '')                      as serial,
      coalesce(r.handstock_reason, '')            as handstock_reason,
      coalesce(r.remarks, '')                     as remarks,
      l.rm_by, l.rm_at, l.commercial_by, l.commercial_at, l.nsm_by, l.nsm_at,
      coalesce(l.created_at, r.created_at)        as raised_at,
      greatest(coalesce(l.nsm_at, l.commercial_at, l.rm_at, l.created_at, r.created_at),
               coalesce(l.created_at, r.created_at))                       as waiting_since
    from public.spare_request_lines l
    join public.spare_requests r on r.uid = l.request_uid
    -- Computed, not read: the stage column is a cache and may be stale.
    where public.spare_line_stage(
            coalesce(l.rm_approval, 'Pending'),
            coalesce(l.commercial_approval, 'Pending'),
            coalesce(l.nsm_approval, 'Pending'),
            coalesce(l.stores_status, 'Pending'),
            l.received_at,
            r.item_status) = 'Stores'
      and coalesce(l.dispatch_uid, '') = ''
  $view$;
end $spd$;


alter view public.spare_pending_dispatch set (security_invoker = on);
grant select on public.spare_pending_dispatch to authenticated;

-- ---------------------------------------------------------------------------
-- Repair every cached stage, and roll the requests up from the repaired lines.
-- Guards are dropped around it: this is a data migration, not somebody
-- approving or dispatching, and auth.uid() is NULL in the SQL editor.
-- ---------------------------------------------------------------------------
drop trigger if exists spare_request_lines_guard          on public.spare_request_lines;
drop trigger if exists spare_request_lines_dispatch_guard on public.spare_request_lines;

update public.spare_request_lines l
   set stage  = public.spare_line_stage(
                  coalesce(l.rm_approval, 'Pending'),
                  coalesce(l.commercial_approval, 'Pending'),
                  coalesce(l.nsm_approval, 'Pending'),
                  coalesce(l.stores_status, 'Pending'),
                  l.received_at, r.item_status),
       status = public.spare_line_stage(
                  coalesce(l.rm_approval, 'Pending'),
                  coalesce(l.commercial_approval, 'Pending'),
                  coalesce(l.nsm_approval, 'Pending'),
                  coalesce(l.stores_status, 'Pending'),
                  l.received_at, r.item_status)
  from public.spare_requests r
 where r.uid = l.request_uid
   and l.stage is distinct from public.spare_line_stage(
                  coalesce(l.rm_approval, 'Pending'),
                  coalesce(l.commercial_approval, 'Pending'),
                  coalesce(l.nsm_approval, 'Pending'),
                  coalesce(l.stores_status, 'Pending'),
                  l.received_at, r.item_status);

create trigger spare_request_lines_guard
  before update on public.spare_request_lines
  for each row execute function public.spare_request_lines_guard();
create trigger spare_request_lines_dispatch_guard
  before update on public.spare_request_lines
  for each row execute function public.spare_request_lines_dispatch_guard();

do $$
declare u text;
begin
  for u in select uid from public.spare_requests loop
    perform public.spare_request_rollup(u);
  end loop;
end $$;

-- ------------------------------------------------------------------------
-- 0032_stores_sees_pending_dispatch.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Stores Incharge can open Pending Dispatch.
--
-- 0027 granted `mod:/spare-dispatch` only to roles whose stored permission
-- list already contained `spare.dispatch`. That is one condition too many: a
-- role's list is editable in Roles & Permissions, so any role whose entry had
-- been re-saved, seeded before 0008's matrix, or trimmed by an administrator
-- came out of that migration without the screen — while still being the role
-- that does the dispatching. Reported for Stores Incharge.
--
-- Granted by ROLE as well now, the way 0020_stock_transfer.sql grants the
-- transfer screen. The two conditions are OR'd, so a custom role that holds
-- spare.dispatch still gets it, and an administrator's later edits to any
-- other permission are untouched — this only ever appends.
--
-- Stores also needs the register itself to see what is coming, and the ability
-- to dispatch at all, so both are topped up for the same roles. Every clause
-- is additive and re-runnable.
-- ===========================================================================

-- 1. The action. A dispatch role that somehow lost it cannot book stock out.
update public.app_roles
   set permissions = coalesce(permissions, '[]'::jsonb) || '["spare.dispatch"]'::jsonb,
       updated_at  = now()
 where role in ('admin', 'stores_incharge', 'spare_coordinator')
   and not coalesce(permissions, '[]'::jsonb) ? 'spare.dispatch';

-- 2. The screen, for those roles and for anyone else holding the action.
update public.app_roles
   set permissions = coalesce(permissions, '[]'::jsonb) || '["mod:/spare-dispatch"]'::jsonb,
       updated_at  = now()
 where (role in ('admin', 'stores_incharge', 'spare_coordinator')
        or coalesce(permissions, '[]'::jsonb) ? 'spare.dispatch')
   and not coalesce(permissions, '[]'::jsonb) ? 'mod:/spare-dispatch';

-- 3. The spare register, so Stores can see what is on its way to them.
update public.app_roles
   set permissions = coalesce(permissions, '[]'::jsonb) || '["mod:/spare-requests"]'::jsonb,
       updated_at  = now()
 where (role in ('admin', 'stores_incharge', 'spare_coordinator')
        or coalesce(permissions, '[]'::jsonb) ? 'spare.dispatch')
   and not coalesce(permissions, '[]'::jsonb) ? 'mod:/spare-requests';

-- ------------------------------------------------------------------------
-- 0033_rm_approves_own_team.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- An RM approves their own team's spares — and never their own request.
--
-- RM approval was gated on the PERMISSION alone: anyone holding
-- spare.approve_rm could approve any spare they could see. Two things follow
-- that should not:
--
--   • a Reporting Manager could approve a spare raised by someone outside
--     their team, including one raised by an administrator;
--   • a Reporting Manager could approve their OWN request, so a manager's
--     spares had no approver above them.
--
-- The rule now: the request's engineer must be someone who reports to the
-- approver, directly or through the tree — and must not be the approver.
-- A manager's own request therefore waits for THEIR manager.
--
-- visible_engineer_names() (0004) already walks that tree, but it INCLUDES
-- the caller, which is exactly why self-approval slipped through. The check
-- below subtracts them.
--
-- Coordination roles — Hotline, Spare Coordinator and the like — sit outside
-- the reporting tree and hold spare.approve_rm as a backstop. They have no
-- reports, so the sub-tree test would refuse them everything; they keep the
-- wider remit they have today, minus the self-approval that is now closed for
-- everyone. If those roles should also be narrowed, this is the one function
-- to change.
-- ===========================================================================

-- Does p_name report to the caller (at any depth), and is not the caller?
create or replace function public.is_my_report(p_name text)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.visible_engineer_names() as v(n)
     where lower(btrim(n)) = lower(btrim(coalesce(p_name, '')))
       and lower(btrim(n)) <> lower(btrim(coalesce(public.my_dir_name(), '')))
  );
$$;
grant execute on function public.is_my_report(text) to authenticated;

-- Does the caller have anyone reporting to them at all?
create or replace function public.has_reports()
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.visible_engineer_names() as v(n)
     where lower(btrim(n)) <> lower(btrim(coalesce(public.my_dir_name(), '')))
  );
$$;
grant execute on function public.has_reports() to authenticated;

-- May the caller give RM approval to a spare raised by p_engineer?
create or replace function public.spare_rm_may_approve(p_engineer text)
returns boolean language sql stable security definer set search_path = public as $$
  select case
    when public.is_admin() then true
    -- Never your own request, whoever you are: it goes to your manager.
    when lower(btrim(coalesce(p_engineer, '')))
       = lower(btrim(coalesce(public.my_dir_name(), ''))) then false
    -- A manager is confined to their own tree.
    when public.has_reports() then public.is_my_report(p_engineer)
    -- Coordination roles, who are not managers, keep the wider remit.
    else true
  end;
$$;
grant execute on function public.spare_rm_may_approve(text) to authenticated;

-- ---------------------------------------------------------------------------
-- Enforced as its own trigger rather than by re-stating 0016's guard, which
-- owns the per-stage permission rules and is long enough already.
-- ---------------------------------------------------------------------------
create or replace function public.spare_request_lines_rm_scope_guard()
returns trigger language plpgsql security definer set search_path = public as $$
declare req public.spare_requests;
begin
  if public.is_admin() then return new; end if;
  if new.rm_approval is not distinct from old.rm_approval
     and new.rm_by    is not distinct from old.rm_by
     and new.rm_at    is not distinct from old.rm_at then
    return new;                                   -- not an RM decision
  end if;

  select * into req from public.spare_requests where uid = new.request_uid;
  if not public.spare_rm_may_approve(req.engineer) then
    if lower(btrim(coalesce(req.engineer, '')))
     = lower(btrim(coalesce(public.my_dir_name(), ''))) then
      raise exception 'You cannot approve your own spare request — it goes to your reporting manager';
    end if;
    raise exception '% does not report to you, so their spare is not yours to approve',
      coalesce(nullif(btrim(req.engineer), ''), 'That engineer');
  end if;
  return new;
end $$;

drop trigger if exists spare_request_lines_rm_scope_guard on public.spare_request_lines;
create trigger spare_request_lines_rm_scope_guard
  before update on public.spare_request_lines
  for each row execute function public.spare_request_lines_rm_scope_guard();

-- ------------------------------------------------------------------------
-- 0040_spare_read_scope.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- A spare request is visible to its raiser, their management chain, and the
-- desks that process it — not to every approver.
--
-- sr_read granted a blanket `can_approve_spares()`: holding ANY spare approval
-- permission let you read EVERY spare request. So a Reporting Manager saw
-- requests raised by people outside their team — administrators included —
-- and 0039 only stopped them approving those, which still left the data on
-- screen. Reported: "the Data itself should not be visible."
--
-- `can_view_all_calls()` (0034_office_roles_see_all / 0035_data_view_all) is
-- already the app's answer to "who legitimately sees everyone's work": admin,
-- an explicit data.view_all grant, and the office roles — Hotline, NSM,
-- Commercial, Spare Coordinator, Stores Incharge, Tally. Those desks act on
-- spares from every team, so they must keep seeing them; a manager must not.
--
-- What a Reporting Manager is left with is exactly what was asked for:
--   • their own requests — visible, and NOT approvable (0039 sends those to
--     their own manager);
--   • their reporting engineers' requests — visible and approvable;
--   • nothing else.
--
-- spare_request_lines needs no change: srl_read is an EXISTS against
-- spare_requests, so the lines follow the header. spare_pending_dispatch and
-- the hand-stock views are security_invoker, so they follow too.
-- ===========================================================================

drop policy if exists sr_read on public.spare_requests;
create policy sr_read on public.spare_requests for select
  using (
    (select public.can_view_all_calls())          -- admin + office desks + data.view_all
    or created_by = (select auth.uid())           -- I raised it
    or lower(engineer_email) = lower((select auth.email()))
    or lower(btrim(engineer)) in (                -- me and my reporting sub-tree
         select lower(btrim(n)) from public.visible_engineer_names() as v(n)
       )
  );

-- ------------------------------------------------------------------------
-- 0036_spare_drop.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- spare.drop — a Spare Coordinator / Hotline may DROP a spare at any stage
-- (short supply, no longer needed, superseded). It sets stores_status =
-- 'Dropped' (terminal), and must NOT mint a DC. Distinct from Stores dispatch,
-- which still needs spare.dispatch. The line guard is widened to allow it.
-- ===========================================================================

create or replace function public.spare_request_lines_guard()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  changed boolean;
  auto_ok boolean;
  req     public.spare_requests;
begin
  if public.is_admin() then return new; end if;
  select * into req from public.spare_requests where uid = new.request_uid;

  auto_ok := not public.spare_needs_review(req.item_status)
             and public.has_perm('spare.approve_rm');

  changed := new.rm_approval is distinct from old.rm_approval
          or new.rm_by       is distinct from old.rm_by
          or new.rm_at       is distinct from old.rm_at;
  if changed and not public.has_perm('spare.approve_rm') then
    raise exception 'RBAC: RM approval requires the spare.approve_rm permission';
  end if;

  changed := new.commercial_approval is distinct from old.commercial_approval
          or new.commercial_by       is distinct from old.commercial_by
          or new.commercial_at       is distinct from old.commercial_at;
  if changed
     and not public.has_perm('spare.approve_commercial')
     and not (auto_ok and new.commercial_approval = 'Auto-Approved'
              and new.commercial_by is not distinct from old.commercial_by) then
    raise exception 'RBAC: Commercial approval requires the spare.approve_commercial permission';
  end if;

  changed := new.nsm_approval is distinct from old.nsm_approval
          or new.nsm_by       is distinct from old.nsm_by
          or new.nsm_at       is distinct from old.nsm_at;
  if changed
     and not public.has_perm('spare.approve_nsm')
     and not (auto_ok and new.nsm_approval = 'Auto-Approved'
              and new.nsm_by is not distinct from old.nsm_by) then
    raise exception 'RBAC: NSM approval requires the spare.approve_nsm permission';
  end if;

  changed := new.stores_status    is distinct from old.stores_status
          or new.dc_number        is distinct from old.dc_number
          or new.dispatched_by    is distinct from old.dispatched_by
          or new.dispatched_at    is distinct from old.dispatched_at
          or new.courier          is distinct from old.courier
          or new.dispatch_remarks is distinct from old.dispatch_remarks;
  -- Dispatch needs spare.dispatch; a DROP (Dropped, no DC) needs spare.drop.
  if changed and not public.has_perm('spare.dispatch')
     and not (public.has_perm('spare.drop')
              and coalesce(new.stores_status, '') ~* 'drop'
              and new.dc_number is not distinct from old.dc_number) then
    raise exception 'RBAC: dispatch / DC requires the spare.dispatch permission (a drop needs spare.drop)';
  end if;

  changed := new.reject_reason  is distinct from old.reject_reason
          or new.rejected_stage is distinct from old.rejected_stage;
  if changed and not public.can_approve_spares() and not public.has_perm('spare.drop') then
    raise exception 'RBAC: recording a rejection requires an approval permission';
  end if;

  changed := new.received_by     is distinct from old.received_by
          or new.received_at     is distinct from old.received_at
          or new.receipt_remarks is distinct from old.receipt_remarks;
  if changed then
    if not public.has_perm('spare.receive') then
      raise exception 'RBAC: acknowledging receipt requires the spare.receive permission';
    end if;
    if not public.is_spare_requester(req) then
      raise exception 'RBAC: only the engineer who raised the request may acknowledge it';
    end if;
    if old.stores_status is null or old.stores_status !~* 'dispatch' then
      raise exception 'RBAC: a spare can only be acknowledged after it is dispatched';
    end if;
  end if;

  if (new.part is distinct from old.part or new.qty is distinct from old.qty)
     and not public.is_spare_requester(req) then
    raise exception 'RBAC: only the engineer who raised the request may change its parts';
  end if;

  return new;
end $$;

-- ------------------------------------------------------------------------
-- 0084_spare_request_import.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Loading the spare-request history: keep the export's columns, and let the
-- two files arrive in either order.
--
-- The register comes as two exports. The HEADER file is one row per request
-- (its OR number, engineer, call, machine); the LINES file is one row per spare
-- on it, and identifies its parent ONLY by the OR number. So the OR number is
-- what joins them, and `spare_requests.uid` has to be it — nothing else in the
-- lines file could point at a request.
--
-- Two things that file needs:
--
-- 1. `extra` on both tables. The header carries 47 columns the table has no
--    field for (its own row id, and Spare (1..20) / Qty (1..20) — the lines
--    repeated across the row) and the lines carry 29 more (the SO number, POD,
--    Tally reference, the reporting and regional manager). Dropping them on the
--    floor because the table happens to have no column is the quiet loss the
--    rest of the import is careful to avoid.
--
-- 2. A STUB PARENT, exactly as 0036 does for a sale item whose entry has not
--    been loaded. 72 of the 8,675 line rows name an OR number that is not in
--    the header export at all — a real gap in the source, not a loading order
--    problem — and `spare_request_lines_request_uid_fkey` would fail the whole
--    batch on them. A stub lets them load and MARKS ITSELF, so the gap is
--    visible in the register instead of costing 8,603 good rows. If the missing
--    header rows ever arrive, loading them fills the stub in.
-- ===========================================================================

alter table public.spare_requests      add column if not exists extra jsonb not null default '{}'::jsonb;
alter table public.spare_request_lines add column if not exists extra jsonb not null default '{}'::jsonb;

comment on column public.spare_requests.extra is
  'Everything the source export carried that has no field of its own, kept as written.';

create or replace function public.spare_request_line_stub_parent()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if btrim(coalesce(new.request_uid, '')) = '' then
    return new;                                   -- nothing to point at; the FK will say so
  end if;
  if exists (select 1 from public.spare_requests r where r.uid = new.request_uid) then
    return new;
  end if;
  -- Marked, not silent: a request that exists only because a line referred to it
  -- should be findable and fixable, not indistinguishable from a real one.
  insert into public.spare_requests (uid, or_no, req_type, status, remarks)
  values (new.request_uid, new.request_uid, 'Call Based', 'Imported',
          'Created from an imported spare line — the request header was not in the export.')
  on conflict (uid) do nothing;
  return new;
end $$;

drop trigger if exists spare_request_line_stub_parent on public.spare_request_lines;
create trigger spare_request_line_stub_parent before insert on public.spare_request_lines
  for each row execute function public.spare_request_line_stub_parent();

-- ------------------------------------------------------------------------
-- 0085_spare_request_or_no_key.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- The OR number is the spare register's key.
--
-- `spare_requests` has TWO unique columns: `uid` (the app's own WA-… id) and
-- `or_no`, unique since 0011. The import matched on `uid` and wrote the OR
-- number into both — which fails the moment a request with that OR number is
-- already here under a different uid:
--
--     duplicate key value violates unique constraint "spare_requests_or_no_idx"
--
-- and that is exactly the state an earlier import left, having keyed those
-- 4,081 rows on the sheet's own row id. One row in the way stops the file.
--
-- So match on what actually identifies a request in the source — the OR
-- number — and leave `uid` alone:
--
--   • `uid` is filled from the OR number when an insert does not carry one, so
--     the import need not send it at all and never fights the other index.
--   • A LINE finds its parent by OR number even when that request is held
--     under a different uid. Only a request that is in neither file gets a
--     stub, as 0084 intended.
--
-- Nothing is re-keyed: a uid already handed out stays as it is. It is internal,
-- and rewriting it would drag every line, dispatch and notification with it.
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- 0017's assignment, plus the uid default. Both are BEFORE INSERT, so the
-- NOT NULL on uid is checked after this has run.
-- ---------------------------------------------------------------------------
create or replace function public.spare_requests_assign_or_no()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.or_req_date is null then
    new.or_req_date := current_date;
  end if;
  if new.or_no is null or trim(new.or_no) = '' then
    -- Numbered in the month the request is raised in.
    new.or_no := public.next_spare_or_no(new.or_req_date);
  end if;
  -- An import identifies a request by its OR number and has no uid to give.
  if new.uid is null or btrim(new.uid) = '' then
    new.uid := new.or_no;
  end if;
  return new;
end $$;

drop trigger if exists spare_requests_assign_or_no on public.spare_requests;
create trigger spare_requests_assign_or_no
  before insert on public.spare_requests
  for each row execute function public.spare_requests_assign_or_no();

-- ---------------------------------------------------------------------------
-- A line names its parent by OR number. Resolve that to the request's uid
-- before falling back to 0084's stub — otherwise a request that is present
-- under another uid gets a second copy, and the stub itself then breaks on
-- the or_no index.
-- ---------------------------------------------------------------------------
create or replace function public.spare_request_line_stub_parent()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  held text;
begin
  if btrim(coalesce(new.request_uid, '')) = '' then
    return new;                                   -- nothing to point at; the FK will say so
  end if;
  if exists (select 1 from public.spare_requests r where r.uid = new.request_uid) then
    return new;
  end if;
  -- Same request, different uid: point the line at the row that is already here.
  select r.uid into held from public.spare_requests r where r.or_no = new.request_uid limit 1;
  if held is not null then
    new.request_uid := held;
    return new;
  end if;
  -- Marked, not silent: a request that exists only because a line referred to it
  -- should be findable and fixable, not indistinguishable from a real one.
  insert into public.spare_requests (uid, or_no, req_type, status, remarks)
  values (new.request_uid, new.request_uid, 'Call Based', 'Imported',
          'Created from an imported spare line — the request header was not in the export.')
  on conflict (uid) do nothing;
  return new;
end $$;

drop trigger if exists spare_request_line_stub_parent on public.spare_request_lines;
create trigger spare_request_line_stub_parent before insert on public.spare_request_lines
  for each row execute function public.spare_request_line_stub_parent();

-- ------------------------------------------------------------------------
-- 0087_spare_line_stub_rls.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- "Your role does not have permission for this action." on the FIRST spare line.
--
-- 0084 lets a line whose request is in neither export create a stub parent from
-- a BEFORE INSERT trigger, so one gap in the source does not cost the file. The
-- foreign key is satisfied by that stub — referential checks run at the end of
-- the statement, with a fresh snapshot — but `srl_insert` is NOT:
--
--   with check (has_perm('spare.request') and exists (
--     select 1 from spare_requests r where r.uid = request_uid
--       and (r.created_by = auth.uid() or is_admin())))
--
-- A row-level security check is evaluated INSIDE the inserting command, and a
-- command cannot see rows written by SQL its own triggers ran: the stub's cmin
-- is higher than the command's. So the EXISTS finds nothing and the row is
-- refused — for an ADMIN too, because `is_admin()` sat inside the EXISTS and an
-- EXISTS with no row is false however permissive its predicate is.
--
-- And PostgREST sends the whole upload as ONE insert, so a single such line
-- fails all 8,571 — which is what happened on row 1 (OR26724, an OR number the
-- 2026 header export does not go back far enough to carry).
--
-- Hoisting `is_admin()` out of the EXISTS is the whole fix. It takes nothing
-- away from anyone else: a non-admin still has to own the request they are
-- attaching lines to, and an admin could already read and write every one of
-- these rows.
-- ===========================================================================

drop policy if exists srl_insert on public.spare_request_lines;
create policy srl_insert on public.spare_request_lines for insert
  with check (
    public.has_perm('spare.request')
    and (
      public.is_admin()
      or exists (
        select 1 from public.spare_requests r
         where r.uid = request_uid and r.created_by = auth.uid())
    ));

-- ------------------------------------------------------------------------
-- 0088_spare_line_parent_visible.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- "Your role does not have permission for this action." on the first spare
-- line — still, after 0087.
--
-- 0087 hoisted `is_admin()` out of the EXISTS, which fixes the upload for an
-- administrator and nobody else. But the real fault is not WHO is uploading, it
-- is that the check cannot SEE what it is checking: 0084's stub parent is
-- written by a BEFORE trigger, and a command cannot see rows the SQL its own
-- triggers ran has inserted. So for anyone who is not an admin — a Spare
-- Coordinator, an RM, whoever actually loads the register — the row is still
-- refused, and one such line still fails all 8,571.
--
-- Ask the question in a place that can see the answer. A VOLATILE plpgsql
-- function takes a FRESH SNAPSHOT for each statement it runs (read committed),
-- so the stub its caller's trigger just wrote is visible to it. Same question,
-- same rule — a line must belong to a request you raised (or you are an
-- admin) — asked where it can be answered truthfully.
--
-- It is SECURITY DEFINER so the lookup is not itself filtered by `sr_read`
-- (a request you own but cannot yet read would otherwise answer "no"), and it
-- returns a BOOLEAN and nothing else, so it discloses nothing.
-- ===========================================================================

create or replace function public.spare_line_parent_ok(p_uid text)
returns boolean language plpgsql volatile security definer set search_path = public as $$
declare ok boolean;
begin
  if btrim(coalesce(p_uid, '')) = '' then
    return false;                                 -- no parent named; the FK will say so
  end if;
  select exists (
    select 1 from public.spare_requests r
     where r.uid = p_uid
       and (r.created_by = auth.uid() or public.is_admin())
  ) into ok;
  return coalesce(ok, false);
end $$;

grant execute on function public.spare_line_parent_ok(text) to authenticated;

drop policy if exists srl_insert on public.spare_request_lines;
create policy srl_insert on public.spare_request_lines for insert
  with check (
    public.has_perm('spare.request')
    and public.spare_line_parent_ok(request_uid)
  );

-- ------------------------------------------------------------------------
-- 0020_stock_transfer.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Stock Transfer — engineer to engineer.
--
-- Stock is not stored as a balance anywhere; it is DERIVED from what has
-- already happened to an engineer's hand-stock:
--   +  a HandStock spare request line dispatched to the engineer
--   -  a spare consumed on a call
--   +/- stock transferred in or out
-- engineer_stock sums those movements, so a balance can never disagree with
-- the history behind it.
--
-- A transfer may only move stock the FROM engineer actually holds: the qty is
-- capped in the form and enforced here, so no route can drive a balance
-- negative.
-- ===========================================================================

create table if not exists public.stock_transfers (
  id            bigint generated always as identity primary key,
  uid           text unique not null,          -- ST-YYMM-NNNN
  from_engineer text not null,
  to_engineer   text not null,
  transfer_date date not null default current_date,
  remarks       text default '',
  status        text default 'Completed',
  created_at    timestamptz not null default now(),
  created_by    uuid references auth.users (id) default auth.uid(),
  constraint stock_transfer_distinct_parties
    check (lower(trim(from_engineer)) <> lower(trim(to_engineer)))
);
create table if not exists public.stock_transfer_lines (
  id           bigint generated always as identity primary key,
  transfer_uid text not null references public.stock_transfers (uid) on delete cascade,
  row_no       int,
  part         text not null,
  qty          numeric not null check (qty > 0),
  created_at   timestamptz not null default now()
);
create index if not exists stock_transfer_lines_uid_idx on public.stock_transfer_lines (transfer_uid);
create index if not exists stock_transfers_from_idx on public.stock_transfers (lower(trim(from_engineer)));
create index if not exists stock_transfers_to_idx   on public.stock_transfers (lower(trim(to_engineer)));

-- ---------------------------------------------------------------------------
-- ST numbers follow the OR convention: ST-YYMM-NNNN, restarting each month.
-- ---------------------------------------------------------------------------
create table if not exists public.stock_transfer_counters (
  period  text primary key,
  last_no integer not null default 0
);
alter table public.stock_transfer_counters enable row level security;  -- definer-only

create or replace function public.next_stock_transfer_no(p_on date default current_date)
returns text language plpgsql security definer set search_path = public as $$
declare p text := to_char(p_on, 'YY/MM'); n integer;
begin
  insert into public.stock_transfer_counters (period, last_no) values (p, 1)
  on conflict (period) do update set last_no = public.stock_transfer_counters.last_no + 1
  returning last_no into n;
  return 'ST-' || to_char(p_on, 'YYMM') || '-' || lpad(n::text, 4, '0');
end $$;
grant execute on function public.next_stock_transfer_no(date) to authenticated;

create or replace function public.stock_transfers_assign_no()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.transfer_date is null then new.transfer_date := current_date; end if;
  if new.uid is null or trim(new.uid) = '' then
    new.uid := public.next_stock_transfer_no(new.transfer_date);
  end if;
  return new;
end $$;
drop trigger if exists stock_transfers_assign_no on public.stock_transfers;
create trigger stock_transfers_assign_no
  before insert on public.stock_transfers
  for each row execute function public.stock_transfers_assign_no();

create or replace function public.stock_transfer_lines_row_no()
returns trigger language plpgsql security definer set search_path = public as $$
declare n int;
begin
  if new.row_no is null then
    select coalesce(max(row_no), 0) + 1 into n
      from public.stock_transfer_lines where transfer_uid = new.transfer_uid;
    new.row_no := n;
  end if;
  return new;
end $$;
drop trigger if exists stock_transfer_lines_row_no on public.stock_transfer_lines;
create trigger stock_transfer_lines_row_no
  before insert on public.stock_transfer_lines
  for each row execute function public.stock_transfer_lines_row_no();

-- ---------------------------------------------------------------------------
-- The derived balance. Engineers are matched by name, normalised the way
-- visible_engineer_names() does, because that is how every other table in the
-- app refers to them.
-- ---------------------------------------------------------------------------
create or replace view public.engineer_stock as
with moves as (
  -- In: hand-stock Stores has dispatched to the engineer.
  --
  -- Dispatch, not acknowledgement, is the trigger. Acknowledgement needs
  -- spare.receive, which the role defaults no longer give engineers, so
  -- keying off received_at would leave every balance at zero. Once Stores
  -- books it out it is the engineer's stock; the acknowledgement remains a
  -- confirmation step on the spare request, not a condition for holding it.
  select lower(trim(r.engineer)) as engineer, trim(l.part) as part, l.qty::numeric as qty
    from public.spare_request_lines l
    join public.spare_requests r on r.uid = l.request_uid
   where r.req_type = 'HandStock' and coalesce(l.stores_status, '') ~* 'dispatch'
  union all
  -- Out: consumed on a call.
  select lower(trim(c.engineer)), trim(c.part), -c.qty::numeric
    from public.spare_consumption c
  union all
  -- In: transferred from another engineer.
  select lower(trim(t.to_engineer)), trim(l.part), l.qty::numeric
    from public.stock_transfer_lines l join public.stock_transfers t on t.uid = l.transfer_uid
  union all
  -- Out: transferred away.
  select lower(trim(t.from_engineer)), trim(l.part), -l.qty::numeric
    from public.stock_transfer_lines l join public.stock_transfers t on t.uid = l.transfer_uid
)
select engineer, part, sum(qty) as qty
  from moves
 where coalesce(part, '') <> '' and coalesce(engineer, '') <> ''
 group by 1, 2;

grant select on public.engineer_stock to authenticated;

-- What an engineer can actually transfer: only parts they are holding.
create or replace function public.engineer_stock_available(p_engineer text, p_part text)
returns numeric language sql stable security definer set search_path = public as $$
  select coalesce((select qty from public.engineer_stock
                    where engineer = lower(trim(p_engineer)) and part = trim(p_part)), 0);
$$;
grant execute on function public.engineer_stock_available(text, text) to authenticated;

-- ---------------------------------------------------------------------------
-- A transfer may not move more than the sender holds. Checked AFTER the row
-- lands so the view already accounts for it — which also catches a multi-row
-- insert that would individually pass but together over-draw.
-- ---------------------------------------------------------------------------
create or replace function public.stock_transfer_lines_check_stock()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  sender text;
  bal    numeric;
begin
  select from_engineer into sender from public.stock_transfers where uid = new.transfer_uid;
  bal := public.engineer_stock_available(sender, new.part);
  if bal < 0 then
    -- bal is the balance AFTER this row, so a negative is the shortfall.
    raise exception
      'Stock transfer exceeds available stock: % would be left with % of %',
      sender, bal, trim(new.part);
  end if;
  return null;
end $$;
drop trigger if exists stock_transfer_lines_check_stock on public.stock_transfer_lines;
create trigger stock_transfer_lines_check_stock
  after insert or update on public.stock_transfer_lines
  for each row execute function public.stock_transfer_lines_check_stock();

-- ---------------------------------------------------------------------------
-- RLS. Reading follows the reporting tree, as the call and spare registers do;
-- raising a transfer needs stock.transfer, and an engineer may only send their
-- own stock (anyone with the wider permission may move on their behalf).
-- ---------------------------------------------------------------------------
alter table public.stock_transfers      enable row level security;
alter table public.stock_transfer_lines enable row level security;

drop policy if exists st_read on public.stock_transfers;
create policy st_read on public.stock_transfers for select
  using (public.is_admin() or created_by = auth.uid()
      or lower(trim(from_engineer)) in (select lower(trim(n)) from public.visible_engineer_names() as v(n))
      or lower(trim(to_engineer))   in (select lower(trim(n)) from public.visible_engineer_names() as v(n)));
drop policy if exists st_insert on public.stock_transfers;
create policy st_insert on public.stock_transfers for insert
  with check (public.has_perm('stock.transfer'));

drop policy if exists stl_read on public.stock_transfer_lines;
create policy stl_read on public.stock_transfer_lines for select
  using (exists (select 1 from public.stock_transfers t where t.uid = stock_transfer_lines.transfer_uid));
drop policy if exists stl_insert on public.stock_transfer_lines;
create policy stl_insert on public.stock_transfer_lines for insert
  with check (public.has_perm('stock.transfer') and exists (
    select 1 from public.stock_transfers t
     where t.uid = transfer_uid and (t.created_by = auth.uid() or public.is_admin())));

-- ---------------------------------------------------------------------------
-- Permissions. 0008 leaves an existing role's list alone, so new keys are on
-- no role — append them to the roles that hold or move spares.
-- ---------------------------------------------------------------------------
update public.app_roles
   set permissions = coalesce(permissions, '[]'::jsonb) || '["stock.transfer","mod:/stock-transfer"]'::jsonb,
       updated_at  = now()
 where role in ('admin', 'engineer', 'rm', 'rgm', 'spare_coordinator', 'stores_incharge')
   and not coalesce(permissions, '[]'::jsonb) ? 'stock.transfer';

-- ------------------------------------------------------------------------
-- 0023_handstock.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Hand stock — the stock level an engineer is carrying, per spare.
--
--   Stock Level = Stock Out (from Stores)
--               − Consumption
--               − Stock Transfer From
--               + Stock Transfer To
--
-- 0020_stock_transfer.sql already derives that balance for the Stock Transfer
-- screen (`engineer_stock`), and owns the transfer tables. This migration does
-- not add a second one: it keeps ONE derivation and gives it the detail the
-- Hand Stock register needs.
--
--   handstock_movements — one row per movement, with where it came from:
--                         the DC, the call, or the engineer on the other side.
--   handstock_balance   — the level per engineer + spare, with each term of
--                         the formula kept separately.
--   engineer_stock      — REDEFINED over handstock_balance, so the transfer
--                         screen, its stock guard and this register can never
--                         disagree. Same columns, same meaning.
--
-- Two things the first derivation missed, both of which made a balance wrong:
--
--   • Only `req_type = 'HandStock'` requests counted as stock in. A spare
--     dispatched against a CALL was consumed out of a balance it had never
--     been added to, so the engineer went negative and their transfers were
--     refused. Every spare Stores dispatches is stock in the engineer's hands,
--     whatever the request was raised for.
--   • The status is what makes it a stock out, not the timestamp. Dispatches
--     from the sheet era, from imports, or from before 0009 added
--     dispatched_at carry a DC but no date, and are every bit as much stock.
--
-- The views run with the caller's rights, so the register is scoped exactly
-- like the tables under it: an engineer sees their own stock, an RM their
-- sub-tree, an admin everyone's.
-- ===========================================================================

-- Consumption is keyed by the engineer's NAME (that is all the report form ever
-- wrote). The name is what the movements are matched on; the email is carried
-- alongside so a rename can be untangled later, and so new rows can be matched
-- on it once the field has been filled for a while.
alter table public.spare_consumption
  add column if not exists engineer_email text default '';

create index if not exists spare_consumption_engineer_idx     on public.spare_consumption (lower(btrim(engineer)));
create index if not exists spare_consumption_created_at_idx   on public.spare_consumption (created_at desc);
create index if not exists spare_request_lines_stores_idx     on public.spare_request_lines (lower(coalesce(stores_status, '')));
create index if not exists spare_request_lines_dispatched_idx on public.spare_request_lines (dispatched_at) where dispatched_at is not null;

-- ---------------------------------------------------------------------------
-- The two things a movement is matched on. Names arrive with stray case and
-- spacing from four different screens; a spare is stored as its catalogue
-- string "CODE|Description", and only the CODE identifies it.
-- ---------------------------------------------------------------------------
create or replace function public.handstock_key(p text)
returns text language sql immutable as $$ select lower(btrim(coalesce(p, ''))) $$;

create or replace function public.part_code(p text)
returns text language sql immutable as $$ select upper(btrim(split_part(coalesce(p, ''), '|', 1))) $$;

grant execute on function public.handstock_key(text) to authenticated;
grant execute on function public.part_code(text)     to authenticated;

-- ---------------------------------------------------------------------------
-- Movements — the four terms of the formula, one row each.
--
-- Stock out is dated by the DISPATCH, not the acknowledgement: the spare left
-- Stores and is the engineer's from that moment, whether or not they have got
-- round to acknowledging it. Since 0016_spare_line_approvals.sql dispatch is
-- per SPARE, so a partly dispatched OR moves only what actually went out.
--
-- What makes it a stock out is the STATUS, not the timestamp. Dispatches from
-- before this module — sheet-era history, imports, anything dispatched before
-- 0009 added dispatched_at — carry a DC and a status but no date, and they are
-- every bit as much stock in the engineer's hands. They count, dated by the
-- best timestamp the row has.
-- ---------------------------------------------------------------------------
-- These three are REBUILT, not replaced. `create or replace view` may not drop
-- a column, so once MRN (0039_material_returns.sql) has added `returned` to
-- the balance, replaying this file with the older column list fails with
--   ERROR 42P16: cannot drop columns from view
-- — and replaying it is exactly what re-running the bundle does. Dropping
-- first makes this file re-runnable whatever shape the views are currently in;
-- nothing is lost, since all three are derived. Dependants first:
-- engineer_stock reads the balance, the balance reads the movements.
drop view if exists public.engineer_stock;
drop view if exists public.handstock_balance;
drop view if exists public.handstock_movements;

create view public.handstock_movements as
-- 1. Stock out from Stores (+)
select
  'IN'::text                                        as direction,
  'Stock out'::text                                 as movement,
  public.handstock_key(r.engineer)                  as engineer_key,
  coalesce(r.engineer, '')                          as engineer,
  coalesce(r.engineer_email, '')                    as engineer_email,
  public.part_code(l.part)                          as part_code,
  coalesce(l.part, '')                              as part,
  coalesce(l.qty, 0)                                as qty,
  coalesce(l.dispatched_at, r.dispatched_at, l.created_at, r.created_at)
                                                    as moved_at,
  coalesce(nullif(l.dc_number, ''), r.or_no, '')    as ref,
  'Stores DC'::text                                 as ref_type,
  coalesce(r.uid, '')                               as ref_uid,
  coalesce(r.ucn, '')                               as ucn,
  coalesce(r.call_number, '')                       as call_number,
  coalesce(r.party_name, '')                        as party_name,
  coalesce(nullif(l.dispatch_remarks, ''), '')      as remarks
from public.spare_request_lines l
join public.spare_requests r on r.uid = l.request_uid
where coalesce(l.stores_status, '') ~* 'dispatch'
union all
-- 2. Consumption on a call (−)
select
  'OUT'::text, 'Consumption'::text,
  public.handstock_key(c.engineer),
  coalesce(c.engineer, ''),
  coalesce(c.engineer_email, ''),
  public.part_code(c.part),
  coalesce(c.part, ''),
  coalesce(c.qty, 0),
  c.created_at,
  coalesce(nullif(btrim(c.call_number), ''), coalesce(c.ucn, '')),
  'Call'::text,
  ''::text,
  coalesce(c.ucn, ''),
  coalesce(c.call_number, ''),
  ''::text,
  ''::text
from public.spare_consumption c
union all
-- 3. Stock transfer FROM this engineer (−)
select
  'OUT'::text, 'Transfer out'::text,
  public.handstock_key(t.from_engineer),
  coalesce(t.from_engineer, ''),
  ''::text,
  public.part_code(l.part),
  coalesce(l.part, ''),
  coalesce(l.qty, 0),
  coalesce(t.transfer_date::timestamptz, t.created_at),
  coalesce(t.uid, ''),
  'Transfer'::text,
  ''::text,
  ''::text,
  ''::text,
  coalesce(t.to_engineer, ''),                      -- who it went to
  coalesce(t.remarks, '')
from public.stock_transfer_lines l
join public.stock_transfers t on t.uid = l.transfer_uid
union all
-- 4. Stock transfer TO this engineer (+)
select
  'IN'::text, 'Transfer in'::text,
  public.handstock_key(t.to_engineer),
  coalesce(t.to_engineer, ''),
  ''::text,
  public.part_code(l.part),
  coalesce(l.part, ''),
  coalesce(l.qty, 0),
  coalesce(t.transfer_date::timestamptz, t.created_at),
  coalesce(t.uid, ''),
  'Transfer'::text,
  ''::text,
  ''::text,
  ''::text,
  coalesce(t.from_engineer, ''),                    -- who it came from
  coalesce(t.remarks, '')
from public.stock_transfer_lines l
join public.stock_transfers t on t.uid = l.transfer_uid;

-- ---------------------------------------------------------------------------
-- The stock level, one row per engineer + spare, with each term of the formula
-- kept separate so a figure can be argued with.
--
-- A negative level is not an error to hide: it means more was consumed or
-- handed on than this module has seen issued — stock carried from before the
-- register existed, or a spare taken without a DC.
-- ---------------------------------------------------------------------------
create view public.handstock_balance as
select
  m.engineer_key,
  max(m.engineer)                                                       as engineer,
  max(m.engineer_email)                                                 as engineer_email,
  m.part_code,
  -- the catalogue string as the parts master spells it: prefer a Stores
  -- dispatch's, since a consumption row may carry an older wording.
  coalesce(max(m.part) filter (where m.movement = 'Stock out'), max(m.part))
                                                                        as part,
  sum(case when m.movement = 'Stock out'    then m.qty else 0 end)      as stock_out,
  sum(case when m.movement = 'Consumption'  then m.qty else 0 end)      as consumed,
  sum(case when m.movement = 'Transfer in'  then m.qty else 0 end)      as transferred_in,
  sum(case when m.movement = 'Transfer out' then m.qty else 0 end)      as transferred_out,
  sum(case when m.direction = 'IN' then m.qty else -m.qty end)          as on_hand,
  max(m.moved_at) filter (where m.direction = 'IN')                     as last_in,
  max(m.moved_at) filter (where m.direction = 'OUT')                    as last_out,
  max(m.moved_at)                                                       as last_movement,
  count(*)                                                              as movements
from public.handstock_movements m
where m.engineer_key <> '' and m.part_code <> ''
group by m.engineer_key, m.part_code;

-- ---------------------------------------------------------------------------
-- The Stock Transfer screen (and the guard that stops a transfer overdrawing)
-- read `engineer_stock`. Point it at the balance above rather than leaving a
-- second, differently-wrong derivation behind: same columns, same meaning, one
-- set of rules. `engineer_stock_available()` and both screens follow.
--
-- NB: definer-rights functions read this view, so it stays as 0020 created it
-- — NOT security_invoker.
-- ---------------------------------------------------------------------------
create view public.engineer_stock as
select b.engineer_key as engineer, b.part, b.on_hand as qty
  from public.handstock_balance b;

grant select on public.engineer_stock to authenticated;

alter view public.handstock_movements set (security_invoker = on);
alter view public.handstock_balance   set (security_invoker = on);

grant select on public.handstock_movements to authenticated;
grant select on public.handstock_balance   to authenticated;

-- ---------------------------------------------------------------------------
-- Access. `mod:/handstock` is on no role until granted; append it —
-- additively — to every role that can already open the Spare Requests
-- register, leaving anything an admin has since edited alone.
-- (`stock.transfer` and `mod:/stock-transfer` belong to 0020_stock_transfer.)
-- ---------------------------------------------------------------------------
update public.app_roles
   set permissions = coalesce(permissions, '[]'::jsonb) || '["mod:/handstock"]'::jsonb,
       updated_at  = now()
 where coalesce(permissions, '[]'::jsonb) ? 'mod:/spare-requests'
   and not coalesce(permissions, '[]'::jsonb) ? 'mod:/handstock';

-- ------------------------------------------------------------------------
-- 0038_spare_consumption_scope.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Spare consumption / Hand Stock — scope to my own & my team, like calls.
--
-- cons_read granted every consumption.view holder ALL rows; the client then
-- filtered by engineer, which fails open when the viewer's name/email doesn't
-- resolve. So an engineer could see a peer's consumption (and, via the
-- security_invoker handstock views, a peer's hand stock).
--
-- Now the database scopes it: admins, the office/coordination roles and a
-- data.view_all holder see everything (they reconcile across engineers);
-- everyone else sees only rows they raised, that are for their own email, or
-- that belong to an engineer in their reporting sub-tree. spare_requests and
-- its lines are already scoped this way; the handstock_balance /
-- handstock_movements views are security_invoker, so they inherit this.
-- ===========================================================================

-- The email this policy matches on is added by 0023_handstock.sql, which the
-- consolidated file applies long AFTER this one — so add it here too rather
-- than depend on an ordering that does not hold. Idempotent either way.
alter table public.spare_consumption
  add column if not exists engineer_email text default '';

drop policy if exists cons_read on public.spare_consumption;
create policy cons_read on public.spare_consumption for select
  using (
    (select public.can_view_all_calls())          -- admin + office roles + data.view_all
    or created_by = (select auth.uid())
    or lower(engineer_email) = lower((select auth.email()))
    or lower(trim(engineer)) in (
         select lower(trim(n)) from public.visible_engineer_names() as v(n)
       )
  );

-- ------------------------------------------------------------------------
-- 0039_material_returns.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- MRN — Material Return Note.
--
-- The engineer sends a spare back to Stores. It is the fifth movement of hand
-- stock and the second one that takes stock OUT of the engineer's hands:
--
--   Stock Level = Stock Out (Stores) − Consumption
--               − Transfer From + Transfer To
--               − Returned (MRN)
--
-- Shape: the sheet kept this in two tabs — a form-data tab (one row per
-- submission: SI number, MRN No, MRN Date, engineer) and a register tab (one
-- row per item, repeating the header). That is flattened here into ONE table,
-- one row per returned item, carrying its own MRN header fields, grouped by
-- `uid` so a submission returning five spares is five rows sharing one uid.
--
-- An engineer may only return what they are holding: the quantity is capped in
-- the form and enforced here, so no route can drive a hand-stock level
-- negative through a return.
-- ===========================================================================

create table if not exists public.material_returns (
  id              bigint generated always as identity primary key,
  uid             text not null,              -- one submission: MRN-YYMM-NNNN (or the sheet's SI number)
  row_no          int,                        -- the item's position within the submission
  mrn_no          text default '',            -- the physical MRN slip number the engineer writes
  mrn_date        date,                       -- the date on that slip
  engineer        text not null default '',
  engineer_email  text default '',
  part            text not null default '',   -- CODE|Description, as everywhere else
  item_code       text default '',            -- kept as its own column: the sheet exports it separately
  item_name       text default '',
  good_qty        numeric not null default 0,
  defective_qty   numeric not null default 0,
  -- The rest of the sheet's form fields. All 'NA' in the history, but the form
  -- asks for them, so they keep their place rather than being dropped.
  customer_name   text default '',
  report_no       text default '',
  removed_from_equipment text default '',
  handstock_note  text default '',
  remarks         text default '',
  source          text default 'app',         -- 'app' | 'import'
  returned_at     timestamptz not null default now(),
  created_at      timestamptz not null default now(),
  created_by      uuid references auth.users (id) default auth.uid(),
  constraint material_returns_qty_positive check (coalesce(good_qty, 0) + coalesce(defective_qty, 0) > 0)
);

create index if not exists material_returns_uid_idx      on public.material_returns (uid);
create index if not exists material_returns_engineer_idx on public.material_returns (lower(btrim(engineer)));
create index if not exists material_returns_date_idx     on public.material_returns (mrn_date desc nulls last);
-- The import re-runs; one row per (submission, item) is the natural identity.
create unique index if not exists material_returns_uid_part_idx
  on public.material_returns (uid, public.part_code(part), coalesce(row_no, 0));

-- ---------------------------------------------------------------------------
-- MRN numbers follow the OR / ST convention: MRN-YYMM-NNNN, restarting each
-- month. The sheet's own SI numbers are kept as-is on imported rows.
-- ---------------------------------------------------------------------------
create table if not exists public.material_return_counters (
  period  text primary key,          -- 'YY/MM'
  last_no integer not null default 0
);
alter table public.material_return_counters enable row level security;  -- definer-only

create or replace function public.next_mrn_uid(p_on date default current_date)
returns text language plpgsql security definer set search_path = public as $$
declare p text := to_char(p_on, 'YY/MM'); n integer;
begin
  insert into public.material_return_counters (period, last_no) values (p, 1)
  on conflict (period) do update set last_no = public.material_return_counters.last_no + 1
  returning last_no into n;
  return 'MRN-' || to_char(p_on, 'YYMM') || '-' || lpad(n::text, 4, '0');
end $$;
grant execute on function public.next_mrn_uid(date) to authenticated;

-- Row numbers restart at 1 within a submission, as they do on a spare request.
create or replace function public.material_returns_assign_row_no()
returns trigger language plpgsql security definer set search_path = public as $$
declare n int;
begin
  if new.uid is null or btrim(new.uid) = '' then
    new.uid := public.next_mrn_uid(coalesce(new.mrn_date, current_date));
  end if;
  if new.row_no is null then
    select coalesce(max(row_no), 0) + 1 into n from public.material_returns where uid = new.uid;
    new.row_no := n;
  end if;
  -- The item code and the catalogue string are two views of one thing; fill
  -- whichever the caller left empty rather than letting them drift apart.
  if btrim(coalesce(new.item_code, '')) = '' then new.item_code := public.part_code(new.part); end if;
  if btrim(coalesce(new.part, '')) = '' and btrim(coalesce(new.item_code, '')) <> '' then
    new.part := btrim(new.item_code) || '|' || coalesce(new.item_name, '');
  end if;
  return new;
end $$;

drop trigger if exists material_returns_assign_row_no on public.material_returns;
create trigger material_returns_assign_row_no
  before insert on public.material_returns
  for each row execute function public.material_returns_assign_row_no();

-- ---------------------------------------------------------------------------
-- A return is a record of something that happened. Correcting one means
-- another entry, not an edit; only an admin may amend.
-- ---------------------------------------------------------------------------
create or replace function public.material_returns_immutable()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if public.is_admin() then return new; end if;
  raise exception 'A material return cannot be edited — raise a correcting entry instead';
end $$;

drop trigger if exists material_returns_immutable on public.material_returns;
create trigger material_returns_immutable
  before update on public.material_returns
  for each row execute function public.material_returns_immutable();

alter table public.material_returns enable row level security;

-- Reading follows the reporting tree, in the same shape as spare consumption
-- (0038): the reconciling roles see everything, everyone else sees their own
-- returns and their sub-tree's. The handstock views are security_invoker, so a
-- peer's return stays out of a peer's movement trail too.
drop policy if exists mr_read on public.material_returns;
create policy mr_read on public.material_returns for select
  using (
    (select public.can_view_all_calls())        -- admin + office roles + data.view_all
    or created_by = (select auth.uid())
    or lower(coalesce(engineer_email, '')) = lower((select auth.email()))
    or lower(btrim(engineer)) in (select lower(btrim(n)) from public.visible_engineer_names() as v(n))
  );

-- Raising one needs stock.return, and an engineer may only return their own
-- stock (anyone who may act for others — admin, Stores, an approver — can
-- record one on their behalf).
drop policy if exists mr_insert on public.material_returns;
create policy mr_insert on public.material_returns for insert
  with check (
    public.has_perm('stock.return')
    and (public.is_admin()
         or public.can_approve_spares()
         or lower(coalesce(engineer_email, '')) = lower(auth.email()))
  );

drop policy if exists mr_delete on public.material_returns;
create policy mr_delete on public.material_returns for delete using (public.is_admin());

grant select, insert on public.material_returns to authenticated;

-- ---------------------------------------------------------------------------
-- Hand stock: the fifth movement.
--
-- Both quantities leave the engineer's hands — a defective spare is on its way
-- back to Stores just as a good one is — so the movement is good + defective.
-- ---------------------------------------------------------------------------
create or replace view public.handstock_movements as
-- 1. Stock out from Stores (+)
select
  'IN'::text                                        as direction,
  'Stock out'::text                                 as movement,
  public.handstock_key(r.engineer)                  as engineer_key,
  coalesce(r.engineer, '')                          as engineer,
  coalesce(r.engineer_email, '')                    as engineer_email,
  public.part_code(l.part)                          as part_code,
  coalesce(l.part, '')                              as part,
  coalesce(l.qty, 0)                                as qty,
  coalesce(l.dispatched_at, r.dispatched_at, l.created_at, r.created_at)
                                                    as moved_at,
  coalesce(nullif(l.dc_number, ''), r.or_no, '')    as ref,
  'Stores DC'::text                                 as ref_type,
  coalesce(r.uid, '')                               as ref_uid,
  coalesce(r.ucn, '')                               as ucn,
  coalesce(r.call_number, '')                       as call_number,
  coalesce(r.party_name, '')                        as party_name,
  coalesce(nullif(l.dispatch_remarks, ''), '')      as remarks
from public.spare_request_lines l
join public.spare_requests r on r.uid = l.request_uid
where coalesce(l.stores_status, '') ~* 'dispatch'
union all
-- 2. Consumption on a call (−)
select
  'OUT'::text, 'Consumption'::text,
  public.handstock_key(c.engineer),
  coalesce(c.engineer, ''),
  coalesce(c.engineer_email, ''),
  public.part_code(c.part),
  coalesce(c.part, ''),
  coalesce(c.qty, 0),
  c.created_at,
  coalesce(nullif(btrim(c.call_number), ''), coalesce(c.ucn, '')),
  'Call'::text,
  ''::text,
  coalesce(c.ucn, ''),
  coalesce(c.call_number, ''),
  ''::text,
  ''::text
from public.spare_consumption c
union all
-- 3. Stock transfer FROM this engineer (−)
select
  'OUT'::text, 'Transfer out'::text,
  public.handstock_key(t.from_engineer),
  coalesce(t.from_engineer, ''),
  ''::text,
  public.part_code(l.part),
  coalesce(l.part, ''),
  coalesce(l.qty, 0),
  coalesce(t.transfer_date::timestamptz, t.created_at),
  coalesce(t.uid, ''),
  'Transfer'::text,
  ''::text,
  ''::text,
  ''::text,
  coalesce(t.to_engineer, ''),                      -- who it went to
  coalesce(t.remarks, '')
from public.stock_transfer_lines l
join public.stock_transfers t on t.uid = l.transfer_uid
union all
-- 4. Stock transfer TO this engineer (+)
select
  'IN'::text, 'Transfer in'::text,
  public.handstock_key(t.to_engineer),
  coalesce(t.to_engineer, ''),
  ''::text,
  public.part_code(l.part),
  coalesce(l.part, ''),
  coalesce(l.qty, 0),
  coalesce(t.transfer_date::timestamptz, t.created_at),
  coalesce(t.uid, ''),
  'Transfer'::text,
  ''::text,
  ''::text,
  ''::text,
  coalesce(t.from_engineer, ''),                    -- who it came from
  coalesce(t.remarks, '')
from public.stock_transfer_lines l
join public.stock_transfers t on t.uid = l.transfer_uid
union all
-- 5. Returned to Stores on an MRN (−)
select
  'OUT'::text, 'Return'::text,
  public.handstock_key(m.engineer),
  coalesce(m.engineer, ''),
  coalesce(m.engineer_email, ''),
  public.part_code(m.part),
  coalesce(m.part, ''),
  coalesce(m.good_qty, 0) + coalesce(m.defective_qty, 0),
  coalesce(m.mrn_date::timestamptz, m.returned_at, m.created_at),
  coalesce(nullif(btrim(m.mrn_no), ''), m.uid, ''),
  'MRN'::text,
  coalesce(m.uid, ''),
  ''::text,
  coalesce(m.report_no, ''),
  coalesce(m.customer_name, ''),
  btrim(
    case when coalesce(m.defective_qty, 0) > 0
         then 'good ' || coalesce(m.good_qty, 0) || ', defective ' || m.defective_qty || ' · ' else '' end
    || coalesce(m.remarks, '')
  )
from public.material_returns m;

-- ---------------------------------------------------------------------------
-- The balance gains its own column for what has been returned, so the level
-- stays arguable term by term.
--
-- `create or replace view` cannot insert a column in the middle of an existing
-- view, so the balance and the view over it are dropped and rebuilt. Both are
-- derived — there is nothing in them to lose.
-- ---------------------------------------------------------------------------
drop view if exists public.engineer_stock;
drop view if exists public.handstock_balance;

create view public.handstock_balance as
select
  m.engineer_key,
  max(m.engineer)                                                       as engineer,
  max(m.engineer_email)                                                 as engineer_email,
  m.part_code,
  coalesce(max(m.part) filter (where m.movement = 'Stock out'), max(m.part))
                                                                        as part,
  sum(case when m.movement = 'Stock out'    then m.qty else 0 end)      as stock_out,
  sum(case when m.movement = 'Consumption'  then m.qty else 0 end)      as consumed,
  sum(case when m.movement = 'Transfer in'  then m.qty else 0 end)      as transferred_in,
  sum(case when m.movement = 'Transfer out' then m.qty else 0 end)      as transferred_out,
  sum(case when m.movement = 'Return'       then m.qty else 0 end)      as returned,
  sum(case when m.direction = 'IN' then m.qty else -m.qty end)          as on_hand,
  max(m.moved_at) filter (where m.direction = 'IN')                     as last_in,
  max(m.moved_at) filter (where m.direction = 'OUT')                    as last_out,
  max(m.moved_at)                                                       as last_movement,
  count(*)                                                              as movements
from public.handstock_movements m
where m.engineer_key <> '' and m.part_code <> ''
group by m.engineer_key, m.part_code;

alter view public.handstock_movements set (security_invoker = on);
alter view public.handstock_balance   set (security_invoker = on);

grant select on public.handstock_movements to authenticated;
grant select on public.handstock_balance   to authenticated;

-- `engineer_stock` is a view over the balance (0023), so the Stock Transfer
-- screen and its overdraw guard pick the return up with no change of their own.
create view public.engineer_stock as
select b.engineer_key as engineer, b.part, b.on_hand as qty
  from public.handstock_balance b;
grant select on public.engineer_stock to authenticated;

-- ---------------------------------------------------------------------------
-- An engineer cannot return what they are not holding. Checked AFTER the row
-- lands, so the view already accounts for it — which also catches a multi-row
-- insert whose rows would individually pass but together over-draw.
--
-- Imported history is exempt: the sheet's returns predate the stock ledger
-- they would be checked against, and refusing them would make the import
-- impossible. They are loaded as `source = 'import'`.
-- ---------------------------------------------------------------------------
create or replace function public.material_returns_check_stock()
returns trigger language plpgsql security definer set search_path = public as $$
declare bal numeric;
begin
  if coalesce(new.source, 'app') = 'import' then return null; end if;
  bal := public.engineer_stock_available(new.engineer, new.part);
  if bal < 0 then
    -- bal is the balance AFTER this row, so a negative is the shortfall.
    raise exception
      'Material return exceeds hand stock: % would be left with % of %',
      new.engineer, bal, public.part_code(new.part);
  end if;
  return null;
end $$;

drop trigger if exists material_returns_check_stock on public.material_returns;
create trigger material_returns_check_stock
  after insert on public.material_returns
  for each row execute function public.material_returns_check_stock();

-- ---------------------------------------------------------------------------
-- Access. Neither key is on any role until granted.
--   mod:/mrn       opens the register.
--   stock.return   records a return (own stock, unless you may act for others).
-- Granted additively to the roles that already hold or move spares, plus
-- Stores, who receive the returned parts.
-- ---------------------------------------------------------------------------
update public.app_roles
   set permissions = coalesce(permissions, '[]'::jsonb) || '["stock.return","mod:/mrn"]'::jsonb,
       updated_at  = now()
 where role in ('admin', 'engineer', 'rm', 'rgm', 'spare_coordinator', 'stores_incharge')
   and not coalesce(permissions, '[]'::jsonb) ? 'stock.return';

-- Anyone who can already open Hand Stock can read the MRN register.
update public.app_roles
   set permissions = coalesce(permissions, '[]'::jsonb) || '["mod:/mrn"]'::jsonb,
       updated_at  = now()
 where coalesce(permissions, '[]'::jsonb) ? 'mod:/handstock'
   and not coalesce(permissions, '[]'::jsonb) ? 'mod:/mrn';

-- ------------------------------------------------------------------------
-- 0041_stock_read_scope.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Hand Stock, Stock Transfer and Material Returns follow the same rule as
-- Spare Requests: your own, and your reporting engineers' — nothing else.
--
-- After 0040 scoped the spare register, two gaps were left on the stock side.
--
-- 1. `engineer_stock` was NOT security_invoker, so it ran with the view
--    owner's rights and bypassed row-level security altogether. The Stock
--    Transfer screen reads it through listAllStock() — "every engineer's
--    holding" — so any signed-in user could see every engineer's stock levels,
--    whatever the policies on the tables underneath said.
--
--    0023 deliberately left it definer-rights because engineer_stock_available()
--    reads it. That still works: engineer_stock_available() is SECURITY
--    DEFINER, so inside it the current user is the view's owner, who is not
--    subject to RLS — the overdraw guard keeps seeing every movement, which is
--    exactly what a correctness check needs, while the SCREEN sees only what
--    the person may see.
--
-- 2. `st_read` on stock_transfers was scoped to the reporting tree but tested
--    is_admin() alone, so the office desks — Commercial, NSM, Stores, Hotline,
--    Spare Coordinator, Tally — could not see transfers at all. Everywhere
--    else that is can_view_all_calls(); this brings transfers into line.
--
-- Hand Stock itself needs no change: handstock_balance and handstock_movements
-- are already security_invoker, so they inherit from spare_request_lines (via
-- spare_requests, 0040), spare_consumption (0038) and stock_transfers (below).
-- Material Returns needs none either: mr_read already reads this way.
-- ===========================================================================

-- 1. The derived stock level now answers as the person asking.
alter view public.engineer_stock set (security_invoker = on);

-- 2. Transfers: the desks that move stock for every team can see them.
drop policy if exists st_read on public.stock_transfers;
create policy st_read on public.stock_transfers for select
  using (
    (select public.can_view_all_calls())          -- admin + office desks + data.view_all
    or created_by = (select auth.uid())
    or lower(btrim(from_engineer)) in (
         select lower(btrim(n)) from public.visible_engineer_names() as v(n))
    or lower(btrim(to_engineer)) in (
         select lower(btrim(n)) from public.visible_engineer_names() as v(n))
  );

-- ------------------------------------------------------------------------
-- 0055_partial_dispatch.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- PARTIAL DISPATCH — Stores can send fewer units than were requested.
--
-- Before: a spare line was dispatched whole. If an engineer asked for 2 and
-- Stores had 1, the only options were to send nothing or to pretend 2 went out.
--
-- Now: each stock out records HOW MANY of each line it carried. A line keeps
-- its requested qty (the request of record is never rewritten); what has gone
-- out accumulates in spare_request_lines.dispatched_qty, and the line stays in
-- the Stores queue for the REMAINDER until it is fully sent.
--
--   requested 2, dispatched 1  ->  queue shows 1 still to send
--   requested 2, dispatched 2  ->  line leaves the queue (as before)
--
-- A line can now belong to several stock outs, which a single dispatch_uid
-- column cannot express, so the per-dispatch quantities live in their own
-- table (spare_dispatch_lines) — that is what a DC prints. Existing dispatches
-- are back-filled into it, so history and hand stock stay uniform: there is no
-- "old way" left to special-case.
-- ===========================================================================

-- ---- 1. what has gone out, per line ---------------------------------------
alter table public.spare_request_lines
  add column if not exists dispatched_qty numeric not null default 0;

-- ---- 2. what each stock out carried ---------------------------------------
create table if not exists public.spare_dispatch_lines (
  id           bigint generated always as identity primary key,
  dispatch_uid text   not null,                       -- spare_dispatches.uid (SO-…)
  line_id      bigint not null references public.spare_request_lines (id) on delete cascade,
  line_uid     text   default '',
  part         text   default '',
  qty          numeric not null default 0,
  created_at   timestamptz not null default now()
);
create index if not exists spare_dispatch_lines_dispatch_idx on public.spare_dispatch_lines (dispatch_uid);
create index if not exists spare_dispatch_lines_line_idx     on public.spare_dispatch_lines (line_id);

alter table public.spare_dispatch_lines enable row level security;
grant select on public.spare_dispatch_lines to authenticated;
-- Read is open to signed-in users; every screen reaches these rows through a
-- join to spare_request_lines / spare_requests, whose own RLS does the scoping.
drop policy if exists sdl_read on public.spare_dispatch_lines;
create policy sdl_read on public.spare_dispatch_lines for select
  using (auth.role() = 'authenticated');
-- Written only by dispatch_spare_lines() (security definer); a direct write
-- still needs the dispatch permission.
drop policy if exists sdl_write on public.spare_dispatch_lines;
create policy sdl_write on public.spare_dispatch_lines for all
  using (public.has_perm('spare.dispatch')) with check (public.has_perm('spare.dispatch'));

-- ---- 3. back-fill history: every already-dispatched line sent its full qty --
update public.spare_request_lines l
   set dispatched_qty = coalesce(l.qty, 0)
 where coalesce(l.dispatched_qty, 0) = 0
   and coalesce(l.stores_status, '') ~* 'dispatch';

insert into public.spare_dispatch_lines (dispatch_uid, line_id, line_uid, part, qty)
select l.dispatch_uid, l.id, coalesce(l.line_uid, ''), coalesce(l.part, ''), coalesce(l.qty, 0)
  from public.spare_request_lines l
 where coalesce(l.dispatch_uid, '') <> ''
   and not exists (select 1 from public.spare_dispatch_lines d where d.line_id = l.id);


-- ---- 4. hand stock counts what was DISPATCHED, not what was asked for ----
create or replace view public.handstock_movements as
-- 1. Stock out from Stores (+)
select
  'IN'::text                                        as direction,
  'Stock out'::text                                 as movement,
  public.handstock_key(r.engineer)                  as engineer_key,
  coalesce(r.engineer, '')                          as engineer,
  coalesce(r.engineer_email, '')                    as engineer_email,
  public.part_code(l.part)                          as part_code,
  coalesce(l.part, '')                              as part,
  -- what actually went out: the recorded dispatched qty when there is one,
  -- else the line's qty (a line marked Dispatched by an import or an older
  -- path sent all of it) — so no stock is ever lost from the ledger.
  case when coalesce(l.dispatched_qty, 0) > 0
       then l.dispatched_qty else coalesce(l.qty, 0) end   as qty,
  coalesce(l.dispatched_at, r.dispatched_at, l.created_at, r.created_at)
                                                    as moved_at,
  coalesce(nullif(l.dc_number, ''), r.or_no, '')    as ref,
  'Stores DC'::text                                 as ref_type,
  coalesce(r.uid, '')                               as ref_uid,
  coalesce(r.ucn, '')                               as ucn,
  coalesce(r.call_number, '')                       as call_number,
  coalesce(r.party_name, '')                        as party_name,
  coalesce(nullif(l.dispatch_remarks, ''), '')      as remarks
from public.spare_request_lines l
join public.spare_requests r on r.uid = l.request_uid
where coalesce(l.dispatched_qty, 0) > 0
   or coalesce(l.stores_status, '') ~* 'dispatch'
union all
-- 2. Consumption on a call (−)
select
  'OUT'::text, 'Consumption'::text,
  public.handstock_key(c.engineer),
  coalesce(c.engineer, ''),
  coalesce(c.engineer_email, ''),
  public.part_code(c.part),
  coalesce(c.part, ''),
  coalesce(c.qty, 0),
  c.created_at,
  coalesce(nullif(btrim(c.call_number), ''), coalesce(c.ucn, '')),
  'Call'::text,
  ''::text,
  coalesce(c.ucn, ''),
  coalesce(c.call_number, ''),
  ''::text,
  ''::text
from public.spare_consumption c
union all
-- 3. Stock transfer FROM this engineer (−)
select
  'OUT'::text, 'Transfer out'::text,
  public.handstock_key(t.from_engineer),
  coalesce(t.from_engineer, ''),
  ''::text,
  public.part_code(l.part),
  coalesce(l.part, ''),
  coalesce(l.qty, 0),
  coalesce(t.transfer_date::timestamptz, t.created_at),
  coalesce(t.uid, ''),
  'Transfer'::text,
  ''::text,
  ''::text,
  ''::text,
  coalesce(t.to_engineer, ''),                      -- who it went to
  coalesce(t.remarks, '')
from public.stock_transfer_lines l
join public.stock_transfers t on t.uid = l.transfer_uid
union all
-- 4. Stock transfer TO this engineer (+)
select
  'IN'::text, 'Transfer in'::text,
  public.handstock_key(t.to_engineer),
  coalesce(t.to_engineer, ''),
  ''::text,
  public.part_code(l.part),
  coalesce(l.part, ''),
  coalesce(l.qty, 0),
  coalesce(t.transfer_date::timestamptz, t.created_at),
  coalesce(t.uid, ''),
  'Transfer'::text,
  ''::text,
  ''::text,
  ''::text,
  coalesce(t.from_engineer, ''),                    -- who it came from
  coalesce(t.remarks, '')
from public.stock_transfer_lines l
join public.stock_transfers t on t.uid = l.transfer_uid
union all
-- 5. Returned to Stores on an MRN (−)
select
  'OUT'::text, 'Return'::text,
  public.handstock_key(m.engineer),
  coalesce(m.engineer, ''),
  coalesce(m.engineer_email, ''),
  public.part_code(m.part),
  coalesce(m.part, ''),
  coalesce(m.good_qty, 0) + coalesce(m.defective_qty, 0),
  coalesce(m.mrn_date::timestamptz, m.returned_at, m.created_at),
  coalesce(nullif(btrim(m.mrn_no), ''), m.uid, ''),
  'MRN'::text,
  coalesce(m.uid, ''),
  ''::text,
  coalesce(m.report_no, ''),
  coalesce(m.customer_name, ''),
  btrim(
    case when coalesce(m.defective_qty, 0) > 0
         then 'good ' || coalesce(m.good_qty, 0) || ', defective ' || m.defective_qty || ' · ' else '' end
    || coalesce(m.remarks, '')
  )
from public.material_returns m;

alter view public.handstock_movements set (security_invoker = on);
grant select on public.handstock_movements to authenticated;

-- ---- 5. the queue shows the REMAINDER --------------------------------------
create or replace view public.spare_pending_dispatch as
select
  l.id                                        as line_id,
  l.line_uid,
  l.request_uid,
  r.or_no,
  r.or_req_date,
  l.row_no,
  l.part,
  upper(btrim(split_part(coalesce(l.part, ''), '|', 1)))
                                              as part_code,
  -- `qty` is what is STILL to send, so every consumer (queue totals, KPI
  -- tiles, the digest) counts outstanding units, not the original ask.
  greatest(coalesce(l.qty, 0) - coalesce(l.dispatched_qty, 0), 0) as qty,
  r.req_type,
  r.item_status,
  coalesce(r.engineer, '')                    as engineer,
  lower(btrim(coalesce(r.engineer, '')))      as engineer_key,
  coalesce(r.engineer_email, '')              as engineer_email,
  coalesce(r.ucn, '')                         as ucn,
  coalesce(r.call_number, '')                 as call_number,
  coalesce(r.party_name, '')                  as party_name,
  coalesce(r.product_name, '')                as product_name,
  coalesce(r.serial, '')                      as serial,
  coalesce(r.handstock_reason, '')            as handstock_reason,
  coalesce(r.remarks, '')                     as remarks,
  l.rm_by, l.rm_at, l.commercial_by, l.commercial_at, l.nsm_by, l.nsm_at,
  coalesce(l.created_at, r.created_at)        as raised_at,
  greatest(coalesce(l.nsm_at, l.commercial_at, l.rm_at, l.created_at, r.created_at),
           coalesce(l.created_at, r.created_at))                       as waiting_since,
  coalesce(l.qty, 0)                          as requested_qty,
  coalesce(l.dispatched_qty, 0)               as dispatched_qty
from public.spare_request_lines l
join public.spare_requests r on r.uid = l.request_uid
-- Computed, not read: the stage column is a cache and may be stale.
where public.spare_line_stage(
        coalesce(l.rm_approval, 'Pending'),
        coalesce(l.commercial_approval, 'Pending'),
        coalesce(l.nsm_approval, 'Pending'),
        coalesce(l.stores_status, 'Pending'),
        l.received_at,
        r.item_status) = 'Stores'
  and coalesce(l.dispatch_uid, '') = ''
  -- a partly-sent line stays queued for its remainder; a fully sent one leaves
  and (coalesce(l.qty, 0) - coalesce(l.dispatched_qty, 0)) > 0;

alter view public.spare_pending_dispatch set (security_invoker = on);
grant select on public.spare_pending_dispatch to authenticated;

-- ---- 6. dispatch, with a quantity per line ---------------------------------
-- p_qtys is parallel to p_line_ids: how many units of that line this stock out
-- carries. NULL (or a null element) means "all that is left". A quantity above
-- the remainder is rejected rather than silently clamped — Stores should see
-- that the queue moved under them.
create or replace function public.dispatch_spare_lines(
  p_line_ids bigint[],
  p_qtys     numeric[],
  p_courier  text default '',
  p_remarks  text default '',
  p_dc_date  date default current_date,
  p_actor    text default ''
) returns public.spare_dispatches
language plpgsql security definer set search_path = public as $$
declare
  eng   text;
  n     integer;
  head  public.spare_dispatches;
  email text;
  i     integer;
  lid   bigint;
  want  numeric;
  rem   numeric;
  send  numeric;
  total numeric := 0;
  cnt   integer := 0;
begin
  if not (public.is_admin() or public.has_perm('spare.dispatch')) then
    raise exception 'RBAC: dispatch requires the spare.dispatch permission';
  end if;
  if p_line_ids is null or array_length(p_line_ids, 1) is null then
    raise exception 'Nothing to dispatch: no spares selected';
  end if;

  select count(*), min(v.engineer), min(v.engineer_email)
    into n, eng, email
    from public.spare_pending_dispatch v
   where v.line_id = any (p_line_ids);
  if coalesce(n, 0) <> array_length(p_line_ids, 1) then
    raise exception
      'Only % of the % selected spares are still waiting at Stores — refresh and try again',
      coalesce(n, 0), array_length(p_line_ids, 1);
  end if;
  if (select count(distinct v.engineer_key) from public.spare_pending_dispatch v
       where v.line_id = any (p_line_ids)) <> 1 then
    raise exception 'A stock out goes to one engineer — select spares for a single engineer';
  end if;

  insert into public.spare_dispatches
    (dc_date, engineer, engineer_email, courier, remarks, line_count, total_qty, dispatched_by)
  values
    (coalesce(p_dc_date, current_date), eng, coalesce(email, ''), coalesce(p_courier, ''),
     coalesce(p_remarks, ''), 0, 0, coalesce(nullif(btrim(p_actor), ''), ''))
  returning * into head;

  for i in 1 .. array_length(p_line_ids, 1) loop
    lid  := p_line_ids[i];
    want := case when p_qtys is null then null else p_qtys[i] end;

    select greatest(coalesce(l.qty, 0) - coalesce(l.dispatched_qty, 0), 0)
      into rem from public.spare_request_lines l where l.id = lid;

    send := coalesce(want, rem);
    if send is null or send <= 0 then
      raise exception 'Quantity for spare % must be more than zero', lid;
    end if;
    if send > rem then
      raise exception 'Only % left to send on that spare (you asked for %) — refresh and try again', rem, send;
    end if;

    insert into public.spare_dispatch_lines (dispatch_uid, line_id, line_uid, part, qty)
    select head.uid, l.id, coalesce(l.line_uid, ''), coalesce(l.part, ''), send
      from public.spare_request_lines l where l.id = lid;

    update public.spare_request_lines l
       set dispatched_qty   = coalesce(l.dispatched_qty, 0) + send,
           courier          = coalesce(p_courier, ''),
           dispatch_remarks = coalesce(p_remarks, ''),
           dispatched_by    = head.dispatched_by,
           dispatched_at    = head.dispatched_at,
           -- Fully sent: stamp the stock out and close the line, exactly as
           -- before. Partly sent: leave dispatch_uid / stores_status alone so
           -- the line stays at Stores for its remainder.
           dc_number    = case when coalesce(l.dispatched_qty, 0) + send >= coalesce(l.qty, 0)
                               then head.dc_number else l.dc_number end,
           dispatch_uid = case when coalesce(l.dispatched_qty, 0) + send >= coalesce(l.qty, 0)
                               then head.uid else l.dispatch_uid end,
           stock_out_no = case when coalesce(l.dispatched_qty, 0) + send >= coalesce(l.qty, 0)
                               then head.uid else l.stock_out_no end,
           stores_status = case when coalesce(l.dispatched_qty, 0) + send >= coalesce(l.qty, 0)
                                then 'Dispatched' else l.stores_status end
     where l.id = lid;

    total := total + send;
    cnt   := cnt + 1;
  end loop;

  update public.spare_dispatches d
     set line_count = cnt, total_qty = total
   where d.uid = head.uid
   returning * into head;

  return head;
end $$;
grant execute on function public.dispatch_spare_lines(bigint[], numeric[], text, text, date, text) to authenticated;

-- The original signature still works and means "send everything that is left".
create or replace function public.dispatch_spare_lines(
  p_line_ids bigint[],
  p_courier  text default '',
  p_remarks  text default '',
  p_dc_date  date default current_date,
  p_actor    text default ''
) returns public.spare_dispatches
language sql security definer set search_path = public as $$
  select public.dispatch_spare_lines(p_line_ids, null::numeric[], p_courier, p_remarks, p_dc_date, p_actor);
$$;
grant execute on function public.dispatch_spare_lines(bigint[], text, text, date, text) to authenticated;

-- ------------------------------------------------------------------------
-- 0056_receive_per_shipment.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- ACKNOWLEDGE PER SHIPMENT — receipt follows the stock, not the line.
--
-- With partial dispatch (0055) a line can arrive in several deliveries, so
-- "received" stopped being one moment per line. The engineer now acknowledges
-- each SHIPMENT: every spare_dispatch_lines row is stamped when it lands, and
-- the line carries how much has been acknowledged so far (received_qty).
--
-- The line's own received_at is still what marks it Received — it is set only
-- once the WHOLE line has been acknowledged — so spare_line_stage() and
-- deriveStage() are untouched: a line part-delivered stays at Stores (waiting
-- for its balance) and turns Received when the last unit is confirmed.
-- ===========================================================================

alter table public.spare_request_lines
  add column if not exists received_qty numeric not null default 0;

alter table public.spare_dispatch_lines
  add column if not exists received_at     timestamptz,
  add column if not exists received_by     text default '',
  add column if not exists receipt_remarks text default '';

-- History: a line already acknowledged had all of it acknowledged, and its
-- shipments landed with it. Idempotent.
update public.spare_request_lines l
   set received_qty = coalesce(l.qty, 0)
 where l.received_at is not null and coalesce(l.received_qty, 0) = 0;

update public.spare_dispatch_lines d
   set received_at = l.received_at,
       received_by = coalesce(l.received_by, '')
  from public.spare_request_lines l
 where l.id = d.line_id and d.received_at is null and l.received_at is not null;

-- ---------------------------------------------------------------------------
-- Acknowledge every outstanding shipment on these lines. Returns how many
-- shipments were acknowledged. A line whose whole quantity is now confirmed is
-- closed as Received; one still awaiting a balance stays where it is.
-- ---------------------------------------------------------------------------
create or replace function public.receive_spare_shipments(
  p_line_ids bigint[],
  p_actor    text default '',
  p_remarks  text default ''
) returns integer
language plpgsql security definer set search_path = public as $$
declare n integer := 0; lid bigint; got numeric;
begin
  if not (public.is_admin() or public.has_perm('spare.receive')) then
    raise exception 'RBAC: acknowledging a receipt requires the spare.receive permission';
  end if;
  if p_line_ids is null or array_length(p_line_ids, 1) is null then
    raise exception 'Nothing to acknowledge: no spares selected';
  end if;

  foreach lid in array p_line_ids loop
    update public.spare_dispatch_lines d
       set received_at     = now(),
           received_by     = coalesce(nullif(btrim(p_actor), ''), ''),
           receipt_remarks = coalesce(p_remarks, '')
     where d.line_id = lid and d.received_at is null;
    get diagnostics got = row_count;
    n := n + got;

    -- how much of this line has now been acknowledged
    select coalesce(sum(d.qty), 0) into got
      from public.spare_dispatch_lines d
     where d.line_id = lid and d.received_at is not null;

    update public.spare_request_lines l
       set received_qty = got,
           -- only a fully acknowledged line becomes Received
           received_at     = case when got >= coalesce(l.qty, 0) then now() else l.received_at end,
           received_by     = case when got >= coalesce(l.qty, 0)
                                  then coalesce(nullif(btrim(p_actor), ''), '') else l.received_by end,
           receipt_remarks = case when got >= coalesce(l.qty, 0)
                                  then coalesce(p_remarks, '') else l.receipt_remarks end
     where l.id = lid;
  end loop;

  return n;
end $$;
grant execute on function public.receive_spare_shipments(bigint[], text, text) to authenticated;

-- ------------------------------------------------------------------------
-- 0059_consumption_reconciliation.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- RECONCILIATION CONSUMPTION — an Admin / Spare Coordinator can book a spare
-- against a call directly into consumption, without waiting for the engineer's
-- call report.
--
-- These rows are stock adjustments made by the office, not something the
-- engineer wrote, so they are FLAGGED: `source` is 'Reconciliation' rather than
-- the default 'Report'. Hand stock already treats consumption as stock leaving
-- the engineer's hands, so a reconciliation line corrects the balance the same
-- way a reported one does — the flag is what keeps the two tellable apart.
--
-- Guarded by its own permission (consumption.reconcile) so an engineer cannot
-- write one, and stamped with who entered it. spare_consumption is already an
-- audited table (0048), so every reconciliation carries a full before/after
-- trail.
-- ===========================================================================

alter table public.spare_consumption
  add column if not exists source      text not null default 'Report',   -- Report | Reconciliation
  add column if not exists remarks     text default '',                  -- why the adjustment was made
  add column if not exists recorded_by text default '';                  -- who entered it (name)

create index if not exists spare_consumption_source_idx on public.spare_consumption (source);

-- Stamp the author so the register's Created By stops coming back empty.
create or replace function public.consumption_before_insert()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.created_by is null then new.created_by := auth.uid(); end if;
  if coalesce(new.source, '') = '' then new.source := 'Report'; end if;
  return new;
end $$;
drop trigger if exists consumption_biu on public.spare_consumption;
create trigger consumption_biu before insert on public.spare_consumption
  for each row execute function public.consumption_before_insert();

-- Writing a RECONCILIATION line needs the new permission; an ordinary reported
-- line keeps the existing rule (the engineer reporting, or Stores).
drop policy if exists cons_write on public.spare_consumption;
create policy cons_write on public.spare_consumption for insert
  with check (
    case when coalesce(source, 'Report') = 'Reconciliation'
         then public.has_perm('consumption.reconcile')
         else (public.has_perm('calls.report') or public.has_perm('spare.dispatch'))
    end
  );

-- Grant it to the roles that do the reconciling: Spare Coordinator, Hotline
-- and Admin (merge — anything already tuned on these roles is kept).
do $$
declare r text;
begin
  foreach r in array array['admin', 'spare_coordinator', 'hotline'] loop
    insert into public.app_roles as ar (role, label, permissions)
    values (r, initcap(replace(r, '_', ' ')), '["consumption.reconcile"]'::jsonb)
    on conflict (role) do update set
      permissions = (
        select coalesce(jsonb_agg(distinct v), '[]'::jsonb)
        from (
          select jsonb_array_elements_text(ar.permissions) as v
          union
          select 'consumption.reconcile' as v
        ) u
      ),
      updated_at = now();
  end loop;
end $$;

-- ------------------------------------------------------------------------
-- 0060_reconcile_within_handstock.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- A reconciliation is booked AGAINST A CALL, and cannot consume more than the
-- engineer is holding.
--
-- The office books these lines by hand, so the quantity is typed rather than
-- derived — and a typo would drive an engineer's hand stock negative and
-- quietly corrupt the balance every stock screen reads. The picker only offers
-- parts in that engineer's hand stock, and this guard is the same rule enforced
-- where it cannot be bypassed.
--
-- Only RECONCILIATION rows are capped. A consumption reported from a call is
-- left alone: that is the engineer stating what they actually fitted, and the
-- honest answer to it exceeding the recorded balance is to fix the balance, not
-- to refuse the report.
-- ===========================================================================

create or replace function public.consumption_reconcile_guard()
returns trigger language plpgsql security definer set search_path = public as $$
declare avail numeric;
begin
  if coalesce(new.source, 'Report') <> 'Reconciliation' then return new; end if;
  if coalesce(new.qty, 0) <= 0 then
    raise exception 'Quantity must be more than zero';
  end if;

  -- The UCN is what makes this traceable to a call; without it the line is an
  -- unattributed stock write-off. Required, and it has to be a real call.
  if coalesce(btrim(new.ucn), '') = '' then
    raise exception 'A reconciliation needs the UCN of the call the spare was used on';
  end if;
  if not exists (select 1 from public.calls c where c.ucn = btrim(new.ucn)) then
    raise exception 'No call found with UCN % — check the number', btrim(new.ucn);
  end if;

  -- Every field is required on a hand-booked line: whose stock it came off,
  -- what was used, and why. A stock adjustment with no stated reason is not
  -- auditable, which is the whole point of flagging these separately.
  if coalesce(btrim(new.engineer), '') = '' then
    raise exception 'A reconciliation needs the engineer whose hand stock the spare came off';
  end if;
  if coalesce(btrim(new.part), '') = '' then
    raise exception 'A reconciliation needs the part';
  end if;
  if coalesce(btrim(new.remarks), '') = '' then
    raise exception 'A reconciliation needs a reason (why the spare is being booked by hand)';
  end if;

  select coalesce(b.on_hand, 0) into avail
    from public.handstock_balance b
   where b.engineer_key = public.handstock_key(coalesce(new.engineer, ''))
     and b.part_code    = public.part_code(coalesce(new.part, ''));

  if coalesce(avail, 0) < new.qty then
    raise exception '% has % of % in hand — cannot book % against this call',
      coalesce(nullif(btrim(new.engineer), ''), 'That engineer'),
      coalesce(avail, 0), public.part_code(coalesce(new.part, '')), new.qty;
  end if;
  return new;
end $$;

-- Runs after consumption_biu ('c' < 'r'), so `source` is defaulted before the
-- guard reads it.
drop trigger if exists consumption_reconcile_guard on public.spare_consumption;
create trigger consumption_reconcile_guard before insert on public.spare_consumption
  for each row execute function public.consumption_reconcile_guard();

-- ------------------------------------------------------------------------
-- 0061_cap_all_consumption.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- No consumption may exceed the engineer's hand stock — reported or not.
--
-- 0060 capped only the office's reconciliation lines and deliberately left a
-- call report uncapped, on the reasoning that the engineer is stating what they
-- actually fitted. In practice an engineer can simply key it wrong, and a wrong
-- report drives the balance negative where nobody is watching.
--
-- So the cap now applies to EVERY consumption line. When a report is refused,
-- the fix belongs to the Spare Coordinator: correct the hand stock (dispatch,
-- transfer, or a reconciliation line) and the report goes through. Control of
-- the balance sits with the coordinator, not with whoever typed last.
--
-- Unattributable rows are the one exception: with no engineer or no part there
-- is no balance to check, so those are allowed rather than blocked — refusing
-- them would strand a call report on a data gap the engineer cannot fix.
-- Mandatory UCN / engineer / reason stay specific to reconciliation lines.
-- ===========================================================================

create or replace function public.consumption_reconcile_guard()
returns trigger language plpgsql security definer set search_path = public as $$
declare avail numeric; is_recon boolean;
begin
  is_recon := coalesce(new.source, 'Report') = 'Reconciliation';

  if coalesce(new.qty, 0) <= 0 then
    raise exception 'Quantity must be more than zero';
  end if;

  -- Everything is required on a hand-booked line: whose stock it came off,
  -- what was used, and why. A stock adjustment with no stated reason is not
  -- auditable, which is the point of flagging these separately.
  if is_recon then
    if coalesce(btrim(new.ucn), '') = '' then
      raise exception 'A reconciliation needs the UCN of the call the spare was used on';
    end if;
    if not exists (select 1 from public.calls c where c.ucn = btrim(new.ucn)) then
      raise exception 'No call found with UCN % — check the number', btrim(new.ucn);
    end if;
    if coalesce(btrim(new.engineer), '') = '' then
      raise exception 'A reconciliation needs the engineer whose hand stock the spare came off';
    end if;
    if coalesce(btrim(new.part), '') = '' then
      raise exception 'A reconciliation needs the part';
    end if;
    if coalesce(btrim(new.remarks), '') = '' then
      raise exception 'A reconciliation needs a reason (why the spare is being booked by hand)';
    end if;
  end if;

  -- THE CAP — every line, however it was written. Skipped only when the row
  -- names no engineer or no part, where there is no balance to check.
  if coalesce(btrim(new.engineer), '') = '' or coalesce(btrim(new.part), '') = '' then
    return new;
  end if;

  select coalesce(b.on_hand, 0) into avail
    from public.handstock_balance b
   where b.engineer_key = public.handstock_key(new.engineer)
     and b.part_code    = public.part_code(new.part);

  if coalesce(avail, 0) < new.qty then
    if is_recon then
      raise exception '% has % of % in hand — cannot book % against this call',
        btrim(new.engineer), coalesce(avail, 0), public.part_code(new.part), new.qty;
    else
      raise exception
        '% has % of % in hand, so % cannot be consumed. Ask the Spare Coordinator to correct the hand stock first.',
        btrim(new.engineer), coalesce(avail, 0), public.part_code(new.part), new.qty;
    end if;
  end if;
  return new;
end $$;

drop trigger if exists consumption_reconcile_guard on public.spare_consumption;
create trigger consumption_reconcile_guard before insert on public.spare_consumption
  for each row execute function public.consumption_reconcile_guard();

-- ------------------------------------------------------------------------
-- 0062_adjust_consumption_qty.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- ADJUSTING A CONSUMPTION QUANTITY (part of reconciliation).
--
-- An engineer can report the wrong quantity, and until now nothing could put it
-- right: spare_consumption had no UPDATE policy at all, so the row was frozen
-- and the balance stayed wrong. The Spare Coordinator can now correct the
-- quantity — and only the quantity.
--
-- What is kept:
--   • on the row — original_qty, adjusted_by, adjusted_at and the reason, so
--     the correction is visible where the line is read;
--   • in the audit trail — record_audit (0048) already logs every UPDATE with
--     the full before/after, so nothing depends on the row being honest.
--
-- What cannot be changed: the call, the part, the engineer or the source. A
-- reconciliation corrects a NUMBER; letting it rewrite whose stock or which
-- call would turn an adjustment into a way of rewriting history. Change those
-- by dropping the line and booking the right one.
-- ===========================================================================

alter table public.spare_consumption
  add column if not exists original_qty      numeric,
  add column if not exists adjusted_by       text,
  add column if not exists adjusted_at       timestamptz,
  add column if not exists adjustment_reason text;

-- Correcting a line is the reconciler's job, same permission as booking one.
drop policy if exists cons_update on public.spare_consumption;
create policy cons_update on public.spare_consumption for update
  using (public.has_perm('consumption.reconcile'))
  with check (public.has_perm('consumption.reconcile'));

create or replace function public.consumption_adjust_guard()
returns trigger language plpgsql security definer set search_path = public as $$
declare avail numeric; delta numeric;
begin
  -- Identity is fixed: a reconciliation adjusts the quantity, nothing else.
  if coalesce(new.ucn, '')      is distinct from coalesce(old.ucn, '')
  or coalesce(new.part, '')     is distinct from coalesce(old.part, '')
  or coalesce(new.engineer, '') is distinct from coalesce(old.engineer, '')
  or coalesce(new.source, '')   is distinct from coalesce(old.source, '') then
    raise exception 'A reconciliation can only change the quantity — not the call, part, engineer or source';
  end if;

  if new.qty is not distinct from old.qty then
    return new;                        -- nothing quantitative changed
  end if;
  if coalesce(new.qty, 0) <= 0 then
    raise exception 'Quantity must be more than zero';
  end if;
  if coalesce(btrim(new.adjustment_reason), '') = '' then
    raise exception 'Say why the quantity is being adjusted — the reason is kept with the line';
  end if;

  -- Raising it consumes more stock: the extra has to be in hand. on_hand
  -- already accounts for the quantity this line consumes today, so only the
  -- DELTA is checked. Lowering it always gives stock back.
  delta := new.qty - old.qty;
  if delta > 0 and coalesce(btrim(new.engineer), '') <> '' and coalesce(btrim(new.part), '') <> '' then
    select coalesce(b.on_hand, 0) into avail
      from public.handstock_balance b
     where b.engineer_key = public.handstock_key(new.engineer)
       and b.part_code    = public.part_code(new.part);
    if coalesce(avail, 0) < delta then
      raise exception '% has % of % in hand — cannot raise this line from % to %',
        btrim(new.engineer), coalesce(avail, 0), public.part_code(new.part), old.qty, new.qty;
    end if;
  end if;

  -- Keep what it was before the FIRST adjustment, and stamp who/when.
  if new.original_qty is null then new.original_qty := old.qty; end if;
  new.adjusted_at := now();
  if coalesce(btrim(new.adjusted_by), '') = '' then
    new.adjusted_by := coalesce((select full_name from public.profiles where id = auth.uid()), '');
  end if;
  return new;
end $$;

drop trigger if exists consumption_adjust_guard on public.spare_consumption;
create trigger consumption_adjust_guard before update on public.spare_consumption
  for each row execute function public.consumption_adjust_guard();

-- ------------------------------------------------------------------------
-- 0063_void_consumption_line.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- VOIDING a consumption line — setting the quantity to zero.
--
-- A spare booked against the wrong call, or never actually fitted, has to come
-- off the balance. Deleting the row is not an option and should not be: these
-- are quality records, hard deletes are blocked (0049), and a line that simply
-- vanishes takes its history with it.
--
-- So a line is VOIDED instead: the quantity goes to 0, the row stays, and the
-- original quantity, the reason and who did it stay with it. Hand stock treats
-- a zero-quantity line as consuming nothing, so the spare returns to the
-- engineer's balance — which is exactly what "it was never used" means.
--
-- Creating a line at zero is still refused: an entry that consumes nothing is
-- not something to write in the first place. Zero is only reachable by voiding
-- something that already exists.
-- ===========================================================================

create or replace function public.consumption_adjust_guard()
returns trigger language plpgsql security definer set search_path = public as $$
declare avail numeric; delta numeric;
begin
  if coalesce(new.ucn, '')      is distinct from coalesce(old.ucn, '')
  or coalesce(new.part, '')     is distinct from coalesce(old.part, '')
  or coalesce(new.engineer, '') is distinct from coalesce(old.engineer, '')
  or coalesce(new.source, '')   is distinct from coalesce(old.source, '') then
    raise exception 'A reconciliation can only change the quantity — not the call, part, engineer or source';
  end if;

  if new.qty is not distinct from old.qty then
    return new;
  end if;
  -- 0 is allowed here (voiding); negative never is.
  if coalesce(new.qty, 0) < 0 then
    raise exception 'Quantity cannot be negative — set it to 0 to void the line';
  end if;
  if coalesce(btrim(new.adjustment_reason), '') = '' then
    raise exception 'Say why the quantity is being adjusted — the reason is kept with the line';
  end if;

  delta := new.qty - old.qty;
  if delta > 0 and coalesce(btrim(new.engineer), '') <> '' and coalesce(btrim(new.part), '') <> '' then
    select coalesce(b.on_hand, 0) into avail
      from public.handstock_balance b
     where b.engineer_key = public.handstock_key(new.engineer)
       and b.part_code    = public.part_code(new.part);
    if coalesce(avail, 0) < delta then
      raise exception '% has % of % in hand — cannot raise this line from % to %',
        btrim(new.engineer), coalesce(avail, 0), public.part_code(new.part), old.qty, new.qty;
    end if;
  end if;

  if new.original_qty is null then new.original_qty := old.qty; end if;
  new.adjusted_at := now();
  if coalesce(btrim(new.adjusted_by), '') = '' then
    new.adjusted_by := coalesce((select full_name from public.profiles where id = auth.uid()), '');
  end if;
  return new;
end $$;

-- ------------------------------------------------------------------------
-- 0064_stock_out_lines_and_refurb.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- STOCK OUT — a flat line list, time-to-dispatch, and refurbished parts.
--
-- 1. spare_stock_out_lines: one row per spare actually issued, rather than one
--    card per stock out. It carries the call and the order it came from, and
--    DAYS TO DISPATCH — measured from the moment the spare cleared its LAST
--    approval (NSM where the item needs that review, else Commercial, else RM)
--    to the moment Stores booked it out. That is the interval Stores actually
--    controls; counting from the request would measure the approvers instead.
--
-- 2. Refurbished parts. A recycled spare carries the same description under an
--    R-prefixed part number (ECG-022 -> RECG-022). Stores records the swap as
--    it books the spare out; the DC and the engineer's notification then both
--    say plainly that the part is refurbished.
--
--    NOTE: hand stock continues to key on the REQUESTED part code, so balances
--    and consumption are unaffected by the swap. The refurbished identity is
--    recorded on the issue and shown to the engineer. Tracking R-parts as
--    separate stock lines would be a further change.
-- ===========================================================================

alter table public.spare_dispatch_lines
  add column if not exists refurbished boolean not null default false;

-- ---- the flat list ---------------------------------------------------------
create or replace view public.spare_stock_out_lines as
select
  dl.id                                   as line_id,
  d.uid                                   as stock_out_no,
  coalesce(d.dc_number, '')               as dc_number,
  d.dc_date,
  d.dispatched_at,
  coalesce(d.dispatched_by, '')           as dispatched_by,
  coalesce(d.courier, '')                 as courier,
  coalesce(d.engineer, '')                as engineer,
  lower(btrim(coalesce(d.engineer, '')))  as engineer_key,
  coalesce(d.engineer_email, '')          as engineer_email,
  coalesce(dl.line_uid, '')               as line_uid,
  coalesce(dl.part, '')                   as part,
  public.part_code(dl.part)               as part_code,
  dl.qty,
  dl.refurbished,
  dl.received_at,
  coalesce(r.or_no, '')                   as or_no,
  coalesce(r.req_type, '')                as req_type,
  coalesce(r.item_status, '')             as item_status,
  coalesce(r.ucn, '')                     as ucn,
  coalesce(r.call_number, '')             as call_number,
  coalesce(r.party_name, '')              as party_name,
  coalesce(r.product_name, '')            as product_name,
  coalesce(r.serial, '')                  as serial,
  -- when it cleared its last approval and became Stores' to send
  coalesce(greatest(l.rm_at, l.commercial_at, l.nsm_at), l.created_at, r.created_at)
                                          as approved_at,
  -- and how long Stores then took, in days (one decimal)
  round(
    extract(epoch from (
      d.dispatched_at
      - coalesce(greatest(l.rm_at, l.commercial_at, l.nsm_at), l.created_at, r.created_at)
    ))::numeric / 86400.0, 1)              as days_to_dispatch
from public.spare_dispatch_lines dl
join public.spare_dispatches      d on d.uid = dl.dispatch_uid
join public.spare_request_lines   l on l.id  = dl.line_id
join public.spare_requests        r on r.uid = l.request_uid;

alter view public.spare_stock_out_lines set (security_invoker = on);
grant select on public.spare_stock_out_lines to authenticated;

-- ---- issuing a refurbished part -------------------------------------------
-- p_refurb is parallel to p_line_ids: true issues the recycled equivalent, so
-- the ISSUE records R<code> with the description unchanged. The request itself
-- is untouched — it still says what was asked for.
create or replace function public.refurb_part(p_part text)
returns text language sql immutable as $$
  select case
    when coalesce(btrim(p_part), '') = '' then p_part
    when public.part_code(p_part) like 'R%' then p_part          -- already recycled
    else 'R' || public.part_code(p_part)
         || case when position('|' in p_part) > 0
                 then '|' || split_part(p_part, '|', 2) else '' end
  end;
$$;
grant execute on function public.refurb_part(text) to authenticated;

-- Dispatch, now able to issue a line as its recycled equivalent.
create or replace function public.dispatch_spare_lines(
  p_line_ids bigint[],
  p_qtys     numeric[],
  p_refurb   boolean[],
  p_courier  text default '',
  p_remarks  text default '',
  p_dc_date  date default current_date,
  p_actor    text default ''
) returns public.spare_dispatches
language plpgsql security definer set search_path = public as $$
declare
  eng text; n integer; head public.spare_dispatches; email text;
  i integer; lid bigint; want numeric; rem numeric; send numeric; ref boolean;
  total numeric := 0; cnt integer := 0;
begin
  if not (public.is_admin() or public.has_perm('spare.dispatch')) then
    raise exception 'RBAC: dispatch requires the spare.dispatch permission';
  end if;
  if p_line_ids is null or array_length(p_line_ids, 1) is null then
    raise exception 'Nothing to dispatch: no spares selected';
  end if;

  select count(*), min(v.engineer), min(v.engineer_email) into n, eng, email
    from public.spare_pending_dispatch v where v.line_id = any (p_line_ids);
  if coalesce(n, 0) <> array_length(p_line_ids, 1) then
    raise exception
      'Only % of the % selected spares are still waiting at Stores — refresh and try again',
      coalesce(n, 0), array_length(p_line_ids, 1);
  end if;
  if (select count(distinct v.engineer_key) from public.spare_pending_dispatch v
       where v.line_id = any (p_line_ids)) <> 1 then
    raise exception 'A stock out goes to one engineer — select spares for a single engineer';
  end if;

  insert into public.spare_dispatches
    (dc_date, engineer, engineer_email, courier, remarks, line_count, total_qty, dispatched_by)
  values
    (coalesce(p_dc_date, current_date), eng, coalesce(email, ''), coalesce(p_courier, ''),
     coalesce(p_remarks, ''), 0, 0, coalesce(nullif(btrim(p_actor), ''), ''))
  returning * into head;

  for i in 1 .. array_length(p_line_ids, 1) loop
    lid  := p_line_ids[i];
    want := case when p_qtys   is null then null  else p_qtys[i]   end;
    ref  := case when p_refurb is null then false else coalesce(p_refurb[i], false) end;

    select greatest(coalesce(l.qty, 0) - coalesce(l.dispatched_qty, 0), 0)
      into rem from public.spare_request_lines l where l.id = lid;

    send := coalesce(want, rem);
    if send is null or send <= 0 then
      raise exception 'Quantity for spare % must be more than zero', lid;
    end if;
    if send > rem then
      raise exception 'Only % left to send on that spare (you asked for %) — refresh and try again', rem, send;
    end if;

    insert into public.spare_dispatch_lines (dispatch_uid, line_id, line_uid, part, qty, refurbished)
    select head.uid, l.id, coalesce(l.line_uid, ''),
           case when ref then public.refurb_part(l.part) else coalesce(l.part, '') end,
           send, ref
      from public.spare_request_lines l where l.id = lid;

    update public.spare_request_lines l
       set dispatched_qty   = coalesce(l.dispatched_qty, 0) + send,
           courier          = coalesce(p_courier, ''),
           dispatch_remarks = coalesce(p_remarks, ''),
           dispatched_by    = head.dispatched_by,
           dispatched_at    = head.dispatched_at,
           dc_number    = case when coalesce(l.dispatched_qty, 0) + send >= coalesce(l.qty, 0)
                               then head.dc_number else l.dc_number end,
           dispatch_uid = case when coalesce(l.dispatched_qty, 0) + send >= coalesce(l.qty, 0)
                               then head.uid else l.dispatch_uid end,
           stock_out_no = case when coalesce(l.dispatched_qty, 0) + send >= coalesce(l.qty, 0)
                               then head.uid else l.stock_out_no end,
           stores_status = case when coalesce(l.dispatched_qty, 0) + send >= coalesce(l.qty, 0)
                                then 'Dispatched' else l.stores_status end
     where l.id = lid;

    total := total + send; cnt := cnt + 1;
  end loop;

  update public.spare_dispatches d set line_count = cnt, total_qty = total
   where d.uid = head.uid returning * into head;
  return head;
end $$;
grant execute on function public.dispatch_spare_lines(bigint[], numeric[], boolean[], text, text, date, text) to authenticated;

-- Older signatures keep working: no refurbishment.
create or replace function public.dispatch_spare_lines(
  p_line_ids bigint[], p_qtys numeric[],
  p_courier text default '', p_remarks text default '',
  p_dc_date date default current_date, p_actor text default ''
) returns public.spare_dispatches
language sql security definer set search_path = public as $$
  select public.dispatch_spare_lines(p_line_ids, p_qtys, null::boolean[], p_courier, p_remarks, p_dc_date, p_actor);
$$;

-- The engineer is told when what is coming is a refurbished part.
create or replace function public.notify_spare_dispatched()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_uid uuid; r record; refurb_note text := '';
begin
  if coalesce(new.stores_status, '') !~* 'dispatch' then return new; end if;
  if tg_op = 'UPDATE' and coalesce(old.stores_status, '') ~* 'dispatch' then return new; end if;
  select sr.engineer, sr.engineer_email, sr.ucn, sr.party_name into r
    from public.spare_requests sr where sr.uid = new.request_uid;
  v_uid := public.notify_resolve_uid(r.engineer_email, r.engineer);
  if v_uid is null then return new; end if;

  if exists (select 1 from public.spare_dispatch_lines d
              where d.line_id = new.id and d.refurbished) then
    refurb_note := ' · REFURBISHED part';
  end if;

  insert into public.notifications (recipient_id, recipient_email, kind, title, body, link)
  values (v_uid, coalesce(r.engineer_email, ''), 'spare_dispatched',
          case when refurb_note <> '' then 'Spare dispatched (refurbished)' else 'Spare dispatched' end,
          concat_ws(' · ', nullif(coalesce(new.part, ''), ''), nullif(coalesce(r.ucn, ''), ''),
                    nullif(coalesce(r.party_name, ''), '')) || refurb_note,
          '/spare-requests');
  return new;
end $$;

-- ------------------------------------------------------------------------
-- 0065_refurb_stock_and_part_master.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- A refurbished spare is tracked under its own part number, and the swap is
-- only allowed for a part that exists in Part Master and is ACTIVE.
--
-- 1. Hand stock now counts what was ISSUED (spare_dispatch_lines) rather than
--    what was requested, so a spare issued as RECG-022 appears in the
--    engineer's stock as RECG-022 and is consumed as RECG-022. A legacy arm
--    keeps any line marked Dispatched without issue rows (an import) in the
--    ledger, so no stock is lost.
--
-- 2. The R-part must be a real, active part. Stores cannot invent stock by
--    ticking Refurb: if R<code> is not in Part Master, or is inactive, the
--    dispatch is refused and names the code that is missing.
-- ===========================================================================

create or replace view public.handstock_movements as
-- 1. Stock out from Stores (+) — from the ISSUE, so what the engineer holds is
--    the part that actually arrived. A refurbished spare is issued under its own
--    R-prefixed code and therefore appears as its own stock line.
select
  'IN'::text                                        as direction,
  'Stock out'::text                                 as movement,
  public.handstock_key(r.engineer)                  as engineer_key,
  coalesce(r.engineer, '')                          as engineer,
  coalesce(r.engineer_email, '')                    as engineer_email,
  public.part_code(dl.part)                         as part_code,
  coalesce(dl.part, '')                             as part,
  coalesce(dl.qty, 0)                               as qty,
  coalesce(d.dispatched_at, dl.created_at)          as moved_at,
  coalesce(nullif(d.dc_number, ''), r.or_no, '')    as ref,
  'Stores DC'::text                                 as ref_type,
  coalesce(r.uid, '')                               as ref_uid,
  coalesce(r.ucn, '')                               as ucn,
  coalesce(r.call_number, '')                       as call_number,
  coalesce(r.party_name, '')                        as party_name,
  coalesce(nullif(l.dispatch_remarks, ''), '')      as remarks
from public.spare_dispatch_lines dl
join public.spare_dispatches    d on d.uid = dl.dispatch_uid
join public.spare_request_lines l on l.id  = dl.line_id
join public.spare_requests      r on r.uid = l.request_uid
union all
-- 1b. Legacy safety net: a line marked Dispatched that has no issue rows (an
--     import, or a write that bypassed dispatch_spare_lines). Without this the
--     ledger would silently lose that stock.
select
  'IN'::text, 'Stock out'::text,
  public.handstock_key(r.engineer), coalesce(r.engineer, ''), coalesce(r.engineer_email, ''),
  public.part_code(l.part), coalesce(l.part, ''),
  case when coalesce(l.dispatched_qty, 0) > 0 then l.dispatched_qty else coalesce(l.qty, 0) end,
  coalesce(l.dispatched_at, r.dispatched_at, l.created_at, r.created_at),
  coalesce(nullif(l.dc_number, ''), r.or_no, ''),
  'Stores DC'::text, coalesce(r.uid, ''), coalesce(r.ucn, ''), coalesce(r.call_number, ''),
  coalesce(r.party_name, ''), coalesce(nullif(l.dispatch_remarks, ''), '')
from public.spare_request_lines l
join public.spare_requests r on r.uid = l.request_uid
where (coalesce(l.dispatched_qty, 0) > 0 or coalesce(l.stores_status, '') ~* 'dispatch')
  and not exists (select 1 from public.spare_dispatch_lines dl where dl.line_id = l.id)
union all
-- 2. Consumption on a call (−)
select
  'OUT'::text, 'Consumption'::text,
  public.handstock_key(c.engineer),
  coalesce(c.engineer, ''),
  coalesce(c.engineer_email, ''),
  public.part_code(c.part),
  coalesce(c.part, ''),
  coalesce(c.qty, 0),
  c.created_at,
  coalesce(nullif(btrim(c.call_number), ''), coalesce(c.ucn, '')),
  'Call'::text,
  ''::text,
  coalesce(c.ucn, ''),
  coalesce(c.call_number, ''),
  ''::text,
  ''::text
from public.spare_consumption c
union all
-- 3. Stock transfer FROM this engineer (−)
select
  'OUT'::text, 'Transfer out'::text,
  public.handstock_key(t.from_engineer),
  coalesce(t.from_engineer, ''),
  ''::text,
  public.part_code(l.part),
  coalesce(l.part, ''),
  coalesce(l.qty, 0),
  coalesce(t.transfer_date::timestamptz, t.created_at),
  coalesce(t.uid, ''),
  'Transfer'::text,
  ''::text,
  ''::text,
  ''::text,
  coalesce(t.to_engineer, ''),                      -- who it went to
  coalesce(t.remarks, '')
from public.stock_transfer_lines l
join public.stock_transfers t on t.uid = l.transfer_uid
union all
-- 4. Stock transfer TO this engineer (+)
select
  'IN'::text, 'Transfer in'::text,
  public.handstock_key(t.to_engineer),
  coalesce(t.to_engineer, ''),
  ''::text,
  public.part_code(l.part),
  coalesce(l.part, ''),
  coalesce(l.qty, 0),
  coalesce(t.transfer_date::timestamptz, t.created_at),
  coalesce(t.uid, ''),
  'Transfer'::text,
  ''::text,
  ''::text,
  ''::text,
  coalesce(t.from_engineer, ''),                    -- who it came from
  coalesce(t.remarks, '')
from public.stock_transfer_lines l
join public.stock_transfers t on t.uid = l.transfer_uid
union all
-- 5. Returned to Stores on an MRN (−)
select
  'OUT'::text, 'Return'::text,
  public.handstock_key(m.engineer),
  coalesce(m.engineer, ''),
  coalesce(m.engineer_email, ''),
  public.part_code(m.part),
  coalesce(m.part, ''),
  coalesce(m.good_qty, 0) + coalesce(m.defective_qty, 0),
  coalesce(m.mrn_date::timestamptz, m.returned_at, m.created_at),
  coalesce(nullif(btrim(m.mrn_no), ''), m.uid, ''),
  'MRN'::text,
  coalesce(m.uid, ''),
  ''::text,
  coalesce(m.report_no, ''),
  coalesce(m.customer_name, ''),
  btrim(
    case when coalesce(m.defective_qty, 0) > 0
         then 'good ' || coalesce(m.good_qty, 0) || ', defective ' || m.defective_qty || ' · ' else '' end
    || coalesce(m.remarks, '')
  )
from public.material_returns m;

alter view public.handstock_movements set (security_invoker = on);
grant select on public.handstock_movements to authenticated;

-- ---- the R-part must exist and be active ----------------------------------
create or replace function public.refurb_part_ok(p_part text)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.parts p
     where upper(btrim(p.code)) = public.part_code(p_part)
       and coalesce(p.active, true)
  );
$$;
grant execute on function public.refurb_part_ok(text) to authenticated;

-- ---- dispatch refuses an unknown or inactive refurbished part -------------
create or replace function public.dispatch_spare_lines(
  p_line_ids bigint[],
  p_qtys     numeric[],
  p_refurb   boolean[],
  p_courier  text default '',
  p_remarks  text default '',
  p_dc_date  date default current_date,
  p_actor    text default ''
) returns public.spare_dispatches
language plpgsql security definer set search_path = public as $$
declare
  eng text; n integer; head public.spare_dispatches; email text;
  i integer; lid bigint; want numeric; rem numeric; send numeric; ref boolean;
  total numeric := 0; cnt integer := 0;
begin
  if not (public.is_admin() or public.has_perm('spare.dispatch')) then
    raise exception 'RBAC: dispatch requires the spare.dispatch permission';
  end if;
  if p_line_ids is null or array_length(p_line_ids, 1) is null then
    raise exception 'Nothing to dispatch: no spares selected';
  end if;

  select count(*), min(v.engineer), min(v.engineer_email) into n, eng, email
    from public.spare_pending_dispatch v where v.line_id = any (p_line_ids);
  if coalesce(n, 0) <> array_length(p_line_ids, 1) then
    raise exception
      'Only % of the % selected spares are still waiting at Stores — refresh and try again',
      coalesce(n, 0), array_length(p_line_ids, 1);
  end if;
  if (select count(distinct v.engineer_key) from public.spare_pending_dispatch v
       where v.line_id = any (p_line_ids)) <> 1 then
    raise exception 'A stock out goes to one engineer — select spares for a single engineer';
  end if;

  insert into public.spare_dispatches
    (dc_date, engineer, engineer_email, courier, remarks, line_count, total_qty, dispatched_by)
  values
    (coalesce(p_dc_date, current_date), eng, coalesce(email, ''), coalesce(p_courier, ''),
     coalesce(p_remarks, ''), 0, 0, coalesce(nullif(btrim(p_actor), ''), ''))
  returning * into head;

  for i in 1 .. array_length(p_line_ids, 1) loop
    lid  := p_line_ids[i];
    want := case when p_qtys   is null then null  else p_qtys[i]   end;
    ref  := case when p_refurb is null then false else coalesce(p_refurb[i], false) end;

    select greatest(coalesce(l.qty, 0) - coalesce(l.dispatched_qty, 0), 0)
      into rem from public.spare_request_lines l where l.id = lid;

    send := coalesce(want, rem);
    if send is null or send <= 0 then
      raise exception 'Quantity for spare % must be more than zero', lid;
    end if;
    if send > rem then
      raise exception 'Only % left to send on that spare (you asked for %) — refresh and try again', rem, send;
    end if;

    -- A refurbished issue may only use a part that Part Master actually knows
    -- and still lists as active — otherwise ticking Refurb would invent a part
    -- number, and with it a stock line nobody can order against.
    if ref then
      declare rp text;
      begin
        select public.refurb_part(l.part) into rp from public.spare_request_lines l where l.id = lid;
        if not public.refurb_part_ok(rp) then
          raise exception 'Refurbished part % is not in Part Master, or is not active — add it before issuing it',
            public.part_code(rp);
        end if;
      end;
    end if;

    insert into public.spare_dispatch_lines (dispatch_uid, line_id, line_uid, part, qty, refurbished)
    select head.uid, l.id, coalesce(l.line_uid, ''),
           case when ref then public.refurb_part(l.part) else coalesce(l.part, '') end,
           send, ref
      from public.spare_request_lines l where l.id = lid;

    update public.spare_request_lines l
       set dispatched_qty   = coalesce(l.dispatched_qty, 0) + send,
           courier          = coalesce(p_courier, ''),
           dispatch_remarks = coalesce(p_remarks, ''),
           dispatched_by    = head.dispatched_by,
           dispatched_at    = head.dispatched_at,
           dc_number    = case when coalesce(l.dispatched_qty, 0) + send >= coalesce(l.qty, 0)
                               then head.dc_number else l.dc_number end,
           dispatch_uid = case when coalesce(l.dispatched_qty, 0) + send >= coalesce(l.qty, 0)
                               then head.uid else l.dispatch_uid end,
           stock_out_no = case when coalesce(l.dispatched_qty, 0) + send >= coalesce(l.qty, 0)
                               then head.uid else l.stock_out_no end,
           stores_status = case when coalesce(l.dispatched_qty, 0) + send >= coalesce(l.qty, 0)
                                then 'Dispatched' else l.stores_status end
     where l.id = lid;

    total := total + send; cnt := cnt + 1;
  end loop;

  update public.spare_dispatches d set line_count = cnt, total_qty = total
   where d.uid = head.uid returning * into head;
  return head;
end $$;
grant execute on function public.dispatch_spare_lines(bigint[], numeric[], boolean[], text, text, date, text) to authenticated;

-- ------------------------------------------------------------------------
-- 0074_handstock_opening.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- OPENING STOCK — the hand stock that pre-dates the movement history.
--
-- Hand stock is DERIVED: stock out - consumption - transfers + returns. That is
-- right for every spare the system issued. It is wrong for everything an
-- engineer was already carrying before the system had the movements: raw spare
-- data starts JUNE 2022, and the stock held before that (WinMax HS), plus the
-- per-period figures alongside it (22 H2, 23, 24, 25), exist only as balances.
--
-- Without them the derivation says those engineers hold ZERO — and because
-- consumption is CAPPED at hand stock (0061), an engineer cannot report fitting
-- a part they are genuinely holding. The cap turns a reporting gap into a
-- blocked job.
--
-- Each row here is an OPENING INJECTION, not a restatement: the pools sit
-- ALONGSIDE one another and alongside the movement history, which is how they
-- were kept. They are additive precisely because the raw movements do not cover
-- them — nothing is counted twice, because there is nothing before June 2022 to
-- count. `as_of` records when the pool was struck and `source` which pool it is.
--
-- Added as an ARM of `handstock_movements` rather than as a term of its own, so
-- every consumer inherits it without being touched: the balance, the movement
-- trail an engineer reads, `engineer_stock`, the transfer guard, and the
-- consumption cap. A separate term would have had to be added to each, and the
-- ones that were missed would silently disagree.
-- ===========================================================================

create table if not exists public.handstock_opening (
  id             bigint generated always as identity primary key,
  engineer       text not null,
  engineer_key   text generated always as (public.handstock_key(engineer)) stored,
  part           text not null,                       -- CODE|Description
  part_code      text generated always as (public.part_code(part)) stored,
  qty            numeric not null check (qty >= 0),
  as_of          date not null,
  source         text not null,                       -- 'WinMax HS', '22 H2', '23', ...
  -- Stored so the unique index below is on PLAIN COLUMNS. An expression index
  -- (lower(btrim(source))) cannot be inferred by `on conflict`, so the upload's
  -- upsert would be refused outright — the same trap the partial reports_uid
  -- index sprang in 0071. `source` keeps what was typed, for display.
  source_key     text generated always as (lower(btrim(source))) stored,
  remarks        text not null default '',
  recorded_by      uuid references auth.users (id),
  recorded_by_name text not null default '',
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);

-- One figure per engineer + part + pool, so re-loading a corrected sheet
-- REPLACES that pool's figure instead of adding a second one. Getting this
-- wrong is how an opening balance silently doubles.
create unique index if not exists handstock_opening_uniq
  on public.handstock_opening (engineer_key, part_code, source_key);
create index if not exists handstock_opening_eng_idx on public.handstock_opening (engineer_key);

create or replace function public.handstock_opening_biu()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if btrim(coalesce(new.engineer, '')) = '' then raise exception 'An opening balance needs the engineer.'; end if;
  if btrim(coalesce(new.part, ''))     = '' then raise exception 'An opening balance needs the part.'; end if;
  if btrim(coalesce(new.source, ''))   = '' then raise exception 'An opening balance needs its source (which pool it is).'; end if;
  if tg_op = 'INSERT' then new.recorded_by := coalesce(new.recorded_by, auth.uid());
  else new.recorded_by := old.recorded_by; new.created_at := old.created_at; end if;
  new.updated_at := now();
  return new;
end $$;
drop trigger if exists handstock_opening_biu on public.handstock_opening;
create trigger handstock_opening_biu before insert or update on public.handstock_opening
  for each row execute function public.handstock_opening_biu();

alter table public.handstock_opening enable row level security;
grant select, insert, update, delete on public.handstock_opening to authenticated;

-- Read: the same scope the rest of hand stock uses — an engineer sees their own
-- and their tree's; the office roles see all.
drop policy if exists hso_read on public.handstock_opening;
-- A set-returning function cannot appear in a policy expression, so the
-- visible-engineer list is joined as a subquery — the same shape mr_read (0039)
-- uses, and the reason it is written that way there too.
create policy hso_read on public.handstock_opening for select
  using (
    (select public.can_view_all_calls())
    or (select public.has_perm('data.view_all'))
    or lower(btrim(engineer)) in (select lower(btrim(n)) from public.visible_engineer_names() as v(n))
  );

-- Write: the Spare Coordinator's job, as with every other hand-stock
-- correction — the control point stays with them, not the engineer.
drop policy if exists hso_write on public.handstock_opening;
create policy hso_write on public.handstock_opening for all
  using (public.has_perm('consumption.reconcile') or public.has_perm('spare.dispatch'))
  with check (public.has_perm('consumption.reconcile') or public.has_perm('spare.dispatch'));

-- ---------------------------------------------------------------------------
-- The new arm. Appended to the UNION, so the balance, the movement trail,
-- engineer_stock, the transfer guard and the consumption cap all pick it up.
-- ---------------------------------------------------------------------------
do $hm$
declare v_def text;
begin
  if to_regclass('public.handstock_movements') is null then
    raise notice 'handstock_movements is not present — run the HandStock bundle first';
    return;
  end if;
  -- Already added? (This file is idempotent and the bundles are re-run.)
  if exists (select 1 from pg_views where schemaname = 'public' and viewname = 'handstock_movements'
              and definition ilike '%handstock_opening%') then
    return;
  end if;
  v_def := pg_get_viewdef('public.handstock_movements'::regclass, true);
  -- Strip the trailing semicolon pg_get_viewdef adds.
  v_def := regexp_replace(v_def, ';\s*$', '');
  execute 'create or replace view public.handstock_movements as ' || v_def || $arm$
UNION ALL
 SELECT 'IN'::text AS direction,
    'Opening'::text AS movement,
    o.engineer_key,
    COALESCE(o.engineer, ''::text) AS engineer,
    ''::text AS engineer_email,
    o.part_code,
    COALESCE(o.part, ''::text) AS part,
    COALESCE(o.qty, 0::numeric) AS qty,
    o.as_of::timestamptz AS moved_at,
    COALESCE(o.source, ''::text) AS ref,
    'Opening balance'::text AS ref_type,
    ''::text AS ref_uid,
    ''::text AS ucn,
    ''::text AS call_number,
    ''::text AS party_name,
    COALESCE(o.remarks, ''::text) AS remarks
   FROM public.handstock_opening o
$arm$;
end $hm$;

alter view public.handstock_movements set (security_invoker = on);
grant select on public.handstock_movements to authenticated;

-- Show the opening separately on the balance, so a figure that comes from a
-- pool rather than from a dispatch is legible rather than merely correct.
-- APPENDED at the end: `create or replace view` cannot insert a column.
do $hb$
begin
  if to_regclass('public.handstock_balance') is null then return; end if;
  if exists (select 1 from information_schema.columns
              where table_schema='public' and table_name='handstock_balance' and column_name='opening') then
    return;
  end if;
  execute $v$
    create or replace view public.handstock_balance as
    select engineer_key,
           max(engineer) as engineer,
           max(engineer_email) as engineer_email,
           part_code,
           coalesce(max(part) filter (where movement = 'Stock out'), max(part)) as part,
           sum(case when movement = 'Stock out'    then qty else 0 end) as stock_out,
           sum(case when movement = 'Consumption'  then qty else 0 end) as consumed,
           sum(case when movement = 'Transfer in'  then qty else 0 end) as transferred_in,
           sum(case when movement = 'Transfer out' then qty else 0 end) as transferred_out,
           sum(case when movement = 'Return'       then qty else 0 end) as returned,
           sum(case when direction = 'IN' then qty else -qty end) as on_hand,
           max(moved_at) filter (where direction = 'IN')  as last_in,
           max(moved_at) filter (where direction = 'OUT') as last_out,
           max(moved_at) as last_movement,
           count(*) as movements,
           sum(case when movement = 'Opening' then qty else 0 end) as opening
      from public.handstock_movements m
     where engineer_key <> '' and part_code <> ''
     group by engineer_key, part_code
  $v$;
end $hb$;

alter view public.handstock_balance set (security_invoker = on);
grant select on public.handstock_balance to authenticated;

-- ------------------------------------------------------------------------
-- 0075_spare_history.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- HISTORICAL SPARE MOVEMENT — the record before the system held it.
--
-- ~44,000 consumption rows pre-date this system. Loading them into
-- `spare_consumption` would be wrong twice over:
--
--   * the CAP (0061) checks every inserted line against the engineer's hand
--     stock. Applied retrospectively it would REFUSE most of the history —
--     silently deleting real consumption to satisfy a rule that did not exist
--     when it happened.
--   * the cap runs a derivation per row. Over 44,000 rows that is an aggregate
--     over the whole movement history, forty-four thousand times.
--
-- So history lives in its OWN table, with no cap and no reconciliation, and is
-- CONSOLIDATED into hand stock as another arm — exactly as the opening pools
-- are (0074). Reconciliation stays where it belongs: on the 2026 entries in
-- `spare_consumption`, which is where the control point is meant to be.
--
-- `source` says which body of data a row came from, so a historical figure can
-- always be traced back to the sheet it was recovered from.
-- ===========================================================================

create table if not exists public.spare_consumption_history (
  id             bigint generated always as identity primary key,
  engineer       text not null,
  engineer_key   text generated always as (public.handstock_key(engineer)) stored,
  part           text not null,                       -- CODE|Description
  part_code      text generated always as (public.part_code(part)) stored,
  qty            numeric not null check (qty >= 0),
  consumed_at    timestamptz,
  ucn            text not null default '',
  call_number    text not null default '',
  party_name     text not null default '',
  source         text not null,                       -- which body of data this came from
  -- Stored, so the unique index below is on PLAIN COLUMNS: an expression index
  -- cannot be inferred by `on conflict`, and the upload upserts on it.
  source_key     text generated always as (lower(btrim(source))) stored,
  ref            text not null default '',            -- its id in that source
  remarks        text not null default '',
  data           jsonb not null default '{}',
  recorded_by      uuid references auth.users (id),
  recorded_by_name text not null default '',
  created_at     timestamptz not null default now()
);

-- The source's own reference is what makes a re-load correct rather than
-- duplicate. Where a row has none it is still loadable — it just cannot be
-- matched on a second run, which the upload screen says out loud.
-- Partial, because a row with no reference in its source cannot be matched on
-- a re-run and must not be forced to collide with the others. The upload says
-- so out loud rather than quietly duplicating.
create unique index if not exists spare_consumption_history_ref_uniq
  on public.spare_consumption_history (source_key, ref)
  where ref <> '';

create index if not exists spare_consumption_history_eng_idx  on public.spare_consumption_history (engineer_key);
create index if not exists spare_consumption_history_part_idx on public.spare_consumption_history (part_code);
create index if not exists spare_consumption_history_ucn_idx  on public.spare_consumption_history (ucn) where ucn <> '';

create or replace function public.spare_consumption_history_biu()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if btrim(coalesce(new.engineer, '')) = '' then raise exception 'A historical consumption row needs the engineer.'; end if;
  if btrim(coalesce(new.part, ''))     = '' then raise exception 'A historical consumption row needs the part.'; end if;
  if btrim(coalesce(new.source, ''))   = '' then raise exception 'A historical consumption row needs its source (which body of data it came from).'; end if;
  if tg_op = 'INSERT' then new.recorded_by := coalesce(new.recorded_by, auth.uid());
  else new.recorded_by := old.recorded_by; new.created_at := old.created_at; end if;
  return new;
end $$;
drop trigger if exists spare_consumption_history_biu on public.spare_consumption_history;
create trigger spare_consumption_history_biu before insert or update on public.spare_consumption_history
  for each row execute function public.spare_consumption_history_biu();

-- NOTE: deliberately NO cap trigger and NO reconciliation. This table is the
-- record of what happened, not a control point. 0049's retention guard does not
-- cover it either — it is loadable and correctable until the history is settled.

alter table public.spare_consumption_history enable row level security;
grant select, insert, update, delete on public.spare_consumption_history to authenticated;

drop policy if exists sch_read on public.spare_consumption_history;
create policy sch_read on public.spare_consumption_history for select
  using (
    (select public.can_view_all_calls())
    or (select public.has_perm('data.view_all'))
    or lower(btrim(engineer)) in (select lower(btrim(n)) from public.visible_engineer_names() as v(n))
  );

drop policy if exists sch_write on public.spare_consumption_history;
create policy sch_write on public.spare_consumption_history for all
  using (public.has_perm('consumption.reconcile') or public.has_perm('spare.dispatch'))
  with check (public.has_perm('consumption.reconcile') or public.has_perm('spare.dispatch'));

-- ---------------------------------------------------------------------------
-- Consolidate it into hand stock — another arm, so the balance, the movement
-- trail, engineer_stock, the transfer guard and the 2026 cap all see it without
-- being touched.
-- ---------------------------------------------------------------------------
do $hm$
declare v_def text;
begin
  if to_regclass('public.handstock_movements') is null then
    raise notice 'handstock_movements is not present — run the HandStock bundle first';
    return;
  end if;
  if exists (select 1 from pg_views where schemaname = 'public' and viewname = 'handstock_movements'
              and definition ilike '%spare_consumption_history%') then
    return;
  end if;
  v_def := regexp_replace(pg_get_viewdef('public.handstock_movements'::regclass, true), ';\s*$', '');
  execute 'create or replace view public.handstock_movements as ' || v_def || $arm$
UNION ALL
 SELECT 'OUT'::text AS direction,
    'Consumption'::text AS movement,
    h.engineer_key,
    COALESCE(h.engineer, ''::text) AS engineer,
    ''::text AS engineer_email,
    h.part_code,
    COALESCE(h.part, ''::text) AS part,
    COALESCE(h.qty, 0::numeric) AS qty,
    COALESCE(h.consumed_at, h.created_at) AS moved_at,
    COALESCE(NULLIF(h.ref, ''::text), h.source, ''::text) AS ref,
    'Historical'::text AS ref_type,
    ''::text AS ref_uid,
    COALESCE(h.ucn, ''::text) AS ucn,
    COALESCE(h.call_number, ''::text) AS call_number,
    COALESCE(h.party_name, ''::text) AS party_name,
    COALESCE(h.remarks, ''::text) AS remarks
   FROM public.spare_consumption_history h
$arm$;
end $hm$;

alter view public.handstock_movements set (security_invoker = on);
grant select on public.handstock_movements to authenticated;

-- ------------------------------------------------------------------------
-- 0078_consumption_grir.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- GRIR / TRACEABILITY on a consumed spare.
--
-- Which part was fitted is recorded; WHICH ONE is not. On a medical device that
-- is the difference between "an oxygen sensor was replaced" and being able to
-- answer, when a batch is recalled or a failure repeats, exactly which sensor
-- went into which machine. The engineers already capture it in the field — the
-- consumption export carries it on all 8,339 real rows — so it has had nowhere
-- to land.
--
-- Also gives the table a natural key at last. `spare_consumption` had none, so
-- re-running an import ADDED every row again; on 8,339 rows that is a hand-stock
-- figure quietly halved. `source_ref` is the export's own id, and the index is
-- partial because a line entered in the app has no such id and must not be
-- forced to collide with the others.
-- ===========================================================================

alter table public.spare_consumption add column if not exists grir       text not null default '';
alter table public.spare_consumption add column if not exists source_ref text not null default '';

comment on column public.spare_consumption.grir is
  'GRIR / traceability reference for the part actually fitted — batch, goods-receipt or serial. Recorded by the engineer at consumption.';
comment on column public.spare_consumption.source_ref is
  'The row id this line came from when it was imported. Lets a re-load correct rather than duplicate.';

create unique index if not exists spare_consumption_source_ref_uniq
  on public.spare_consumption (source_ref) where source_ref <> '';
create index if not exists spare_consumption_grir_idx
  on public.spare_consumption (grir) where grir <> '';

-- ------------------------------------------------------------------------
-- 0081_part_product_keys_inferable.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Make 0079's keys actually usable by `on conflict`.
--
-- 0079 built them PARTIAL — `where code_key <> ''` and `where machine_key <>
-- '|'` — and Postgres cannot infer a partial index from `on conflict (col)`.
-- So the index existed, `_status.sql` read yes, and the upload still failed
-- with "there is no unique or exclusion constraint matching the ON CONFLICT
-- specification". Exactly the trap 0071, 0074, 0076 and 0077 each hit; I wrote
-- it into the migration that was meant to be the fix.
--
-- Full indexes instead. The predicate was excluding the keyless row, which does
-- not need excluding: a part with no code, or a machine with neither model nor
-- serial, is not a record — at most one such row can exist, which is the right
-- answer rather than a limitation.
--
-- `scripts/check-upsert-targets.mjs` now checks every register's conflict target
-- against a real database, so this class cannot ship again by inspection alone.
--
-- LIVES IN THE handstock MODULE. It fixes indexes on parts and products (created
-- in masters, an EARLIER module — fine) and on spare_consumption.source_ref,
-- which 0078 adds HERE. From masters it ran before that column existed and
-- all.sql died on it. 0082 follows it in the same module, since it drops an
-- index this file creates and must not run first.
-- ===========================================================================

drop index if exists public.parts_code_key_uniq;
do $$
begin
  if exists (select 1 from public.parts group by code_key having count(*) > 1) then
    raise notice 'parts holds duplicate codes — de-duplicate, then re-run this file to build parts_code_key_uniq.';
  else
    create unique index if not exists parts_code_key_uniq on public.parts (code_key);
  end if;
end $$;

drop index if exists public.products_machine_key_uniq;
do $$
begin
  if exists (select 1 from public.products group by machine_key having count(*) > 1) then
    raise notice 'products holds duplicate model+serial — de-duplicate, then re-run this file to build products_machine_key_uniq.';
  else
    create unique index if not exists products_machine_key_uniq on public.products (machine_key);
  end if;
end $$;

-- ---------------------------------------------------------------------------
-- spare_consumption, found by that same check.
--
-- 0078 indexed `source_ref` PARTIALLY (`where source_ref <> ''`) because a line
-- entered in the app has no source reference and many blanks cannot share a
-- unique index. The predicate was necessary, and it made the index
-- un-inferable, so the Consumption upload would have failed exactly as Part
-- Master did.
--
-- A NULLABLE key solves both at once: NULLs are DISTINCT in a unique index, so
-- every app-entered line coexists happily while imported lines are still unique
-- on their source reference — and the index is full, so `on conflict` can infer
-- it.
-- ---------------------------------------------------------------------------
alter table public.spare_consumption
  add column if not exists source_ref_key text generated always as (nullif(btrim(source_ref), '')) stored;

drop index if exists public.spare_consumption_source_ref_uniq;
do $$
begin
  if exists (select 1 from public.spare_consumption
              where nullif(btrim(source_ref), '') is not null
              group by nullif(btrim(source_ref), '') having count(*) > 1) then
    raise notice 'spare_consumption holds duplicate source references — de-duplicate, then re-run this file.';
  else
    create unique index if not exists spare_consumption_source_ref_uniq
      on public.spare_consumption (source_ref_key);
  end if;
end $$;

-- ---------------------------------------------------------------------------
-- The adjustment guard must not block a RE-IMPORT.
--
-- 0062 insists a quantity change carries a reason, so a reconciler cannot
-- silently restate a line. That is right, and it stays right — for a person
-- correcting a line in the app.
--
-- It is wrong for a bulk re-load. Re-importing a corrected consumption sheet is
-- the SOURCE SYSTEM restating itself, not somebody adjusting a figure; demanding
-- a typed reason per row across 8,335 lines is not a control, it is a wall that
-- simply stops the load. And a re-load that cannot correct is the whole point of
-- giving the table a key in the first place.
--
-- So the exemption is exactly one case and no wider: a line that CAME FROM an
-- import (source_ref present) and is still the same import (source_ref
-- unchanged). A line entered in the app has no source_ref and is untouched by
-- this — the reconciler still has to say why. The before/after is recorded by
-- the audit trail (0048) either way, so nothing becomes unaccountable.
-- ---------------------------------------------------------------------------
create or replace function public.consumption_adjust_guard()
returns trigger language plpgsql security definer set search_path = public as $$
declare avail numeric; delta numeric;
begin
  if coalesce(new.ucn, '')      is distinct from coalesce(old.ucn, '')
  or coalesce(new.part, '')     is distinct from coalesce(old.part, '')
  or coalesce(new.engineer, '') is distinct from coalesce(old.engineer, '')
  or coalesce(new.source, '')   is distinct from coalesce(old.source, '') then
    raise exception 'A reconciliation can only change the quantity — not the call, part, engineer or source';
  end if;

  if new.qty is not distinct from old.qty then
    return new;                        -- nothing quantitative changed
  end if;
  if coalesce(new.qty, 0) < 0 then
    raise exception 'Quantity cannot be negative';
  end if;

  -- The one exemption: the same imported line, re-loaded from its source.
  if coalesce(btrim(new.source_ref), '') <> ''
     and btrim(new.source_ref) is not distinct from btrim(old.source_ref) then
    return new;
  end if;

  if coalesce(new.qty, 0) <= 0 and coalesce(btrim(new.adjustment_reason), '') = '' then
    raise exception 'Say why the line is being voided — the reason is kept with it';
  end if;
  if coalesce(btrim(new.adjustment_reason), '') = '' then
    raise exception 'Say why the quantity is being adjusted — the reason is kept with the line';
  end if;

  -- A RAISE still has to fit in the engineer's hand stock; a reduction never does.
  delta := coalesce(new.qty, 0) - coalesce(old.qty, 0);
  if delta > 0 then
    select coalesce(b.on_hand, 0) into avail
      from public.handstock_balance b
     where b.engineer_key = public.handstock_key(new.engineer)
       and b.part_code = public.part_code(new.part);
    if coalesce(avail, 0) < delta then
      raise exception '% has % of % in hand, so the line cannot be raised by %. Ask the Spare Coordinator to correct the hand stock first.',
        new.engineer, coalesce(avail, 0), public.part_code(new.part), delta;
    end if;
  end if;

  if old.original_qty is null then new.original_qty := old.qty; end if;
  new.adjusted_at := now();
  return new;
end $$;

-- ------------------------------------------------------------------------
-- 0082_part_key_is_item_detail.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- A part is its ITEM DETAIL, not its code.
--
-- 0079/0081 keyed Part Master on the code. The real 1,324-row ITEM Master says
-- otherwise: YR134500 is used for TWO different parts —
--
--     YR134500|LOUDSPEAKER V2-MT50
--     YR134500|SPEAKER V2-MT75
--
-- — so keying on the code would have merged them and lost one, and the unique
-- index on the code would have REFUSED the load outright. `Item Details` is
-- distinct across all 1,324.
--
-- It is also the right key on its own merits: `CODE|Description` is how a part
-- is referenced everywhere else — on a consumption line, in hand stock, in the
-- engineer's picker — so the register now keys on the same thing the rest of
-- the system does.
--
-- The code keeps an index for lookups; it just is not unique, because it isn't.
-- ===========================================================================

alter table public.parts
  add column if not exists item_detail_key text generated always as (lower(btrim(item_detail))) stored;

-- The code is NOT unique in the real register — drop the constraint that says
-- it is, or the ITEM Master cannot be loaded at all.
drop index if exists public.parts_code_key_uniq;

do $$
begin
  if exists (select 1 from public.parts group by item_detail_key having count(*) > 1) then
    raise notice 'parts holds duplicate item details — de-duplicate, then re-run this file to build parts_item_detail_key_uniq.';
  else
    create unique index if not exists parts_item_detail_key_uniq on public.parts (item_detail_key);
  end if;
end $$;

create index if not exists parts_item_detail_key_idx on public.parts (item_detail_key);

-- ------------------------------------------------------------------------
-- 0089_spare_imports_load.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- What the historical spare files hit, found by loading them end to end against
-- a copy of the live database rather than one screen at a time.
--
-- 1. `material_returns.extra` DOES NOT EXIST. The MRN register has always
--    mapped its leftover columns into it, so that upload could never have
--    written a row — the preview said "595 ready" right up to the failure.
--    `npm run check:columns` now resolves every register's columns against a
--    real database, which is the only place that fact lives.
--
-- 2. `stock_transfers.created_by` had NO DEFAULT, while every sibling table
--    defaults it to auth.uid(). `stl_insert` requires the parent transfer to be
--    yours (or you an admin), so with a NULL creator a non-admin could not add
--    lines to a transfer they had just made — in the app as much as in an
--    import. addStockTransfer() then deletes the header and reports the
--    row-level error. Defaulted, as 0009 did for spare_requests.
--
-- 3. The CAP and the transfer STOCK CHECK are controls on entry: an engineer
--    may not report using — or hand on — more than they hold. An import is not
--    entry. It is the record of what already happened, and it is the input the
--    reconciliation is computed FROM; refusing it because our derived stock is
--    still partial (the opening pools and the pre-2026 issues are separate
--    files) is the tail wagging the dog. 0075 already accepted this for the
--    pre-2026 history, which is uncapped by design.
--
--    So a row that carries an IMPORT PROVENANCE is exempt from the shortfall
--    check, and only from that:
--      • consumption — `source_ref`, which only the importer writes;
--      • transfers — the parent's `source = 'import'`, stamped by the register,
--        the same marker 0039 already reads on a material return (which the
--        MRN register simply never stamped, so every historical return was
--        refused for a shortfall).
--    Everything else still holds: quantity above zero, a reconciliation still
--    needs its UCN, engineer, part and reason. A hand-entered line is capped
--    exactly as before, and a negative balance an import reveals is what the
--    Spare Coordinator's reconciliation is for.
-- ===========================================================================

alter table public.material_returns add column if not exists extra jsonb not null default '{}'::jsonb;
comment on column public.material_returns.extra is
  'Everything the source export carried that has no field of its own, kept as written.';

alter table public.stock_transfers alter column created_by set default auth.uid();
alter table public.stock_transfers add column if not exists source text not null default '';
comment on column public.stock_transfers.source is
  'import for a transfer loaded from the sheet era, as material_returns.source already means; empty for one made here.';

-- ---------------------------------------------------------------------------
-- The cap, with the import exemption. Everything else is 0061 unchanged.
-- ---------------------------------------------------------------------------
create or replace function public.consumption_reconcile_guard()
returns trigger language plpgsql security definer set search_path = public as $$
declare avail numeric; is_recon boolean;
begin
  is_recon := coalesce(new.source, 'Report') = 'Reconciliation';

  if coalesce(new.qty, 0) <= 0 then
    raise exception 'Quantity must be more than zero';
  end if;

  -- Everything is required on a hand-booked line: whose stock it came off,
  -- what was used, and why. A stock adjustment with no stated reason is not
  -- auditable, which is the point of flagging these separately.
  if is_recon then
    if coalesce(btrim(new.ucn), '') = '' then
      raise exception 'A reconciliation needs the UCN of the call the spare was used on';
    end if;
    if not exists (select 1 from public.calls c where c.ucn = btrim(new.ucn)) then
      raise exception 'No call found with UCN % — check the number', btrim(new.ucn);
    end if;
    if coalesce(btrim(new.engineer), '') = '' then
      raise exception 'A reconciliation needs the engineer whose hand stock the spare came off';
    end if;
    if coalesce(btrim(new.part), '') = '' then
      raise exception 'A reconciliation needs the part';
    end if;
    if coalesce(btrim(new.remarks), '') = '' then
      raise exception 'A reconciliation needs a reason (why the spare is being booked by hand)';
    end if;
  end if;

  -- An imported line is a record, not a request: it says what was used, and the
  -- issues that covered it may be in a file that is not loaded yet.
  if coalesce(btrim(new.source_ref), '') <> '' then
    return new;
  end if;

  -- THE CAP — every line, however it was written. Skipped only when the row
  -- names no engineer or no part, where there is no balance to check.
  if coalesce(btrim(new.engineer), '') = '' or coalesce(btrim(new.part), '') = '' then
    return new;
  end if;

  select coalesce(b.on_hand, 0) into avail
    from public.handstock_balance b
   where b.engineer_key = public.handstock_key(new.engineer)
     and b.part_code    = public.part_code(new.part);

  if coalesce(avail, 0) < new.qty then
    if is_recon then
      raise exception '% has % of % in hand — cannot book % against this call',
        btrim(new.engineer), coalesce(avail, 0), public.part_code(new.part), new.qty;
    else
      raise exception
        '% has % of % in hand, so % cannot be consumed. Ask the Spare Coordinator to correct the hand stock first.',
        btrim(new.engineer), coalesce(avail, 0), public.part_code(new.part), new.qty;
    end if;
  end if;
  return new;
end $$;

-- ---------------------------------------------------------------------------
-- The transfer stock check, with the same exemption. 0020 otherwise unchanged.
-- ---------------------------------------------------------------------------
create or replace function public.stock_transfer_lines_check_stock()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  sender text;
  src    text;
  bal    numeric;
begin
  select from_engineer, coalesce(source, '') into sender, src
    from public.stock_transfers where uid = new.transfer_uid;
  if src = 'import' then
    return null;                    -- a transfer that already happened
  end if;
  bal := public.engineer_stock_available(sender, new.part);
  if bal < 0 then
    -- bal is the balance AFTER this row, so a negative is the shortfall.
    raise exception
      'Stock transfer exceeds available stock: % would be left with % of %',
      sender, bal, trim(new.part);
  end if;
  return null;
end $$;

-- ------------------------------------------------------------------------
-- 0090_spare_issue_history.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- WHAT WAS ISSUED — the other half of the historical record.
--
-- Hand stock is, in the user's own words:
--
--     WinMax HS + SO + ST received - Consumption - ST sent - MRN
--
-- Every one of those has a home already except the SO — the stock outs. The
-- issue side has only ever been derived from a spare REQUEST: a dispatch line
-- joined to its request, or (0074/0084) a request line marked dispatched. That
-- covers 2026, where the requests were exported. It cannot cover 2022-2025:
-- the stock-out export has 48,196 rows and 40,085 of them name a request that
-- is not in this system at all.
--
-- So the issues get the same treatment 0075 gave the consumption they paid for:
-- their own table, no cap, and CONSOLIDATED as another arm of
-- handstock_movements — so the balance, the movement trail, engineer_stock, the
-- transfer guard and the 2026 cap all inherit it untouched.
--
-- The arm EXCLUDES any row whose spare is already counted through its request
-- line, so loading the whole stock-out export alongside the 2026 register
-- cannot count 2026 twice. The test is the line's own id (OR number|part), and
-- it is made by the view rather than by the import: it stays right when the
-- 2026 requests are loaded later, or re-loaded.
-- ===========================================================================

-- The opening pools keep what their sheet carried, as every other register
-- does: the WinMax export has the item code, name, type, category, prices and
-- the missing balance, none of which the table has a field for, and the part
-- itself is built from two of them.
alter table public.handstock_opening add column if not exists data jsonb not null default '{}'::jsonb;

create table if not exists public.spare_issue_history (
  id             bigint generated always as identity primary key,
  engineer       text not null,
  engineer_key   text generated always as (public.handstock_key(engineer)) stored,
  part           text not null,                       -- CODE|Description
  part_code      text generated always as (public.part_code(part)) stored,
  qty            numeric not null check (qty > 0),
  issued_at      timestamptz,
  so_no          text not null default '',            -- the stock out it went on
  line_uid       text not null default '',            -- OR number|part, where it has one
  source         text not null,                       -- which body of data this came from
  source_key     text generated always as (lower(btrim(source))) stored,
  ref            text not null default '',            -- its id in that source
  remarks        text not null default '',
  data           jsonb not null default '{}',
  recorded_by      uuid references auth.users (id),
  recorded_by_name text not null default '',
  created_at     timestamptz not null default now()
);

-- PLAIN, not partial. 0075 made this one partial (`where ref <> ''`) and 0077
-- had to undo it: `on conflict` cannot infer a partial index, so the upload was
-- refused outright. The register always sends a ref — the SO number and the
-- line — and a row without one could not be matched on a re-run anyway.
create unique index if not exists spare_issue_history_ref_uniq
  on public.spare_issue_history (source_key, ref);

create index if not exists spare_issue_history_eng_idx  on public.spare_issue_history (engineer_key);
create index if not exists spare_issue_history_part_idx on public.spare_issue_history (part_code);
create index if not exists spare_issue_history_line_idx on public.spare_issue_history (line_uid) where line_uid <> '';

create or replace function public.spare_issue_history_biu()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if btrim(coalesce(new.engineer, '')) = '' then raise exception 'An issued spare needs the engineer it went to.'; end if;
  if btrim(coalesce(new.part, ''))     = '' then raise exception 'An issued spare needs the part.'; end if;
  if btrim(coalesce(new.source, ''))   = '' then raise exception 'An issued spare needs its source (which body of data it came from).'; end if;
  -- PostgREST sends one object per row and fills a key some rows do not carry
  -- with NULL, which a `not null default ''` column then refuses. The default
  -- only applies to a key that is ABSENT — so a mixed batch (a few rows have an
  -- Address, most do not) fails on the ones that do not. Settle it here.
  new.so_no    := coalesce(new.so_no, '');
  new.line_uid := coalesce(new.line_uid, '');
  new.ref      := coalesce(new.ref, '');
  new.remarks  := coalesce(new.remarks, '');
  new.data     := coalesce(new.data, '{}'::jsonb);
  new.recorded_by_name := coalesce(new.recorded_by_name, '');
  if tg_op = 'INSERT' then new.recorded_by := coalesce(new.recorded_by, auth.uid());
  else new.recorded_by := old.recorded_by; new.created_at := old.created_at; end if;
  return new;
end $$;
drop trigger if exists spare_issue_history_biu on public.spare_issue_history;
create trigger spare_issue_history_biu before insert or update on public.spare_issue_history
  for each row execute function public.spare_issue_history_biu();

alter table public.spare_issue_history enable row level security;
grant select, insert, update, delete on public.spare_issue_history to authenticated;

drop policy if exists sih_read on public.spare_issue_history;
create policy sih_read on public.spare_issue_history for select
  using (
    (select public.can_view_all_calls())
    or (select public.has_perm('data.view_all'))
    or lower(btrim(engineer)) in (select lower(btrim(n)) from public.visible_engineer_names() as v(n))
  );

drop policy if exists sih_write on public.spare_issue_history;
create policy sih_write on public.spare_issue_history for all
  using (public.has_perm('consumption.reconcile') or public.has_perm('spare.dispatch'))
  with check (public.has_perm('consumption.reconcile') or public.has_perm('spare.dispatch'));

-- ---------------------------------------------------------------------------
-- The arm.
-- ---------------------------------------------------------------------------
do $hm$
declare v_def text;
begin
  if to_regclass('public.handstock_movements') is null then
    raise notice 'handstock_movements is not present — run the HandStock bundle first';
    return;
  end if;
  if exists (select 1 from pg_views where schemaname = 'public' and viewname = 'handstock_movements'
              and definition ilike '%spare_issue_history%') then
    -- Already carries the arm; still make sure of the line below.
    execute 'alter view public.handstock_movements set (security_invoker = on)';
    return;
  end if;
  v_def := regexp_replace(pg_get_viewdef('public.handstock_movements'::regclass, true), ';\s*$', '');
  execute 'create or replace view public.handstock_movements as ' || v_def || $arm$
UNION ALL
 SELECT 'IN'::text AS direction,
    'Stock out'::text AS movement,
    h.engineer_key,
    COALESCE(h.engineer, ''::text) AS engineer,
    ''::text AS engineer_email,
    h.part_code,
    COALESCE(h.part, ''::text) AS part,
    COALESCE(h.qty, 0::numeric) AS qty,
    COALESCE(h.issued_at, h.created_at) AS moved_at,
    COALESCE(NULLIF(h.so_no, ''::text), NULLIF(h.ref, ''::text), h.source, ''::text) AS ref,
    'Historical'::text AS ref_type,
    ''::text AS ref_uid,
    ''::text AS ucn,
    ''::text AS call_number,
    ''::text AS party_name,
    COALESCE(h.remarks, ''::text) AS remarks
   FROM public.spare_issue_history h
  WHERE NOT EXISTS (
          SELECT 1 FROM public.spare_request_lines l
           WHERE lower(btrim(l.line_uid)) = lower(btrim(h.line_uid))
             AND h.line_uid <> ''::text
             AND (COALESCE(l.dispatched_qty, 0::numeric) > 0::numeric
                  OR COALESCE(l.stores_status, ''::text) ~* 'dispatch'::text))
$arm$;
  -- CREATE OR REPLACE VIEW does NOT carry `security_invoker` over, and without
  -- it the view runs as its OWNER: every arm's row-level security stops
  -- applying and an RM can see another team's hand stock. The scope suite
  -- caught exactly that. Re-assert it, every time this view is rebuilt.
  execute 'alter view public.handstock_movements set (security_invoker = on)';
end $hm$;

-- ---------------------------------------------------------------------------
-- The same NULL-versus-absent trap on the consumption history (0075). Its `ucn`,
-- `call_number` and `party_name` are `not null default ''`, and the yearly
-- exports have rows with no UC Number: PostgREST fills the key it saw on other
-- rows of the batch with NULL, and the default never applies to a key that IS
-- present. One such row failed all 12,292.
-- ---------------------------------------------------------------------------
create or replace function public.spare_consumption_history_biu()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if btrim(coalesce(new.engineer, '')) = '' then raise exception 'A historical consumption row needs the engineer.'; end if;
  if btrim(coalesce(new.part, ''))     = '' then raise exception 'A historical consumption row needs the part.'; end if;
  if btrim(coalesce(new.source, ''))   = '' then raise exception 'A historical consumption row needs its source (which body of data it came from).'; end if;
  new.ucn         := coalesce(new.ucn, '');
  new.call_number := coalesce(new.call_number, '');
  new.party_name  := coalesce(new.party_name, '');
  new.ref         := coalesce(new.ref, '');
  new.remarks     := coalesce(new.remarks, '');
  new.data        := coalesce(new.data, '{}'::jsonb);
  new.recorded_by_name := coalesce(new.recorded_by_name, '');
  if tg_op = 'INSERT' then new.recorded_by := coalesce(new.recorded_by, auth.uid());
  else new.recorded_by := old.recorded_by; new.created_at := old.created_at; end if;
  return new;
end $$;

-- ------------------------------------------------------------------------
-- 0091_handstock_read_indexes.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- HAND STOCK STAYS DERIVED — and gets the indexes to afford it.
--
-- The balance is computed from the movement history on every read, never
-- stored. With the whole record loaded that history is ~103,000 rows, and the
-- plan showed why one engineer's stock still cost 22 ms: every arm filters on
-- `handstock_key(engineer)` and `part_code(part)` — EXPRESSIONS — so each source
-- table was sequentially scanned, however few rows the answer needed.
--
-- Both functions are IMMUTABLE, so they can be indexed. Measured on the full
-- load (4,375 opening + 48,139 issues + 39,724 historical + 8,352 2026
-- consumptions + the 2026 registers):
--
--   one engineer's hand stock         22 ms -> 10 ms
--   the spare picker (engineer_stock)          9 ms
--   entering a consumption (the CAP)  25-33 ms -> 14-19 ms
--   the whole Stock Levels screen    180 ms -> 160 ms
--
-- The last one barely moves, and should not: it aggregates everything, which is
-- a sequential scan by definition. It is the per-engineer paths that are on the
-- hot path — every consumption entry runs the cap, and every spare picker reads
-- one engineer's stock — and those are the ones that halve.
--
-- The tables the later migrations added (opening pools, consumption history,
-- issue history) already carry `engineer_key` / `part_code` as STORED generated
-- columns with indexes on them. These are the older ones, which do not.
-- ===========================================================================

create index if not exists spare_consumption_hs_idx
  on public.spare_consumption (public.handstock_key(engineer), public.part_code(part));

create index if not exists material_returns_hs_idx
  on public.material_returns (public.handstock_key(engineer), public.part_code(part));

create index if not exists spare_requests_hs_idx
  on public.spare_requests (public.handstock_key(engineer));

create index if not exists spare_dispatches_hs_idx
  on public.spare_dispatches (public.handstock_key(engineer));

create index if not exists stock_transfers_from_hs_idx
  on public.stock_transfers (public.handstock_key(from_engineer));

create index if not exists stock_transfers_to_hs_idx
  on public.stock_transfers (public.handstock_key(to_engineer));

create index if not exists stock_transfer_lines_part_hs_idx
  on public.stock_transfer_lines (public.part_code(part));

create index if not exists spare_request_lines_part_hs_idx
  on public.spare_request_lines (public.part_code(part));

-- ------------------------------------------------------------------------
-- 0095_rls_initplans.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- "canceling statement due to statement timeout" — the Hand Stock screen.
--
-- Not the derivation: with row-level security off the whole movement history
-- (103,000 rows) counts in 98 ms and the balance page in 471 ms. With it ON,
-- 11-14 SECONDS. The plan says why:
--
--   Seq Scan on spare_issue_history (actual time=1.756..3948.092 rows=48139)
--     Filter: (has_perm('consumption.reconcile') OR has_perm('spare.dispatch')
--              OR $0 OR $1 OR (hashed SubPlan 3))
--
-- `$0`, `$1` and the SubPlan are InitPlans — evaluated ONCE, because those
-- clauses are written `(select f())`. The two bare `has_perm(...)` calls are
-- not: they run PER ROW. 48,139 rows x 2 calls ≈ 3.9 s on one table, and the
-- view unions two more of that size.
--
-- They come from the `for all` write policies. A FOR ALL policy's USING clause
-- applies to SELECT as well, so every read paid for them.
--
-- Wrapping a call in `(select ...)` makes it an InitPlan: same answer, computed
-- once. Only calls whose arguments do NOT depend on the row are wrapped —
-- `can_see_call(allocated_to)` and `is_spare_requester(spare_requests)` must
-- stay per-row, because that is the question they answer.
-- ===========================================================================

drop policy if exists sih_write on public.spare_issue_history;
create policy sih_write on public.spare_issue_history for all
  using ((select public.has_perm('consumption.reconcile')) or (select public.has_perm('spare.dispatch')))
  with check ((select public.has_perm('consumption.reconcile')) or (select public.has_perm('spare.dispatch')));

drop policy if exists sch_write on public.spare_consumption_history;
create policy sch_write on public.spare_consumption_history for all
  using ((select public.has_perm('consumption.reconcile')) or (select public.has_perm('spare.dispatch')))
  with check ((select public.has_perm('consumption.reconcile')) or (select public.has_perm('spare.dispatch')));

drop policy if exists hso_write on public.handstock_opening;
create policy hso_write on public.handstock_opening for all
  using ((select public.has_perm('consumption.reconcile')) or (select public.has_perm('spare.dispatch')))
  with check ((select public.has_perm('consumption.reconcile')) or (select public.has_perm('spare.dispatch')));

-- The same, on the three the movement view also reads. `sd_read` had THREE bare
-- calls per row; `sdl_write` is a FOR ALL whose USING was paying on every read.
drop policy if exists sdl_write on public.spare_dispatch_lines;
create policy sdl_write on public.spare_dispatch_lines for all
  using ((select public.has_perm('spare.dispatch')))
  with check ((select public.has_perm('spare.dispatch')));

drop policy if exists sd_read on public.spare_dispatches;
create policy sd_read on public.spare_dispatches for select
  using (
    (select public.is_admin())
    or created_by = (select auth.uid())
    or (select public.has_perm('spare.dispatch'))
    or lower(btrim(engineer)) in (select lower(btrim(n)) from public.visible_engineer_names() as v(n))
  );

-- ------------------------------------------------------------------------
-- 0096_handstock_period_close.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- CLOSING A PERIOD — hand stock stops re-deriving history it has already settled.
--
-- The balance is derived from every movement ever recorded. That was right, and
-- affordable, until the whole history was loaded: 103,000 rows through nine
-- arms, each access-checked. Measured on the full load: 98 ms with row-level
-- security OFF, ELEVEN TO FOURTEEN SECONDS with it on — which is what the
-- screen's "canceling statement due to statement timeout" was. 0095's InitPlan
-- fixes took it to 3-5 s. Still too slow, and it grows with every year.
--
-- The answer is the accountant's one, and it beats a cache: CLOSE THE PERIOD.
-- An opening figure per engineer and part carries everything up to a date, and
-- the register reads only what has happened since. Nothing is estimated and
-- nothing goes stale — the figure IS the sum of what it stands for — and the
-- detail stays in its tables, to be read for anything else.
--
-- 86,350 of the 103,000 rows pre-date 2026.
--
-- HOW THE LINE WORKS: every arm, INCLUDING the opening pools, counts only what
-- falls after the cut-off. So a pool struck at 01-Jan-2026 counts and the WinMax
-- pool struck in June 2022 does not, without deleting anything. Upload an
-- opening balance dated the day after the cut-off and the older pools retire
-- themselves.
--
-- `close_handstock_period(date)` will work the figure out and write it for you;
-- `set_handstock_cutoff(date)` only moves the line, for when the figure is one
-- you have prepared and uploaded yourself.
-- ===========================================================================

create table if not exists public.handstock_period (
  singleton      boolean primary key default true check (singleton),
  closed_through date,
  closed_at      timestamptz,
  closed_by      uuid,
  closed_by_name text not null default ''
);
insert into public.handstock_period (singleton) values (true) on conflict (singleton) do nothing;

alter table public.handstock_period enable row level security;
grant select on public.handstock_period to authenticated;
drop policy if exists hp_read on public.handstock_period;
create policy hp_read on public.handstock_period for select using (auth.role() = 'authenticated');

-- The line, as a timestamp: THE FIRST INSTANT STILL OPEN — the day AFTER the one
-- closed through. `-infinity` while nothing is closed, so every arm's test has
-- the same shape whether or not a close has ever been run.
--
-- It has to be that instant and not the closed day's own midnight, and the arms
-- have to test `>=` against it, because THE CLOSE AND THE ARMS MUST DIVIDE THE
-- SAME LINE. The first cut of this returned the closed date itself and the arms
-- tested `>`, which left the whole of the closing day on BOTH sides: summed into
-- the opening figure and still counted as an open movement. On the real data
-- that was six movements, and a close that was supposed to change nothing added
-- two pools and ten parts. `< cutoff` and `>= cutoff` are exact complements, so
-- there is no day either of them can read twice.
create or replace function public.handstock_cutoff()
returns timestamptz language sql stable security definer set search_path = public as $$
  select coalesce((select closed_through + 1 from public.handstock_period limit 1)::timestamptz,
                  '-infinity'::timestamptz);
$$;
grant execute on function public.handstock_cutoff() to authenticated;

-- A CLOSING FIGURE MAY BE NEGATIVE. 0074 wrote `check (qty >= 0)` for a pool
-- somebody types in, where a negative opening makes no sense. A pool that CLOSES
-- a period is a different thing: it must equal exactly what it replaces, and 282
-- engineer-and-part pairs are already negative because the record of what they
-- were issued is incomplete. Refusing those would quietly improve the numbers at
-- the close — the one thing a close must never do. The reconciliation exists to
-- show a shortfall, not to have it rounded away.
alter table public.handstock_opening drop constraint if exists handstock_opening_qty_check;

-- The dates the arms are filtered on, so the cut-off is an index lookup rather
-- than a scan of everything that has ever happened. (Not the MRN date: a cast
-- from date to timestamptz is not immutable, and 595 rows do not need one.)
create index if not exists spare_consumption_history_at_idx
  on public.spare_consumption_history ((coalesce(consumed_at, created_at)));
create index if not exists spare_issue_history_at_idx
  on public.spare_issue_history ((coalesce(issued_at, created_at)));
create index if not exists spare_consumption_created_idx
  on public.spare_consumption (created_at);
create index if not exists handstock_opening_as_of_idx
  on public.handstock_opening (as_of);

-- ---------------------------------------------------------------------------
-- The movement trail, written out in full rather than appended to by string
-- surgery. Nine arms, the cut-off on every one.
--
-- Writing it out is deliberate: appending an arm by editing the view's own text
-- is what silently dropped `security_invoker` when 0090 did it, and a view
-- nobody can read in one piece is a view nobody can check.
-- ---------------------------------------------------------------------------
create or replace view public.handstock_movements as
 SELECT 'IN'::text AS direction,
    'Stock out'::text AS movement,
    handstock_key(r.engineer) AS engineer_key,
    COALESCE(r.engineer, ''::text) AS engineer,
    COALESCE(r.engineer_email, ''::text) AS engineer_email,
    part_code(dl.part) AS part_code,
    COALESCE(dl.part, ''::text) AS part,
    COALESCE(dl.qty, 0::numeric) AS qty,
    COALESCE(d.dispatched_at, dl.created_at) AS moved_at,
    COALESCE(NULLIF(d.dc_number, ''::text), r.or_no, ''::text) AS ref,
    'Stores DC'::text AS ref_type,
    COALESCE(r.uid, ''::text) AS ref_uid,
    COALESCE(r.ucn, ''::text) AS ucn,
    COALESCE(r.call_number, ''::text) AS call_number,
    COALESCE(r.party_name, ''::text) AS party_name,
    COALESCE(NULLIF(l.dispatch_remarks, ''::text), ''::text) AS remarks
   FROM spare_dispatch_lines dl
     JOIN spare_dispatches d ON d.uid = dl.dispatch_uid
     JOIN spare_request_lines l ON l.id = dl.line_id
     JOIN spare_requests r ON r.uid = l.request_uid
  WHERE COALESCE(d.dispatched_at, dl.created_at) >= (SELECT public.handstock_cutoff())
UNION ALL

 SELECT 'IN'::text AS direction,
    'Stock out'::text AS movement,
    handstock_key(r.engineer) AS engineer_key,
    COALESCE(r.engineer, ''::text) AS engineer,
    COALESCE(r.engineer_email, ''::text) AS engineer_email,
    part_code(l.part) AS part_code,
    COALESCE(l.part, ''::text) AS part,
        CASE
            WHEN COALESCE(l.dispatched_qty, 0::numeric) > 0::numeric THEN l.dispatched_qty
            ELSE COALESCE(l.qty, 0::numeric)
        END AS qty,
    COALESCE(l.dispatched_at, r.dispatched_at, l.created_at, r.created_at) AS moved_at,
    COALESCE(NULLIF(l.dc_number, ''::text), r.or_no, ''::text) AS ref,
    'Stores DC'::text AS ref_type,
    COALESCE(r.uid, ''::text) AS ref_uid,
    COALESCE(r.ucn, ''::text) AS ucn,
    COALESCE(r.call_number, ''::text) AS call_number,
    COALESCE(r.party_name, ''::text) AS party_name,
    COALESCE(NULLIF(l.dispatch_remarks, ''::text), ''::text) AS remarks
   FROM spare_request_lines l
     JOIN spare_requests r ON r.uid = l.request_uid
  WHERE COALESCE(l.dispatched_at, r.dispatched_at, l.created_at, r.created_at) >= (SELECT public.handstock_cutoff()) AND (COALESCE(l.dispatched_qty, 0::numeric) > 0::numeric OR COALESCE(l.stores_status, ''::text) ~* 'dispatch'::text) AND NOT (EXISTS ( SELECT 1
           FROM spare_dispatch_lines dl
          WHERE dl.line_id = l.id))
UNION ALL

 SELECT 'OUT'::text AS direction,
    'Consumption'::text AS movement,
    handstock_key(c.engineer) AS engineer_key,
    COALESCE(c.engineer, ''::text) AS engineer,
    COALESCE(c.engineer_email, ''::text) AS engineer_email,
    part_code(c.part) AS part_code,
    COALESCE(c.part, ''::text) AS part,
    COALESCE(c.qty, 0::numeric) AS qty,
    c.created_at AS moved_at,
    COALESCE(NULLIF(btrim(c.call_number), ''::text), COALESCE(c.ucn, ''::text)) AS ref,
    'Call'::text AS ref_type,
    ''::text AS ref_uid,
    COALESCE(c.ucn, ''::text) AS ucn,
    COALESCE(c.call_number, ''::text) AS call_number,
    ''::text AS party_name,
    ''::text AS remarks
   FROM spare_consumption c
  WHERE c.created_at >= (SELECT public.handstock_cutoff())
UNION ALL

 SELECT 'OUT'::text AS direction,
    'Transfer out'::text AS movement,
    handstock_key(t.from_engineer) AS engineer_key,
    COALESCE(t.from_engineer, ''::text) AS engineer,
    ''::text AS engineer_email,
    part_code(l.part) AS part_code,
    COALESCE(l.part, ''::text) AS part,
    COALESCE(l.qty, 0::numeric) AS qty,
    COALESCE(t.transfer_date::timestamp with time zone, t.created_at) AS moved_at,
    COALESCE(t.uid, ''::text) AS ref,
    'Transfer'::text AS ref_type,
    ''::text AS ref_uid,
    ''::text AS ucn,
    ''::text AS call_number,
    COALESCE(t.to_engineer, ''::text) AS party_name,
    COALESCE(t.remarks, ''::text) AS remarks
   FROM stock_transfer_lines l
     JOIN stock_transfers t ON t.uid = l.transfer_uid
  WHERE COALESCE(t.transfer_date::timestamp with time zone, t.created_at) >= (SELECT public.handstock_cutoff())
UNION ALL

 SELECT 'IN'::text AS direction,
    'Transfer in'::text AS movement,
    handstock_key(t.to_engineer) AS engineer_key,
    COALESCE(t.to_engineer, ''::text) AS engineer,
    ''::text AS engineer_email,
    part_code(l.part) AS part_code,
    COALESCE(l.part, ''::text) AS part,
    COALESCE(l.qty, 0::numeric) AS qty,
    COALESCE(t.transfer_date::timestamp with time zone, t.created_at) AS moved_at,
    COALESCE(t.uid, ''::text) AS ref,
    'Transfer'::text AS ref_type,
    ''::text AS ref_uid,
    ''::text AS ucn,
    ''::text AS call_number,
    COALESCE(t.from_engineer, ''::text) AS party_name,
    COALESCE(t.remarks, ''::text) AS remarks
   FROM stock_transfer_lines l
     JOIN stock_transfers t ON t.uid = l.transfer_uid
  WHERE COALESCE(t.transfer_date::timestamp with time zone, t.created_at) >= (SELECT public.handstock_cutoff())
UNION ALL

 SELECT 'OUT'::text AS direction,
    'Return'::text AS movement,
    handstock_key(m.engineer) AS engineer_key,
    COALESCE(m.engineer, ''::text) AS engineer,
    COALESCE(m.engineer_email, ''::text) AS engineer_email,
    part_code(m.part) AS part_code,
    COALESCE(m.part, ''::text) AS part,
    COALESCE(m.good_qty, 0::numeric) + COALESCE(m.defective_qty, 0::numeric) AS qty,
    COALESCE(m.mrn_date::timestamp with time zone, m.returned_at, m.created_at) AS moved_at,
    COALESCE(NULLIF(btrim(m.mrn_no), ''::text), m.uid, ''::text) AS ref,
    'MRN'::text AS ref_type,
    COALESCE(m.uid, ''::text) AS ref_uid,
    ''::text AS ucn,
    COALESCE(m.report_no, ''::text) AS call_number,
    COALESCE(m.customer_name, ''::text) AS party_name,
    btrim(
        CASE
            WHEN COALESCE(m.defective_qty, 0::numeric) > 0::numeric THEN ((('good '::text || COALESCE(m.good_qty, 0::numeric)) || ', defective '::text) || m.defective_qty) || ' · '::text
            ELSE ''::text
        END || COALESCE(m.remarks, ''::text)) AS remarks
   FROM material_returns m
  WHERE COALESCE(m.mrn_date::timestamp with time zone, m.returned_at, m.created_at) >= (SELECT public.handstock_cutoff())
UNION ALL

 SELECT 'IN'::text AS direction,
    'Opening'::text AS movement,
    o.engineer_key,
    COALESCE(o.engineer, ''::text) AS engineer,
    ''::text AS engineer_email,
    o.part_code,
    COALESCE(o.part, ''::text) AS part,
    COALESCE(o.qty, 0::numeric) AS qty,
    o.as_of::timestamp with time zone AS moved_at,
    COALESCE(o.source, ''::text) AS ref,
    'Opening balance'::text AS ref_type,
    ''::text AS ref_uid,
    ''::text AS ucn,
    ''::text AS call_number,
    ''::text AS party_name,
    COALESCE(o.remarks, ''::text) AS remarks
   FROM handstock_opening o
  WHERE o.as_of::timestamp with time zone >= (SELECT public.handstock_cutoff())
UNION ALL

 SELECT 'OUT'::text AS direction,
    'Consumption'::text AS movement,
    h.engineer_key,
    COALESCE(h.engineer, ''::text) AS engineer,
    ''::text AS engineer_email,
    h.part_code,
    COALESCE(h.part, ''::text) AS part,
    COALESCE(h.qty, 0::numeric) AS qty,
    COALESCE(h.consumed_at, h.created_at) AS moved_at,
    COALESCE(NULLIF(h.ref, ''::text), h.source, ''::text) AS ref,
    'Historical'::text AS ref_type,
    ''::text AS ref_uid,
    COALESCE(h.ucn, ''::text) AS ucn,
    COALESCE(h.call_number, ''::text) AS call_number,
    COALESCE(h.party_name, ''::text) AS party_name,
    COALESCE(h.remarks, ''::text) AS remarks
   FROM spare_consumption_history h
  WHERE COALESCE(h.consumed_at, h.created_at) >= (SELECT public.handstock_cutoff())
UNION ALL

 SELECT 'IN'::text AS direction,
    'Stock out'::text AS movement,
    h.engineer_key,
    COALESCE(h.engineer, ''::text) AS engineer,
    ''::text AS engineer_email,
    h.part_code,
    COALESCE(h.part, ''::text) AS part,
    COALESCE(h.qty, 0::numeric) AS qty,
    COALESCE(h.issued_at, h.created_at) AS moved_at,
    COALESCE(NULLIF(h.so_no, ''::text), NULLIF(h.ref, ''::text), h.source, ''::text) AS ref,
    'Historical'::text AS ref_type,
    ''::text AS ref_uid,
    ''::text AS ucn,
    ''::text AS call_number,
    ''::text AS party_name,
    COALESCE(h.remarks, ''::text) AS remarks
   FROM spare_issue_history h
  WHERE COALESCE(h.issued_at, h.created_at) >= (SELECT public.handstock_cutoff()) AND NOT (EXISTS ( SELECT 1
           FROM spare_request_lines l
          WHERE lower(btrim(l.line_uid)) = lower(btrim(h.line_uid)) AND h.line_uid <> ''::text AND (COALESCE(l.dispatched_qty, 0::numeric) > 0::numeric OR COALESCE(l.stores_status, ''::text) ~* 'dispatch'::text)))
;

alter view public.handstock_movements set (security_invoker = on);

-- ---------------------------------------------------------------------------
-- Move the line, when the opening figure is one you have prepared and uploaded.
-- ---------------------------------------------------------------------------
create or replace function public.set_handstock_cutoff(p_through date)
returns date language plpgsql security definer set search_path = public as $$
declare v_name text := coalesce((select full_name from public.profiles where id = auth.uid()), '');
begin
  if not (public.is_admin() or public.has_perm('consumption.reconcile')) then
    raise exception 'Closing a hand-stock period is the Spare Coordinator''s or an administrator''s to do';
  end if;
  if p_through is not null and p_through >= current_date then
    raise exception 'Close a period that has ENDED — % is not in the past', p_through;
  end if;
  update public.handstock_period
     set closed_through = p_through, closed_at = now(), closed_by = auth.uid(), closed_by_name = v_name
   where singleton;
  return p_through;
end $$;
revoke all on function public.set_handstock_cutoff(date) from public;
grant execute on function public.set_handstock_cutoff(date) to authenticated;

-- ---------------------------------------------------------------------------
-- Or work the figure out and write it, in one statement.
--
-- Order matters: the sum is taken BEFORE the line moves, or it would be summing
-- what it is about to hide.
-- ---------------------------------------------------------------------------
create or replace function public.close_handstock_period(p_through date)
returns table (pools int, parts numeric) language plpgsql security definer set search_path = public as $$
declare
  v_source text := 'Opening ' || to_char(p_through + 1, 'YYYY');
  v_name   text := coalesce((select full_name from public.profiles where id = auth.uid()), '');
begin
  if not (public.is_admin() or public.has_perm('consumption.reconcile')) then
    raise exception 'Closing a hand-stock period is the Spare Coordinator''s or an administrator''s to do';
  end if;
  if p_through is null or p_through >= current_date then
    raise exception 'Close a period that has ENDED — % is not in the past', p_through;
  end if;

  -- `< the first open instant` — the exact complement of what the arms keep, so
  -- the closing day belongs to the figure and to nothing else.
  create temp table _close on commit drop as
  select engineer_key,
         min(engineer) filter (where engineer <> '') as engineer,
         part_code,
         min(part)     filter (where part <> '')     as part,
         sum(case when direction = 'IN' then qty else -qty end) as on_hand
    from public.handstock_movements
   where moved_at is null
      or moved_at < (p_through + 1)::timestamptz
   group by engineer_key, part_code
  having sum(case when direction = 'IN' then qty else -qty end) <> 0;

  insert into public.handstock_opening (engineer, part, qty, as_of, source, remarks, recorded_by, recorded_by_name)
  select coalesce(engineer, engineer_key), coalesce(part, part_code), on_hand,
         p_through + 1, v_source,
         'Closed through ' || to_char(p_through, 'DD-Mon-YYYY') || ' — the net of every movement up to that date.',
         auth.uid(), v_name
    from _close
   where coalesce(engineer, engineer_key) <> '' and coalesce(part, part_code) <> ''
  on conflict (engineer_key, part_code, source_key) do update
     set qty = excluded.qty, as_of = excluded.as_of, remarks = excluded.remarks, updated_at = now();

  update public.handstock_period
     set closed_through = p_through, closed_at = now(), closed_by = auth.uid(), closed_by_name = v_name
   where singleton;

  return query select count(*)::int, coalesce(sum(on_hand), 0) from _close;
end $$;
revoke all on function public.close_handstock_period(date) from public;
grant execute on function public.close_handstock_period(date) to authenticated;

-- ------------------------------------------------------------------------
-- 0100_spare_request_reassign.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- CHANGING WHO A SPARE REQUEST IS FOR — until it is dispatched, and logged.
--
-- A request is raised against an engineer and everything downstream follows
-- that name: the approvals, the DC, and — once the parts go out — the engineer's
-- HAND STOCK, which is derived from the request rather than stored. So the name
-- can be corrected while the request is still paper, and must not be touched
-- once it is stock.
--
-- THE LINE IS DISPATCH, and it is drawn wide on purpose: a request counts as
-- dispatched if IT says so, if ANY of its lines says so, or if a dispatch line
-- points at one of its lines. Any one of those means parts have moved, and
-- moving the name afterwards would move somebody else's stock — silently, since
-- hand stock is a derivation and would simply come out different next time it
-- was read.
--
-- THE LOG IS A TABLE, NOT AN AUDIT LINE. The audit log is a general record of
-- actions; this is the answer to "who was this raised for, and who changed it" —
-- a question about the REQUEST, asked from the request. It keeps both names and
-- both addresses, so a row still reads correctly after either person is renamed
-- or leaves.
--
-- The guard is a TRIGGER, not a rule in the client. The client can only ask
-- nicely; PostgREST will happily take an `update` on the table from anyone whose
-- policy allows it, and the import path writes to the same table.
-- ===========================================================================

create table if not exists public.spare_request_engineer_log (
  id              bigint generated always as identity primary key,
  request_uid     text not null references public.spare_requests (uid) on delete cascade,
  or_no           text default '',
  from_engineer   text default '',
  from_email      text default '',
  to_engineer     text default '',
  to_email        text default '',
  reason          text default '',
  changed_at      timestamptz not null default now(),
  changed_by      uuid,
  changed_by_name text default ''
);
create index if not exists spare_request_engineer_log_uid_idx
  on public.spare_request_engineer_log (request_uid, changed_at desc);

alter table public.spare_request_engineer_log enable row level security;
grant select on public.spare_request_engineer_log to authenticated;

-- Who may READ it: an administrator, whoever can approve or dispatch spares,
-- and the two engineers the row is about. A reassignment is not a secret from
-- the person it moved a request away from.
drop policy if exists srel_read on public.spare_request_engineer_log;
create policy srel_read on public.spare_request_engineer_log for select using (
  (select public.is_admin())
  or (select public.has_perm('spare.dispatch'))
  or (select public.has_perm('spare.approve'))
  or lower(from_email) = lower((select auth.email()))
  or lower(to_email)   = lower((select auth.email()))
);
-- Nobody WRITES it directly. The row is written by the function that makes the
-- change, so a log entry cannot exist without the change or the change without
-- the entry.

-- ---------------------------------------------------------------------------
-- Has anything actually gone out against this request?
-- ---------------------------------------------------------------------------
create or replace function public.spare_request_is_dispatched(p_uid text)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.spare_requests r
                  where r.uid = p_uid
                    and (r.dispatched_at is not null
                         or coalesce(r.stores_status, '') ~* 'dispatch'))
      or exists (select 1 from public.spare_request_lines l
                  where l.request_uid = p_uid
                    and (l.dispatched_at is not null
                         or coalesce(l.dispatched_qty, 0) > 0
                         or coalesce(l.stores_status, '') ~* 'dispatch'))
      or exists (select 1 from public.spare_dispatch_lines dl
                   join public.spare_request_lines l on l.id = dl.line_id
                  where l.request_uid = p_uid);
$$;
grant execute on function public.spare_request_is_dispatched(text) to authenticated;

-- ---------------------------------------------------------------------------
-- The change itself. One function, so the check, the write and the log cannot
-- come apart.
-- ---------------------------------------------------------------------------
create or replace function public.reassign_spare_request(
  p_uid text, p_engineer text, p_email text default '', p_reason text default ''
) returns public.spare_requests language plpgsql security definer set search_path = public as $$
declare
  r      public.spare_requests;
  v_name text := coalesce((select full_name from public.profiles where id = auth.uid()), '');
  v_to   text := btrim(coalesce(p_engineer, ''));
  v_mail text := lower(btrim(coalesce(p_email, '')));
begin
  if not public.is_admin() then
    raise exception 'Changing the engineer on a spare request is an administrator''s to do';
  end if;
  if v_to = '' then
    raise exception 'Give the engineer the request is being moved to';
  end if;

  select * into r from public.spare_requests where uid = p_uid;
  if not found then
    raise exception 'No spare request %', p_uid;
  end if;
  if public.spare_request_is_dispatched(p_uid) then
    raise exception 'OR % has already been dispatched — the parts are in %''s hands, so the engineer cannot be changed. Use a stock transfer instead.',
      coalesce(nullif(r.or_no, ''), p_uid), coalesce(nullif(r.engineer, ''), 'the engineer');
  end if;
  if lower(btrim(coalesce(r.engineer, ''))) = lower(v_to)
     and (v_mail = '' or lower(coalesce(r.engineer_email, '')) = v_mail) then
    return r;                       -- already there; nothing to log
  end if;

  -- The address is looked up when it is not given, so the request keeps a
  -- working one: every engineer-scoped read matches on email, and a name with
  -- the wrong address beside it is a request its own engineer cannot see.
  if v_mail = '' then
    v_mail := lower(coalesce((select email from public.profiles
                               where lower(full_name) = lower(v_to)
                               order by id limit 1), ''));
  end if;

  -- Tell the guard trigger that this update is the one it is meant to allow.
  -- `true` scopes it to this transaction, so it cannot leak into the next.
  perform set_config('rithi.reassigning', p_uid, true);

  insert into public.spare_request_engineer_log
    (request_uid, or_no, from_engineer, from_email, to_engineer, to_email, reason, changed_by, changed_by_name)
  values (p_uid, coalesce(r.or_no, ''), coalesce(r.engineer, ''), coalesce(r.engineer_email, ''),
          v_to, v_mail, btrim(coalesce(p_reason, '')), auth.uid(), v_name);

  update public.spare_requests
     set engineer = v_to, engineer_email = v_mail
   where uid = p_uid
  returning * into r;

  perform set_config('rithi.reassigning', '', true);
  return r;
end $$;
revoke all on function public.reassign_spare_request(text, text, text, text) from public;
grant execute on function public.reassign_spare_request(text, text, text, text) to authenticated;

-- ---------------------------------------------------------------------------
-- And the invariant where it cannot be gone round: on the table.
--
-- THE TRIGGER ENFORCES ONE RULE ONLY — not after dispatch. That is the rule
-- that protects the numbers: hand stock is DERIVED from the request, so moving
-- the name after the parts have gone out does not just mis-label a record, it
-- moves stock from one engineer's balance to another's, silently, the next time
-- anybody reads it.
--
-- WHO may change it before dispatch is a permission question, and it is answered
-- by `reassign_spare_request` (administrators) and by the table's own policies.
-- Putting the admin test in the trigger as well would block the BULK UPLOAD,
-- which writes the engineer named in the file and is not run by an administrator
-- as a matter of course.
--
-- A load that tries to change the engineer on an ALREADY DISPATCHED request is
-- refused, and that is right: it means the file disagrees with the register
-- about who is holding parts that have already gone out. That should stop and
-- be looked at, not be applied quietly.
-- ---------------------------------------------------------------------------
create or replace function public.spare_request_engineer_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if lower(btrim(coalesce(new.engineer, ''))) is not distinct from lower(btrim(coalesce(old.engineer, '')))
     and lower(btrim(coalesce(new.engineer_email, ''))) is not distinct from lower(btrim(coalesce(old.engineer_email, ''))) then
    return new;                                    -- the engineer is not changing
  end if;
  if coalesce(current_setting('rithi.reassigning', true), '') = new.uid then
    return new;                                    -- this is the function's own write
  end if;
  if public.spare_request_is_dispatched(new.uid) then
    raise exception 'OR % has already been dispatched — the engineer cannot be changed once the parts have gone out.',
      coalesce(nullif(new.or_no, ''), new.uid);
  end if;
  return new;
end $$;

drop trigger if exists spare_request_engineer_guard on public.spare_requests;
create trigger spare_request_engineer_guard before update on public.spare_requests
  for each row execute function public.spare_request_engineer_guard();

-- ------------------------------------------------------------------------
-- 0102_handstock_balance_history_split.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- THE BALANCE SAYS HOW MUCH OF ITSELF CAME FROM THE IMPORTED RECORD.
--
-- Hand stock is derived from nine arms, and three of them are not this system's
-- own record at all — they are the sheet era, loaded once:
--
--   Opening balance   handstock_opening   the WinMax pool and the yearly ones
--   Historical        spare_issue_history  every stock out before 2026
--   Historical        spare_consumption_history  the yearly consumption exports
--
-- Those three carry hundreds of thousands of parts between them, and a level
-- that looks wrong is usually a question about THEM: an export that was loaded
-- twice, a year that was never loaded, a stock out with no matching
-- consumption. Until now the register could not tell you which part of a number
-- came from where, so "the levels are incorrect" had nowhere to go.
--
-- These four columns split it. `on_hand_live` is the same derivation with the
-- imported record left out — what this application has recorded itself, since
-- 2026 — and it is the honest answer to "ignore the history and show me what we
-- know". It is NOT a correction: both numbers are true, of different questions.
--
-- APPENDED, not inserted. `create or replace view` can only add columns at the
-- end — putting one in the middle fails with "cannot change name of view
-- column" and takes everything that depends on the view with it.
-- ===========================================================================

create or replace view public.handstock_balance as
  select engineer_key,
         max(engineer) as engineer,
         max(engineer_email) as engineer_email,
         part_code,
         coalesce(max(part) filter (where movement = 'Stock out'), max(part)) as part,
         sum(case when movement = 'Stock out'    then qty else 0 end) as stock_out,
         sum(case when movement = 'Consumption'  then qty else 0 end) as consumed,
         sum(case when movement = 'Transfer in'  then qty else 0 end) as transferred_in,
         sum(case when movement = 'Transfer out' then qty else 0 end) as transferred_out,
         sum(case when movement = 'Return'       then qty else 0 end) as returned,
         sum(case when direction = 'IN' then qty else -qty end) as on_hand,
         max(moved_at) filter (where direction = 'IN')  as last_in,
         max(moved_at) filter (where direction = 'OUT') as last_out,
         max(moved_at) as last_movement,
         count(*) as movements,
         sum(case when movement = 'Opening' then qty else 0 end) as opening,
         -- ---- appended: where the number came from -------------------------
         -- The imported stock outs (spare_issue_history), separately from the
         -- ones this system issued on a DC of its own.
         sum(case when ref_type = 'Historical' and movement = 'Stock out'
                  then qty else 0 end) as hist_stock_out,
         -- The imported consumption (the yearly exports).
         sum(case when ref_type = 'Historical' and movement = 'Consumption'
                  then qty else 0 end) as hist_consumed,
         -- Everything the sheet era contributes, in one figure: the opening
         -- pools plus the imported stock outs, less the imported consumption.
         sum(case when ref_type in ('Historical', 'Opening balance')
                  then (case when direction = 'IN' then qty else -qty end)
                  else 0 end) as hist_net,
         -- The same balance with the sheet era left out. Both are true; this
         -- one answers "what has this system itself recorded".
         sum(case when ref_type in ('Historical', 'Opening balance') then 0
                  else (case when direction = 'IN' then qty else -qty end)
             end) as on_hand_live
    from public.handstock_movements m
   where engineer_key <> '' and part_code <> ''
   group by engineer_key, part_code;

-- `create or replace view` does NOT carry security_invoker over, and a balance
-- read as its owner would hand every engineer everybody else's stock.
alter view public.handstock_balance set (security_invoker = on);
grant select on public.handstock_balance to authenticated;

-- ------------------------------------------------------------------------
-- 0036_sales_contracts.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- SALE / WARRANTY and CONTRACT registers — header + items.
--
-- Four AppSheet exports arrive as two parent/child pairs:
--
--   Sale Entry        (SA Number)  →  Warranty Sale Details  (one per machine)
--   Contract Entry    (MC Number)  →  Contract Details       (one per machine)
--
-- The HEADER holds everything common to the deal (party, invoice, period,
-- payment schedule…); each ITEM is one machine sold or covered under it.
--
-- Inheritance is the point of the redesign. In AppSheet every common value was
-- COPIED onto each child row, so editing the header left the children on the
-- old value — the export shows the drift: 681 warranty dates, 403 contract
-- statuses and 244 entry dates disagreeing with their own header. Here a common
-- value is stored ONCE on the header, and the item's matching column is an
-- OVERRIDE that is null unless someone deliberately sets it. The effective
-- value is coalesce(item, header), served by the *_details views — so changing
-- the header changes every item under it, except the ones deliberately pinned.
--
-- Machines whose cover genuinely differs from their header (a unit added to the
-- deal later, say) keep that value as an override at import, so nothing is lost.
--
-- The cover on the machine itself (products.warranty_* / contract_*) is kept in
-- step by sync_product_cover(): the machine master stays the one place a call
-- form reads cover from, but the registers are now what maintains it.
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- 1. Sale Entry (header) — one sale / delivery to a party.
-- ---------------------------------------------------------------------------
create table if not exists public.sale_entries (
  id               bigint generated always as identity primary key,
  sa_number        text not null unique,              -- SA Number
  entry_at         timestamptz,                       -- Timestamp
  party_name       text default '',
  sold_through     text default '',
  invoice_no       text default '',
  invoice_date     date,
  warranty_start   date,
  warranty_end     date,
  warranty_years   numeric,
  warranty_months  integer,
  pm_visits        integer,
  warranty_status  text default '',                   -- as keyed; the live state is derived
  other_details    text default '',
  party_type       text default '',                   -- Type (CUSTOMER / DEALER)
  profile          text default '',                   -- PRIVATE / GOVERNMENT / DEALER
  country          text default '',
  state            text default '',
  city             text default '',
  engineer         text default '',                   -- Service Engineer - Initial
  address          text default '',
  pincode          text default '',                   -- Inst. Pincode
  tel1             text default '',
  tel2             text default '',
  pan              text default '',
  gst              text default '',
  tax              text default '',
  extra            jsonb not null default '{}',
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  created_by       uuid references auth.users (id) default auth.uid()
);

-- ---------------------------------------------------------------------------
-- 2. Warranty Sale Details (items) — one machine on a sale.
-- Every nullable column that also exists on the header is an OVERRIDE.
-- ---------------------------------------------------------------------------
create table if not exists public.sale_items (
  id               bigint generated always as identity primary key,
  uid              text not null unique,              -- SA|Product|Serial
  sa_number        text not null references public.sale_entries (sa_number)
                     on update cascade on delete cascade,
  priority         integer default 1,
  product_code     text default '',
  product_name     text default '',
  serial_number    text default '',
  -- overrides (null = inherit the header)
  invoice_no       text,
  invoice_date     date,
  sold_through     text,
  warranty_start   date,
  warranty_end     date,
  warranty_years   numeric,
  warranty_months  integer,
  pm_visits        integer,
  warranty_status  text,
  other_details    text,
  state            text,
  city             text,
  engineer         text,
  -- item-only
  accessories_included  boolean,
  consumable_included   boolean,
  contract_price_fixed  boolean,
  already_sold_to       text default '',
  replacement_unit      boolean,
  replacement_unit_sl   text default '',
  add_call              text default '',
  inst_call             text default '',
  added_by              text default '',
  extra            jsonb not null default '{}',
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  created_by       uuid references auth.users (id) default auth.uid()
);
create index if not exists sale_items_sa_idx     on public.sale_items (sa_number);
create index if not exists sale_items_serial_idx on public.sale_items (lower(trim(serial_number)));
create index if not exists sale_entries_party_idx on public.sale_entries (lower(trim(party_name)));

-- ---------------------------------------------------------------------------
-- 3. Contract Entry (header) and 4. Contract Details (items).
-- ---------------------------------------------------------------------------
create table if not exists public.contract_entries (
  id               bigint generated always as identity primary key,
  mc_number        text not null unique,              -- MC Number
  entry_at         timestamptz,                       -- Contract Entry Date
  party_name       text default '',
  payment_schedule text default '',
  bill_generate_at text default '',
  contract_type    text default '',                   -- CMC / AMC
  contract_start   date,
  contract_end     date,
  contract_years   numeric,
  contract_months  integer,
  pm_visits_total  integer,
  status           text default '',
  prev_mc_number   text default '',
  extra            jsonb not null default '{}',
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  created_by       uuid references auth.users (id) default auth.uid()
);

create table if not exists public.contract_items (
  id               bigint generated always as identity primary key,
  uid              text not null unique,              -- MC|Product|Serial
  mc_number        text not null references public.contract_entries (mc_number)
                     on update cascade on delete cascade,
  priority         integer default 2,
  product_code     text default '',
  product_name     text default '',
  serial_number    text default '',
  -- overrides (null = inherit the header)
  entry_at         timestamptz,
  party_name       text,
  payment_schedule text,
  bill_generate_at text,
  contract_type    text,
  contract_start   date,
  contract_end     date,
  contract_years   numeric,
  contract_months  integer,
  pm_visits_total  integer,
  status           text,
  -- item-only
  rate                  numeric,
  item_tax_amount       numeric,
  total_after_tax       numeric,
  present_item_status   text default '',              -- OGP / WGP / CMC / AMC
  last_contract_number  text default '',
  last_contract_end     date,
  sa_number             text default '',              -- the sale this machine came from
  sa_end_date           date,                         -- its warranty end
  added_by              text default '',
  extra            jsonb not null default '{}',
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  created_by       uuid references auth.users (id) default auth.uid()
);
create index if not exists contract_items_mc_idx     on public.contract_items (mc_number);
create index if not exists contract_items_serial_idx on public.contract_items (lower(trim(serial_number)));
create index if not exists contract_entries_party_idx on public.contract_entries (lower(trim(party_name)));

-- ---------------------------------------------------------------------------
-- Item UID and the "|" display strings.
-- AppSheet keyed a contract item as MC|Product|Serial and showed
-- Item Details = Product|Serial, Item Details Long = Code|Product|Serial. Both
-- are derived here rather than stored, so they cannot drift from the item.
-- ---------------------------------------------------------------------------
create or replace function public.cover_item_uid(p_head text, p_product text, p_serial text)
returns text language sql immutable as $$
  select trim(coalesce(p_head, '')) || '|' || trim(coalesce(p_product, '')) || '|' || trim(coalesce(p_serial, ''));
$$;

create or replace function public.sale_items_defaults()
returns trigger language plpgsql set search_path = public as $$
begin
  if new.uid is null or trim(new.uid) = '' then
    new.uid := public.cover_item_uid(new.sa_number, new.product_name, new.serial_number);
  end if;
  new.updated_at := now();
  return new;
end $$;
drop trigger if exists sale_items_defaults on public.sale_items;
create trigger sale_items_defaults before insert or update on public.sale_items
  for each row execute function public.sale_items_defaults();

create or replace function public.contract_items_defaults()
returns trigger language plpgsql set search_path = public as $$
begin
  if new.uid is null or trim(new.uid) = '' then
    new.uid := public.cover_item_uid(new.mc_number, new.product_name, new.serial_number);
  end if;
  new.updated_at := now();
  return new;
end $$;
drop trigger if exists contract_items_defaults on public.contract_items;
create trigger contract_items_defaults before insert or update on public.contract_items
  for each row execute function public.contract_items_defaults();

create or replace function public.touch_updated_at()
returns trigger language plpgsql set search_path = public as $$
begin new.updated_at := now(); return new; end $$;
drop trigger if exists sale_entries_touch on public.sale_entries;
create trigger sale_entries_touch before update on public.sale_entries
  for each row execute function public.touch_updated_at();
drop trigger if exists contract_entries_touch on public.contract_entries;
create trigger contract_entries_touch before update on public.contract_entries
  for each row execute function public.touch_updated_at();

-- ---------------------------------------------------------------------------
-- Import order must not matter. An item whose header has not been loaded yet
-- would fail its foreign key, so a stub header is created for it — the real
-- one fills the columns in when its file is imported (the stub is matched on
-- SA / MC number, so nothing is duplicated).
-- ---------------------------------------------------------------------------
create or replace function public.sale_items_stub_header()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if not exists (select 1 from public.sale_entries where sa_number = new.sa_number) then
    insert into public.sale_entries (sa_number) values (new.sa_number) on conflict do nothing;
  end if;
  return new;
end $$;
drop trigger if exists sale_items_stub_header on public.sale_items;
create trigger sale_items_stub_header before insert on public.sale_items
  for each row execute function public.sale_items_stub_header();

create or replace function public.contract_items_stub_header()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if not exists (select 1 from public.contract_entries where mc_number = new.mc_number) then
    insert into public.contract_entries (mc_number) values (new.mc_number) on conflict do nothing;
  end if;
  return new;
end $$;
drop trigger if exists contract_items_stub_header on public.contract_items;
create trigger contract_items_stub_header before insert on public.contract_items
  for each row execute function public.contract_items_stub_header();

-- ---------------------------------------------------------------------------
-- Cover state, derived from the effective end date. "ABOUT TO EXPIRE" is the
-- word the sheets use for the last 60 days, so it is kept.
-- ---------------------------------------------------------------------------
create or replace function public.cover_state(p_end date)
returns text language sql immutable as $$
  select case
    when p_end is null then 'NOT COVERED'
    when p_end < current_date then 'INACTIVE'
    when p_end <= current_date + 60 then 'ABOUT TO EXPIRE'
    else 'ACTIVE' end;
$$;

-- ---------------------------------------------------------------------------
-- The two "details" views: every AppSheet column, with each common value
-- resolved as coalesce(item override, header). This is what the registers
-- read, and what an export of the old shape would be rebuilt from.
-- ---------------------------------------------------------------------------
create or replace view public.warranty_sale_details as
select
  i.id, i.uid, i.sa_number, i.priority,
  i.product_code, i.product_name, i.serial_number,
  case when coalesce(i.product_code, '') = '' then '' else i.product_code || '|' end
    || coalesce(i.product_name, '') || '|' || coalesce(i.serial_number, '')  as item_details_long,
  coalesce(i.product_name, '') || '|' || coalesce(i.serial_number, '')       as item_details,
  h.entry_at                                     as sale_entry_date,
  h.party_name,
  coalesce(i.sold_through,    h.sold_through)    as sold_through,
  coalesce(i.invoice_no,      h.invoice_no)      as invoice_no,
  coalesce(i.invoice_date,    h.invoice_date)    as invoice_date,
  coalesce(i.warranty_start,  h.warranty_start)  as warranty_start,
  coalesce(i.warranty_end,    h.warranty_end)    as warranty_end,
  coalesce(i.warranty_years,  h.warranty_years)  as warranty_years,
  coalesce(i.warranty_months, h.warranty_months) as warranty_months,
  coalesce(i.pm_visits,       h.pm_visits)       as pm_visits,
  coalesce(i.other_details,   h.other_details)   as other_details,
  coalesce(i.state,           h.state)           as state,
  coalesce(i.city,            h.city)            as city,
  coalesce(i.engineer,        h.engineer)        as engineer,
  coalesce(i.warranty_status, h.warranty_status) as warranty_status_keyed,
  public.cover_state(coalesce(i.warranty_end, h.warranty_end)) as warranty_state,
  i.accessories_included, i.consumable_included, i.contract_price_fixed,
  i.already_sold_to, i.replacement_unit, i.replacement_unit_sl,
  i.add_call, i.inst_call, i.added_by,
  h.party_type, h.profile, h.country, h.address, h.pincode, h.tel1, h.tel2, h.pan, h.gst, h.tax,
  -- which columns this item pins rather than inherits
  (select array_agg(k) from (values
     ('invoice_no', i.invoice_no is not null), ('invoice_date', i.invoice_date is not null),
     ('sold_through', i.sold_through is not null), ('warranty_start', i.warranty_start is not null),
     ('warranty_end', i.warranty_end is not null), ('warranty_years', i.warranty_years is not null),
     ('warranty_months', i.warranty_months is not null), ('pm_visits', i.pm_visits is not null),
     ('warranty_status', i.warranty_status is not null), ('other_details', i.other_details is not null),
     ('state', i.state is not null), ('city', i.city is not null), ('engineer', i.engineer is not null)
   ) as t(k, on_) where on_)                     as overridden,
  i.updated_at
from public.sale_items i
join public.sale_entries h on h.sa_number = i.sa_number;

create or replace view public.contract_details as
select
  i.id, i.uid, i.mc_number, i.priority,
  i.product_code, i.product_name, i.serial_number,
  case when coalesce(i.product_code, '') = '' then '' else i.product_code || '|' end
    || coalesce(i.product_name, '') || '|' || coalesce(i.serial_number, '')  as item_details_long,
  coalesce(i.product_name, '') || '|' || coalesce(i.serial_number, '')       as item_details,
  coalesce(i.entry_at,         h.entry_at)         as contract_entry_date,
  coalesce(i.party_name,       h.party_name)       as party_name,
  coalesce(i.payment_schedule, h.payment_schedule) as payment_schedule,
  coalesce(i.bill_generate_at, h.bill_generate_at) as bill_generate_at,
  coalesce(i.contract_type,    h.contract_type)    as contract_type,
  coalesce(i.contract_start,   h.contract_start)   as contract_start,
  coalesce(i.contract_end,     h.contract_end)     as contract_end,
  coalesce(i.contract_years,   h.contract_years)   as contract_years,
  coalesce(i.contract_months,  h.contract_months)  as contract_months,
  coalesce(i.pm_visits_total,  h.pm_visits_total)  as pm_visits_total,
  coalesce(i.status,           h.status)           as status_keyed,
  public.cover_state(coalesce(i.contract_end, h.contract_end)) as contract_state,
  i.rate, i.item_tax_amount, i.total_after_tax,
  i.present_item_status, i.last_contract_number, i.last_contract_end,
  i.sa_number, i.sa_end_date, i.added_by,
  h.prev_mc_number,
  (select array_agg(k) from (values
     ('entry_at', i.entry_at is not null), ('party_name', i.party_name is not null),
     ('payment_schedule', i.payment_schedule is not null), ('bill_generate_at', i.bill_generate_at is not null),
     ('contract_type', i.contract_type is not null), ('contract_start', i.contract_start is not null),
     ('contract_end', i.contract_end is not null), ('contract_years', i.contract_years is not null),
     ('contract_months', i.contract_months is not null), ('pm_visits_total', i.pm_visits_total is not null),
     ('status', i.status is not null)
   ) as t(k, on_) where on_)                       as overridden,
  i.updated_at
from public.contract_items i
join public.contract_entries h on h.mc_number = i.mc_number;

grant select on public.warranty_sale_details to authenticated;
grant select on public.contract_details      to authenticated;

-- ---------------------------------------------------------------------------
-- One machine, its current cover: the latest warranty and the latest contract
-- on that serial. This is the machine-level answer the registers show and what
-- the product master is synced from.
-- ---------------------------------------------------------------------------
create or replace view public.machine_cover as
with w as (
  select distinct on (lower(trim(serial_number)))
         lower(trim(serial_number)) as skey, serial_number, product_name, product_code, party_name,
         sa_number, warranty_start, warranty_end, state, city, engineer
    from public.warranty_sale_details
   where coalesce(serial_number, '') <> ''
   order by lower(trim(serial_number)), warranty_end desc nulls last, id desc
), c as (
  select distinct on (lower(trim(serial_number)))
         lower(trim(serial_number)) as skey, serial_number, product_name, product_code, party_name,
         mc_number, contract_type, contract_start, contract_end, present_item_status
    from public.contract_details
   where coalesce(serial_number, '') <> ''
   order by lower(trim(serial_number)), contract_end desc nulls last, id desc
)
select
  coalesce(w.skey, c.skey)                       as serial_key,
  coalesce(w.serial_number, c.serial_number)     as serial_number,
  coalesce(c.product_name, w.product_name)       as product_name,
  coalesce(c.product_code, w.product_code)       as product_code,
  coalesce(c.party_name, w.party_name)           as party_name,
  w.sa_number, w.warranty_start, w.warranty_end,
  public.cover_state(w.warranty_end)             as warranty_state,
  c.mc_number, c.contract_type, c.contract_start, c.contract_end,
  public.cover_state(c.contract_end)             as contract_state,
  c.present_item_status, w.state, w.city, w.engineer,
  -- What the machine is under TODAY. A live contract outranks a live warranty
  -- (contract items carry priority 2, warranty items 1 — the same order
  -- AppSheet used), and OGP means out of both.
  case
    when c.contract_end >= current_date then coalesce(nullif(c.contract_type, ''), 'CMC')
    when w.warranty_end >= current_date then 'WGP'
    else 'OGP' end                               as item_status
from w full join c on c.skey = w.skey;
grant select on public.machine_cover to authenticated;

-- ---------------------------------------------------------------------------
-- Keep products (the machine master the call form reads) in step with the
-- registers. A sale or contract item is the source; the machine row is the
-- cache in front of it.
-- ---------------------------------------------------------------------------
create or replace function public.sync_product_cover(p_serial text)
returns void language plpgsql security definer set search_path = public as $$
declare k text := lower(trim(coalesce(p_serial, ''))); w record; c record;
begin
  if k = '' then return; end if;
  -- Indexed single-serial lookups, not a pass over machine_cover: an import
  -- fires this once per item, so it has to be cheap.
  select i.sa_number, coalesce(i.warranty_start, h.warranty_start) as warranty_start,
         coalesce(i.warranty_end, h.warranty_end) as warranty_end
    into w
    from public.sale_items i join public.sale_entries h on h.sa_number = i.sa_number
   where lower(trim(i.serial_number)) = k
   order by coalesce(i.warranty_end, h.warranty_end) desc nulls last, i.id desc limit 1;
  select i.mc_number, coalesce(i.contract_type, h.contract_type) as contract_type,
         coalesce(i.contract_start, h.contract_start) as contract_start,
         coalesce(i.contract_end, h.contract_end) as contract_end
    into c
    from public.contract_items i join public.contract_entries h on h.mc_number = i.mc_number
   where lower(trim(i.serial_number)) = k
   order by coalesce(i.contract_end, h.contract_end) desc nulls last, i.id desc limit 1;

  update public.products p set
    warranty_number = coalesce(w.sa_number, p.warranty_number),
    warranty_start  = coalesce(w.warranty_start, p.warranty_start),
    warranty_end    = coalesce(w.warranty_end,   p.warranty_end),
    contract_number = coalesce(c.mc_number, p.contract_number),
    contract_start  = coalesce(c.contract_start, p.contract_start),
    contract_end    = coalesce(c.contract_end,   p.contract_end),
    contract_type   = coalesce(nullif(c.contract_type, ''), p.contract_type),
    item_status     = case
      when c.contract_end >= current_date then coalesce(nullif(c.contract_type, ''), 'CMC')
      when w.warranty_end >= current_date then 'WGP'
      else 'OGP' end
  where lower(trim(p.serial_number)) = k;
end $$;
grant execute on function public.sync_product_cover(text) to authenticated;

create or replace function public.cover_item_sync()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  perform public.sync_product_cover((case when tg_op = 'DELETE' then old else new end).serial_number);
  if tg_op = 'UPDATE' and old.serial_number is distinct from new.serial_number then
    perform public.sync_product_cover(old.serial_number);
  end if;
  return null;
end $$;
drop trigger if exists sale_items_sync_cover on public.sale_items;
create trigger sale_items_sync_cover after insert or update or delete on public.sale_items
  for each row execute function public.cover_item_sync();
drop trigger if exists contract_items_sync_cover on public.contract_items;
create trigger contract_items_sync_cover after insert or update or delete on public.contract_items
  for each row execute function public.cover_item_sync();

-- Editing a HEADER changes the cover of every item that inherits from it, so
-- the machines under it are re-synced in one statement.
create or replace function public.cover_header_sync()
returns trigger language plpgsql security definer set search_path = public as $$
declare r record;
begin
  if tg_table_name = 'sale_entries' then
    for r in select serial_number from public.sale_items where sa_number = new.sa_number loop
      perform public.sync_product_cover(r.serial_number);
    end loop;
  else
    for r in select serial_number from public.contract_items where mc_number = new.mc_number loop
      perform public.sync_product_cover(r.serial_number);
    end loop;
  end if;
  return null;
end $$;
drop trigger if exists sale_entries_sync_cover on public.sale_entries;
create trigger sale_entries_sync_cover after update on public.sale_entries
  for each row execute function public.cover_header_sync();
drop trigger if exists contract_entries_sync_cover on public.contract_entries;
create trigger contract_entries_sync_cover after update on public.contract_entries
  for each row execute function public.cover_header_sync();

-- Bulk re-sync, for after an import (the per-row trigger already covers
-- ordinary edits). Returns how many machines it touched.
create or replace function public.refresh_product_cover()
returns integer language plpgsql security definer set search_path = public as $$
declare n integer;
begin
  -- One statement over machine_cover, not one call per machine: after an
  -- import there are tens of thousands of items to reconcile.
  update public.products p set
    warranty_number = coalesce(m.sa_number, p.warranty_number),
    warranty_start  = coalesce(m.warranty_start, p.warranty_start),
    warranty_end    = coalesce(m.warranty_end,   p.warranty_end),
    contract_number = coalesce(m.mc_number, p.contract_number),
    contract_start  = coalesce(m.contract_start, p.contract_start),
    contract_end    = coalesce(m.contract_end,   p.contract_end),
    contract_type   = coalesce(nullif(m.contract_type, ''), p.contract_type),
    item_status     = m.item_status
  from public.machine_cover m
  where m.serial_key = lower(trim(p.serial_number));
  get diagnostics n = row_count;
  return n;
end $$;
grant execute on function public.refresh_product_cover() to authenticated;

-- ---------------------------------------------------------------------------
-- After an import, fold the copied-down values back into inheritance.
--
-- The AppSheet exports repeat every header value on every child row, and they
-- are loaded AS EXPORTED so nothing is lost or silently reinterpreted. This
-- then nulls each item column that merely repeats its header, leaving only the
-- values that genuinely differ pinned as overrides. Run it after loading the
-- details files; it is idempotent and safe to re-run.
-- ---------------------------------------------------------------------------
create or replace function public.cover_unpin_inherited()
returns integer language plpgsql security definer set search_path = public as $$
declare n integer := 0; m integer;
begin
  update public.sale_items i set
    invoice_no      = case when i.invoice_no      is not distinct from h.invoice_no      then null else i.invoice_no end,
    invoice_date    = case when i.invoice_date    is not distinct from h.invoice_date    then null else i.invoice_date end,
    sold_through    = case when i.sold_through    is not distinct from h.sold_through    then null else i.sold_through end,
    warranty_start  = case when i.warranty_start  is not distinct from h.warranty_start  then null else i.warranty_start end,
    warranty_end    = case when i.warranty_end    is not distinct from h.warranty_end    then null else i.warranty_end end,
    warranty_years  = case when i.warranty_years  is not distinct from h.warranty_years  then null else i.warranty_years end,
    warranty_months = case when i.warranty_months is not distinct from h.warranty_months then null else i.warranty_months end,
    pm_visits       = case when i.pm_visits       is not distinct from h.pm_visits       then null else i.pm_visits end,
    warranty_status = case when i.warranty_status is not distinct from h.warranty_status then null else i.warranty_status end,
    other_details   = case when i.other_details   is not distinct from h.other_details   then null else i.other_details end,
    state           = case when i.state           is not distinct from h.state           then null else i.state end,
    city            = case when i.city            is not distinct from h.city            then null else i.city end,
    engineer        = case when i.engineer        is not distinct from h.engineer        then null else i.engineer end
  from public.sale_entries h where h.sa_number = i.sa_number;
  get diagnostics m = row_count; n := n + m;

  update public.contract_items i set
    entry_at         = case when i.entry_at         is not distinct from h.entry_at         then null else i.entry_at end,
    party_name       = case when i.party_name       is not distinct from h.party_name       then null else i.party_name end,
    payment_schedule = case when i.payment_schedule is not distinct from h.payment_schedule then null else i.payment_schedule end,
    bill_generate_at = case when i.bill_generate_at is not distinct from h.bill_generate_at then null else i.bill_generate_at end,
    contract_type    = case when i.contract_type    is not distinct from h.contract_type    then null else i.contract_type end,
    contract_start   = case when i.contract_start   is not distinct from h.contract_start   then null else i.contract_start end,
    contract_end     = case when i.contract_end     is not distinct from h.contract_end     then null else i.contract_end end,
    contract_years   = case when i.contract_years   is not distinct from h.contract_years   then null else i.contract_years end,
    contract_months  = case when i.contract_months  is not distinct from h.contract_months  then null else i.contract_months end,
    pm_visits_total  = case when i.pm_visits_total  is not distinct from h.pm_visits_total  then null else i.pm_visits_total end,
    status           = case when i.status           is not distinct from h.status           then null else i.status end
  from public.contract_entries h where h.mc_number = i.mc_number;
  get diagnostics m = row_count; n := n + m;
  return n;
end $$;
grant execute on function public.cover_unpin_inherited() to authenticated;

-- ---------------------------------------------------------------------------
-- RLS. Reading is for anyone who may see the masters; writing needs the
-- Commercial action `cover.edit` (Roles & Permissions), because a sale or a
-- contract is a commercial record, not a service one.
-- ---------------------------------------------------------------------------
alter table public.sale_entries     enable row level security;
alter table public.sale_items       enable row level security;
alter table public.contract_entries enable row level security;
alter table public.contract_items   enable row level security;

do $$
declare t text;
begin
  foreach t in array array['sale_entries', 'sale_items', 'contract_entries', 'contract_items'] loop
    execute format('drop policy if exists %1$s_read on public.%1$s;', t);
    execute format($f$create policy %1$s_read on public.%1$s for select
                        using (public.has_perm('masters.view') or public.has_perm('cover.edit') or public.is_admin());$f$, t);
    execute format('drop policy if exists %1$s_write on public.%1$s;', t);
    execute format($f$create policy %1$s_write on public.%1$s for all
                        using (public.has_perm('cover.edit')) with check (public.has_perm('cover.edit'));$f$, t);
  end loop;
end $$;

-- Everyone who may open the registers may read them; grant the table rights the
-- policies then filter.
grant select on public.sale_entries, public.sale_items,
                public.contract_entries, public.contract_items to authenticated;
grant insert, update, delete on public.sale_entries, public.sale_items,
                public.contract_entries, public.contract_items to authenticated;

-- `cover.edit` is new: give it to the roles that already maintain master data,
-- so an existing project does not lose access the moment this lands.
update public.app_roles
   set permissions = coalesce(permissions, '[]'::jsonb) || '["cover.edit"]'::jsonb
 where role in ('admin', 'commercial', 'nsm')
   and not coalesce(permissions, '[]'::jsonb) ? 'cover.edit';

-- ------------------------------------------------------------------------
-- 0037_cover_import_speed.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Importing the cover registers has to finish inside a statement timeout.
--
-- Every sale / contract item syncs the machine it names (sync_product_cover),
-- which updates `products` by lower(trim(serial_number)) — an EXPRESSION, so
-- without a matching index each row seq-scanned the whole Product Master. At
-- ~21k machines that is ~5ms a row: a 1,000-row insert ran for seconds and
-- Supabase cancelled it ("canceling statement due to statement timeout").
--
-- With the index the same 17,321-row file lands in well under a second.
--
-- The two post-import functions are given their own statement_timeout as well:
-- they are single statements over every item row (~35k), and they are run by
-- `authenticated`, whose timeout is a few seconds.
-- ===========================================================================

create index if not exists products_serial_key_idx
  on public.products (lower(trim(serial_number)));

-- machine_cover pairs the two item tables by serial; keep both sides indexed
-- the same way (0036 created these — repeated here for a project that is
-- applying only this file).
create index if not exists sale_items_serial_idx     on public.sale_items (lower(trim(serial_number)));
create index if not exists contract_items_serial_idx on public.contract_items (lower(trim(serial_number)));

create or replace function public.refresh_product_cover()
returns integer language plpgsql security definer
set search_path = public set statement_timeout = '180s' as $$
declare n integer;
begin
  update public.products p set
    warranty_number = coalesce(m.sa_number, p.warranty_number),
    warranty_start  = coalesce(m.warranty_start, p.warranty_start),
    warranty_end    = coalesce(m.warranty_end,   p.warranty_end),
    contract_number = coalesce(m.mc_number, p.contract_number),
    contract_start  = coalesce(m.contract_start, p.contract_start),
    contract_end    = coalesce(m.contract_end,   p.contract_end),
    contract_type   = coalesce(nullif(m.contract_type, ''), p.contract_type),
    item_status     = m.item_status
  from public.machine_cover m
  where m.serial_key = lower(trim(p.serial_number));
  get diagnostics n = row_count;
  return n;
end $$;
grant execute on function public.refresh_product_cover() to authenticated;

create or replace function public.cover_unpin_inherited()
returns integer language plpgsql security definer
set search_path = public set statement_timeout = '180s' as $$
declare n integer := 0; m integer;
begin
  update public.sale_items i set
    invoice_no      = case when i.invoice_no      is not distinct from h.invoice_no      then null else i.invoice_no end,
    invoice_date    = case when i.invoice_date    is not distinct from h.invoice_date    then null else i.invoice_date end,
    sold_through    = case when i.sold_through    is not distinct from h.sold_through    then null else i.sold_through end,
    warranty_start  = case when i.warranty_start  is not distinct from h.warranty_start  then null else i.warranty_start end,
    warranty_end    = case when i.warranty_end    is not distinct from h.warranty_end    then null else i.warranty_end end,
    warranty_years  = case when i.warranty_years  is not distinct from h.warranty_years  then null else i.warranty_years end,
    warranty_months = case when i.warranty_months is not distinct from h.warranty_months then null else i.warranty_months end,
    pm_visits       = case when i.pm_visits       is not distinct from h.pm_visits       then null else i.pm_visits end,
    warranty_status = case when i.warranty_status is not distinct from h.warranty_status then null else i.warranty_status end,
    other_details   = case when i.other_details   is not distinct from h.other_details   then null else i.other_details end,
    state           = case when i.state           is not distinct from h.state           then null else i.state end,
    city            = case when i.city            is not distinct from h.city            then null else i.city end,
    engineer        = case when i.engineer        is not distinct from h.engineer        then null else i.engineer end
  from public.sale_entries h where h.sa_number = i.sa_number;
  get diagnostics m = row_count; n := n + m;

  update public.contract_items i set
    entry_at         = case when i.entry_at         is not distinct from h.entry_at         then null else i.entry_at end,
    party_name       = case when i.party_name       is not distinct from h.party_name       then null else i.party_name end,
    payment_schedule = case when i.payment_schedule is not distinct from h.payment_schedule then null else i.payment_schedule end,
    bill_generate_at = case when i.bill_generate_at is not distinct from h.bill_generate_at then null else i.bill_generate_at end,
    contract_type    = case when i.contract_type    is not distinct from h.contract_type    then null else i.contract_type end,
    contract_start   = case when i.contract_start   is not distinct from h.contract_start   then null else i.contract_start end,
    contract_end     = case when i.contract_end     is not distinct from h.contract_end     then null else i.contract_end end,
    contract_years   = case when i.contract_years   is not distinct from h.contract_years   then null else i.contract_years end,
    contract_months  = case when i.contract_months  is not distinct from h.contract_months  then null else i.contract_months end,
    pm_visits_total  = case when i.pm_visits_total  is not distinct from h.pm_visits_total  then null else i.pm_visits_total end,
    status           = case when i.status           is not distinct from h.status           then null else i.status end
  from public.contract_entries h where h.mc_number = i.mc_number;
  get diagnostics m = row_count; n := n + m;
  return n;
end $$;
grant execute on function public.cover_unpin_inherited() to authenticated;

analyze public.products;

-- ------------------------------------------------------------------------
-- 0072_ownership_transfer.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- OWNERSHIP TRANSFER — a machine moves from one party to another.
--
-- `products` carries ONE party per serial: who owns the machine now. That is
-- what every call, warranty and contract reads. But a machine that changes
-- hands leaves no trace of it — the old owner is simply overwritten, and the
-- question "who had this machine when that call was raised" becomes
-- unanswerable. For a medical device that is a traceability gap, not an
-- inconvenience.
--
-- So the MOVEMENT is the record, and `products.party_name` is derived from it:
--   * the register keeps every hand-over, with its date and its paperwork
--   * a trigger moves the machine to the new party, so the two cannot disagree
--   * `from_party` is filled in from `products` when the sheet omits it, which
--     is what makes a bulk load of historical transfers usable
--
-- Calls already raised keep the party they were raised under — they happened
-- under the old owner, and rewriting them would be falsifying the record.
-- ===========================================================================

create table if not exists public.ownership_transfers (
  id             bigint generated always as identity primary key,
  serial_number  text not null,
  item_name      text not null default '',
  from_party     text not null default '',
  to_party       text not null,
  transfer_date  date,
  reference_no   text not null default '',   -- the customer's paperwork
  reason         text not null default '',
  remarks        text not null default '',
  document_url   text not null default '',   -- Drive link to the hand-over document
  recorded_by      uuid references auth.users (id),
  recorded_by_name text not null default '',
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  constraint ownership_transfer_parties_differ check (btrim(lower(from_party)) is distinct from btrim(lower(to_party)))
);

create index if not exists ownership_transfers_serial_idx on public.ownership_transfers (lower(serial_number));
create index if not exists ownership_transfers_date_idx   on public.ownership_transfers (transfer_date desc nulls last, id desc);

-- ---------------------------------------------------------------------------
-- Fill in what the sheet left out, then move the machine.
--
-- The order matters: `from_party` has to be read BEFORE products is updated, or
-- a bulk load of several transfers for one machine would record every hop as
-- starting from the same party.
-- ---------------------------------------------------------------------------
create or replace function public.ownership_transfer_apply()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_serial text := btrim(coalesce(new.serial_number, ''));
begin
  if v_serial = '' then
    raise exception 'An ownership transfer needs the machine serial number.';
  end if;
  if btrim(coalesce(new.to_party, '')) = '' then
    raise exception 'An ownership transfer needs the party it is going to.';
  end if;

  if tg_op = 'INSERT' then
    new.recorded_by := coalesce(new.recorded_by, auth.uid());
    -- Who holds it now, per the machine master — the truthful "from".
    if btrim(coalesce(new.from_party, '')) = '' then
      select coalesce(p.party_name, '') into new.from_party
        from public.products p
       where lower(btrim(p.serial_number)) = lower(v_serial)
       limit 1;
    end if;
    if btrim(coalesce(new.item_name, '')) = '' then
      select coalesce(p.item_name, '') into new.item_name
        from public.products p
       where lower(btrim(p.serial_number)) = lower(v_serial)
       limit 1;
    end if;
  else
    new.recorded_by := old.recorded_by;   -- authorship is not editable
    new.created_at  := old.created_at;
  end if;
  new.updated_at := now();
  return new;
end $$;

drop trigger if exists ownership_transfer_biu on public.ownership_transfers;
create trigger ownership_transfer_biu before insert or update on public.ownership_transfers
  for each row execute function public.ownership_transfer_apply();

-- The machine follows the LATEST transfer, applied after the row lands so the
-- "from" above was read against the previous state.
create or replace function public.ownership_transfer_move()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_serial text := lower(btrim(coalesce(new.serial_number, '')));
begin
  -- Only the most recent transfer for this machine decides who holds it, so a
  -- back-dated row loaded after a later one does not undo it.
  if exists (
    select 1 from public.ownership_transfers t
     where lower(btrim(t.serial_number)) = v_serial
       and t.id <> new.id
       and (coalesce(t.transfer_date, '0001-01-01') > coalesce(new.transfer_date, '0001-01-01')
        or (coalesce(t.transfer_date, '0001-01-01') = coalesce(new.transfer_date, '0001-01-01') and t.id > new.id))
  ) then
    return null;
  end if;

  update public.products p
     set party_name = new.to_party
   where lower(btrim(p.serial_number)) = v_serial
     and coalesce(p.party_name, '') is distinct from new.to_party;
  return null;
end $$;

drop trigger if exists ownership_transfer_aiu on public.ownership_transfers;
create trigger ownership_transfer_aiu after insert or update on public.ownership_transfers
  for each row execute function public.ownership_transfer_move();

-- ---------------------------------------------------------------------------
-- Access. Moving a machine between customers changes what every future call,
-- warranty and contract reads, so it is its own right rather than folded into
-- masters.edit. Everyone signed in may READ the history — it is the answer to
-- "who owned this when".
-- ---------------------------------------------------------------------------
alter table public.ownership_transfers enable row level security;
grant select, insert, update, delete on public.ownership_transfers to authenticated;

drop policy if exists ownership_read on public.ownership_transfers;
create policy ownership_read on public.ownership_transfers for select
  using (auth.role() = 'authenticated');

drop policy if exists ownership_write on public.ownership_transfers;
create policy ownership_write on public.ownership_transfers for all
  using (public.has_perm('ownership.transfer'))
  with check (public.has_perm('ownership.transfer'));

-- Grant it where the work already sits, by MERGING — never overwriting, since
-- an admin may have tuned the role.
do $$
declare r record;
begin
  if to_regclass('public.app_roles') is null then return; end if;
  for r in select role, coalesce(permissions, '[]'::jsonb) as perms from public.app_roles loop
    if r.role in ('admin', 'commercial', 'hotline') and not (r.perms ? 'ownership.transfer') then
      update public.app_roles set permissions = r.perms || '["ownership.transfer"]'::jsonb, updated_at = now()
       where role = r.role;
    end if;
  end loop;
  update public.app_roles
     set permissions = coalesce(permissions, '[]'::jsonb) || '["mod:/ownership-transfer"]'::jsonb, updated_at = now()
   where not (coalesce(permissions, '[]'::jsonb) ? 'mod:/ownership-transfer');
end $$;

-- ------------------------------------------------------------------------
-- 0073_product_additional_entries.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- ADDITIONAL ENTRY DETAILS — warranty for a machine whose sale entry is lost.
--
-- `sync_product_cover()` (0036) derives a machine's warranty and contract from
-- the Sale and Contract registers. That is right when the paperwork exists. For
-- an older machine whose Sale Entry never made it into the system, it leaves
-- the machine with no warranty at all — and a call against it reads as
-- out-of-warranty, which is a commercial decision made on missing data.
--
-- This is the second source: warranty (and contract) recorded directly against
-- a serial, for machines that have no entry to derive from. It is NOT a way to
-- overrule the registers — `sync_product_cover` reads it only where a real Sale
-- or Contract item is absent, so the moment the paperwork is loaded the
-- authoritative record wins and this stops being consulted.
--
-- `source_note` records WHERE the detail came from (the customer's copy, an old
-- invoice, an engineer's file). A recovered warranty date with no provenance is
-- an assertion; with one it is evidence.
-- ===========================================================================

create table if not exists public.product_additional_entries (
  id              bigint generated always as identity primary key,
  serial_number   text not null,
  item_name       text not null default '',
  party_name      text not null default '',
  warranty_number text not null default '',
  warranty_start  date,
  warranty_end    date,
  contract_number text not null default '',
  contract_type   text not null default '',
  contract_start  date,
  contract_end    date,
  source_note     text not null default '',   -- where this detail came from
  document_url    text not null default '',
  remarks         text not null default '',
  recorded_by      uuid references auth.users (id),
  recorded_by_name text not null default '',
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);

-- One recovered entry per machine: a second one is a correction of the first,
-- not another record, so the upload can upsert on it.
create unique index if not exists product_additional_entries_serial_uniq
  on public.product_additional_entries (lower(btrim(serial_number)));

create or replace function public.product_additional_entry_biu()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if btrim(coalesce(new.serial_number, '')) = '' then
    raise exception 'An additional entry needs the machine serial number.';
  end if;
  if tg_op = 'INSERT' then new.recorded_by := coalesce(new.recorded_by, auth.uid());
  else new.recorded_by := old.recorded_by; new.created_at := old.created_at; end if;
  new.updated_at := now();
  return new;
end $$;
drop trigger if exists product_additional_entry_biu on public.product_additional_entries;
create trigger product_additional_entry_biu before insert or update on public.product_additional_entries
  for each row execute function public.product_additional_entry_biu();

-- Push it onto the machine as soon as it is recorded, so Product Master shows
-- it without waiting for a cover re-sync.
create or replace function public.product_additional_entry_apply()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  perform public.sync_product_cover(new.serial_number);
  return null;
end $$;
drop trigger if exists product_additional_entry_aiu on public.product_additional_entries;
create trigger product_additional_entry_aiu after insert or update on public.product_additional_entries
  for each row execute function public.product_additional_entry_apply();

-- ---------------------------------------------------------------------------
-- Teach sync_product_cover the second source.
--
-- Ranked BELOW the real registers on purpose: a Sale Item wins wherever one
-- exists, so loading the genuine paperwork later silently corrects a recovered
-- guess rather than being blocked by it. Same shape as the original (0036) —
-- indexed single-serial lookups, because an import fires this once per item.
-- ---------------------------------------------------------------------------
create or replace function public.sync_product_cover(p_serial text)
returns void language plpgsql security definer set search_path = public as $$
declare k text := lower(trim(coalesce(p_serial, ''))); w record; c record; a record;
begin
  if k = '' then return; end if;

  select i.sa_number, coalesce(i.warranty_start, h.warranty_start) as warranty_start,
         coalesce(i.warranty_end, h.warranty_end) as warranty_end
    into w
    from public.sale_items i join public.sale_entries h on h.sa_number = i.sa_number
   where lower(trim(i.serial_number)) = k
   order by coalesce(i.warranty_end, h.warranty_end) desc nulls last, i.id desc limit 1;

  select i.mc_number, coalesce(i.contract_type, h.contract_type) as contract_type,
         coalesce(i.contract_start, h.contract_start) as contract_start,
         coalesce(i.contract_end, h.contract_end) as contract_end
    into c
    from public.contract_items i join public.contract_entries h on h.mc_number = i.mc_number
   where lower(trim(i.serial_number)) = k
   order by coalesce(i.contract_end, h.contract_end) desc nulls last, i.id desc limit 1;

  -- The recovered detail, used only where the registers are silent.
  if to_regclass('public.product_additional_entries') is not null then
    select e.warranty_number, e.warranty_start, e.warranty_end,
           e.contract_number, e.contract_type, e.contract_start, e.contract_end
      into a
      from public.product_additional_entries e
     where lower(btrim(e.serial_number)) = k limit 1;
  end if;

  update public.products p set
    warranty_number = coalesce(w.sa_number, nullif(a.warranty_number, ''), p.warranty_number),
    warranty_start  = coalesce(w.warranty_start, a.warranty_start, p.warranty_start),
    warranty_end    = coalesce(w.warranty_end,   a.warranty_end,   p.warranty_end),
    contract_number = coalesce(c.mc_number, nullif(a.contract_number, ''), p.contract_number),
    contract_start  = coalesce(c.contract_start, a.contract_start, p.contract_start),
    contract_end    = coalesce(c.contract_end,   a.contract_end,   p.contract_end),
    contract_type   = coalesce(nullif(c.contract_type, ''), nullif(a.contract_type, ''), p.contract_type),
    item_status     = case
      when coalesce(c.contract_end, a.contract_end) >= current_date
        then coalesce(nullif(c.contract_type, ''), nullif(a.contract_type, ''), 'CMC')
      when coalesce(w.warranty_end, a.warranty_end) >= current_date then 'WARRANTY'
      else p.item_status end
  where lower(trim(p.serial_number)) = k;
end $$;
grant execute on function public.sync_product_cover(text) to authenticated;

alter table public.product_additional_entries enable row level security;
grant select, insert, update, delete on public.product_additional_entries to authenticated;

drop policy if exists pae_read on public.product_additional_entries;
create policy pae_read on public.product_additional_entries for select
  using (auth.role() = 'authenticated');

-- Same right that governs the Sale and Contract registers: this IS cover data,
-- recorded by a different route.
drop policy if exists pae_write on public.product_additional_entries;
create policy pae_write on public.product_additional_entries for all
  using (public.has_perm('cover.edit'))
  with check (public.has_perm('cover.edit'));

-- ------------------------------------------------------------------------
-- 0080_ownership_extra.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Ownership Transfer: keep what the export carries.
--
-- The real hand-over export has 28 columns the register has no field for — the
-- OT number's warranty and SA context, the engineer, the city, the state, the
-- file upload. `ownership_transfers` had nowhere to put them, so the upload
-- reported "this register has nowhere to put them" and they would have been
-- dropped on the floor.
--
-- A hand-over is a record of provenance. Losing the paperwork around it because
-- the table happened to have no column is exactly the kind of quiet loss the
-- rest of the import is careful to avoid, so the row keeps what it came with.
-- ===========================================================================

alter table public.ownership_transfers add column if not exists extra jsonb not null default '{}'::jsonb;

comment on column public.ownership_transfers.extra is
  'Everything the source export carried that has no field of its own, kept as written.';

-- The stock-transfer register has the same gap: its export carries the
-- timestamp, the raising engineer's email, the MTN number and the uploaded
-- document, none of which had a field.
alter table public.stock_transfers add column if not exists extra jsonb not null default '{}'::jsonb;
comment on column public.stock_transfers.extra is
  'Everything the source export carried that has no field of its own, kept as written.';

-- ------------------------------------------------------------------------
-- 0077_upsert_targets.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Make the bulk-upload upsert targets INFERABLE.
--
-- `on conflict (cols)` needs a unique index Postgres can infer from that exact
-- column list. It cannot infer a PARTIAL index, an EXPRESSION index, or
-- anything at all on a VIEW. Five registers were declared against targets that
-- fail one of those tests, so their upload was refused outright — "there is no
-- unique or exclusion constraint matching the ON CONFLICT specification", or
-- worse, silence.
--
-- The same trap has now been sprung four times (0071's partial reports_uid_key,
-- 0074, 0076, and here), which is why `npm run check:uploads` now verifies every
-- register's conflict target against a real database rather than by eye.
--
-- The call registers needed no change here: they were pointed at the `calls`
-- VIEW, and the fix is in the app — target the physical field_calls /
-- installation_calls / pm_calls, each of which already has <table>_ucn_key and
-- still fires calls_biu (call number, reg date). That is strictly better: the
-- upsert works AND the stamping trigger still runs.
--
-- LIVES IN THE sales_contracts MODULE, not handstock, although it fixes a table
-- from each. `product_additional_entries` is created by 0073 in
-- sales_contracts, which ALL_ORDER runs AFTER handstock — so from handstock this
-- file ran before the table existed and all.sql died on it. The later module is
-- the one where both tables are present.
-- ===========================================================================

-- ---- product_additional_entries: expression index -> stored column ---------
alter table public.product_additional_entries
  add column if not exists serial_key text generated always as (lower(btrim(serial_number))) stored;

create unique index if not exists product_additional_entries_serial_key_uniq
  on public.product_additional_entries (serial_key);
drop index if exists public.product_additional_entries_serial_uniq;

-- ---- spare_consumption_history: partial index -> plain -------------------
--
-- The partial index (`where ref <> ''`) protected only the rows that carry a
-- reference, and could not be inferred. A row with no reference cannot be
-- matched on a re-run anyway, so the upload now REQUIRES one and this index is
-- plain — which makes it both inferable and honest about what it guarantees.
--
-- Guarded: if rows without a reference are already loaded they would all
-- collide on ('', source), so say so rather than failing the migration.
do $$
begin
  if exists (
    select 1 from public.spare_consumption_history
     group by source_key, ref having count(*) > 1
  ) then
    raise notice 'spare_consumption_history has rows sharing (source, ref) — leaving the partial index in place. Give those rows a distinct ref and re-run this file.';
    return;
  end if;
  drop index if exists public.spare_consumption_history_ref_uniq;
  create unique index if not exists spare_consumption_history_ref_uniq
    on public.spare_consumption_history (source_key, ref);
end $$;

-- ------------------------------------------------------------------------
-- 0106_cover_views_security_invoker.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- The cover views read as their owner too, for the same reason.
--
-- `sale_entries` and `contract_entries` restrict reads to `masters.view`,
-- `cover.edit` or an administrator. `warranty_sale_details` and
-- `contract_details` are views over them that were never marked
-- `security_invoker`, so anybody signed in could read the sale and contract
-- record through the view that the table itself would have refused them.
--
-- Smaller in reach than the `calls` leak (0105) and exactly the same fault.
-- Filed in `sales_contracts` because that is the bundle defining these views.
-- ===========================================================================

do $$
declare v text;
begin
  foreach v in array array['warranty_sale_details', 'contract_details', 'machine_cover'] loop
    if to_regclass('public.' || v) is not null
       and (select relkind from pg_class where oid = ('public.' || v)::regclass) = 'v' then
      execute format('alter view public.%I set (security_invoker = on)', v);
      raise notice '%: row-level security now applies to the reader.', v;
    end if;
  end loop;
end $$;

-- ------------------------------------------------------------------------
-- 0044_sla_rules.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- SLA rules — the service-level targets, editable in Admin Config. Each rule is
-- a named target in hours with an on/off switch; the app computes each open
-- call's status (on track / due soon / breached) against the active rules and
-- highlights it for engineers. The rule LOGIC is fixed (which event each rule
-- measures); the hours and whether it applies are what admins edit.
-- ===========================================================================

create table if not exists public.sla_rules (
  key          text primary key,   -- fixed rule id (see seed)
  label        text not null,
  target_hours integer not null,
  active       boolean not null default true,
  sort_order   integer not null default 0,
  updated_at   timestamptz not null default now()
);

-- Seed the agreed rules (idempotent — an admin's later edits are preserved).
insert into public.sla_rules (key, label, target_hours, sort_order) values
  ('first_visit',             'First visit',                         72,  1),
  ('closure',                 'Call closure',                        120, 2),
  ('closure_spare',           'Closure — call includes a spare',     168, 3),
  ('closure_spare_noncover',  'Closure — spare & not in CMC / WGP',  240, 4),
  ('stores_dispatch',         'Stores dispatch — from final approval', 72, 5)
on conflict (key) do nothing;

create or replace function public.sla_rules_touch()
returns trigger language plpgsql as $$
begin new.updated_at := now(); return new; end $$;
drop trigger if exists sla_rules_touch on public.sla_rules;
create trigger sla_rules_touch before update on public.sla_rules
  for each row execute function public.sla_rules_touch();

alter table public.sla_rules enable row level security;
grant select, insert, update, delete on public.sla_rules to authenticated;

drop policy if exists sla_read on public.sla_rules;
create policy sla_read on public.sla_rules for select using (auth.role() = 'authenticated');

drop policy if exists sla_write on public.sla_rules;
create policy sla_write on public.sla_rules for all
  using (public.is_admin() or public.has_perm('config.manage'))
  with check (public.is_admin() or public.has_perm('config.manage'));

-- ------------------------------------------------------------------------
-- 0042_knowledge_base.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Knowledge Base — team-written field-solution articles. Anyone signed in can
-- read every article and contribute one; the author (or an admin) can edit or
-- delete their own. Stamped with the author so the team knows who to ask.
-- ===========================================================================

create table if not exists public.kb_articles (
  id           bigint generated always as identity primary key,
  title        text not null,
  body         text not null,
  category     text default '',      -- Field Issue / How-To / Product Tip / Other
  product      text default '',      -- optional: the product / model it concerns
  tags         text default '',      -- optional: comma-separated keywords
  attachments  jsonb not null default '[]',  -- [{name, url}] — links to files in Drive / on Pages / anywhere
  author_name  text default '',
  author_email text default '',
  created_by   uuid references auth.users (id),
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);
create index if not exists kb_articles_updated_idx  on public.kb_articles (updated_at desc);
create index if not exists kb_articles_category_idx  on public.kb_articles (category);

-- Stamp the author on insert (can't be spoofed) and updated_at on every write.
create or replace function public.kb_before_write()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' and auth.uid() is not null then
    new.created_by := auth.uid();
  end if;
  new.updated_at := now();
  return new;
end $$;
drop trigger if exists kb_biu on public.kb_articles;
create trigger kb_biu before insert or update on public.kb_articles
  for each row execute function public.kb_before_write();

alter table public.kb_articles enable row level security;
grant select, insert, update, delete on public.kb_articles to authenticated;

-- Read: everyone signed in. Contribute: any signed-in user (stamped as self).
-- Edit / delete: the author, or an admin.
drop policy if exists kb_read on public.kb_articles;
create policy kb_read on public.kb_articles for select
  using (auth.role() = 'authenticated');

drop policy if exists kb_insert on public.kb_articles;
create policy kb_insert on public.kb_articles for insert
  with check (auth.uid() is not null);

drop policy if exists kb_update on public.kb_articles;
create policy kb_update on public.kb_articles for update
  using (created_by = auth.uid() or public.is_admin())
  with check (created_by = auth.uid() or public.is_admin());

drop policy if exists kb_delete on public.kb_articles;
create policy kb_delete on public.kb_articles for delete
  using (created_by = auth.uid() or public.is_admin());

-- ------------------------------------------------------------------------
-- 0043_help_screenshots.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Help screenshots — one optional picture per task in the "How to use RITHI
-- CRM" guide, keyed by the task's section id (e.g. 'request', 'install'). Every
-- signed-in user sees them; only an admin can set or clear one. The image is a
-- downscaled data URL (same as Knowledge Base article images), so no separate
-- file store is needed.
-- ===========================================================================

create table if not exists public.help_screenshots (
  section_id  text primary key,             -- matches a guide section id
  image       text not null,                -- data URL (downscaled JPEG/PNG)
  caption     text not null default '',
  updated_by  uuid references auth.users (id),
  updated_at  timestamptz not null default now()
);

-- Stamp who/when on every write (can't be spoofed by the client).
create or replace function public.help_shot_before_write()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is not null then new.updated_by := auth.uid(); end if;
  new.updated_at := now();
  return new;
end $$;
drop trigger if exists help_shot_biu on public.help_screenshots;
create trigger help_shot_biu before insert or update on public.help_screenshots
  for each row execute function public.help_shot_before_write();

alter table public.help_screenshots enable row level security;
grant select, insert, update, delete on public.help_screenshots to authenticated;

-- Read: everyone signed in. Set / replace / clear: admins only.
drop policy if exists help_shot_read on public.help_screenshots;
create policy help_shot_read on public.help_screenshots for select
  using (auth.role() = 'authenticated');

drop policy if exists help_shot_insert on public.help_screenshots;
create policy help_shot_insert on public.help_screenshots for insert
  with check (public.is_admin());

drop policy if exists help_shot_update on public.help_screenshots;
create policy help_shot_update on public.help_screenshots for update
  using (public.is_admin()) with check (public.is_admin());

drop policy if exists help_shot_delete on public.help_screenshots;
create policy help_shot_delete on public.help_screenshots for delete
  using (public.is_admin());

-- ------------------------------------------------------------------------
-- 0045_notifications.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- In-app notifications — a per-user bell. The database raises a notification
-- when a call is allotted to an engineer, or a spare they requested is
-- dispatched. Each user reads/marks only their own.
-- ===========================================================================

create table if not exists public.notifications (
  id              bigint generated always as identity primary key,
  recipient_id    uuid references auth.users (id),
  recipient_email text default '',
  kind            text default '',
  title           text not null,
  body            text default '',
  link            text default '',
  read            boolean not null default false,
  created_at      timestamptz not null default now()
);
create index if not exists notifications_recipient_idx on public.notifications (recipient_id, read, created_at desc);

alter table public.notifications enable row level security;
grant select, update on public.notifications to authenticated;
drop policy if exists notif_read on public.notifications;
create policy notif_read on public.notifications for select using (recipient_id = auth.uid());
drop policy if exists notif_update on public.notifications;
create policy notif_update on public.notifications for update
  using (recipient_id = auth.uid()) with check (recipient_id = auth.uid());
-- No insert policy: only the SECURITY DEFINER triggers below create rows.

-- Resolve an engineer (by email, else by directory name) to a login id.
create or replace function public.notify_resolve_uid(p_email text, p_name text)
returns uuid language sql stable security definer set search_path = public as $$
  select coalesce(
    (select id from public.profiles where lower(email) = lower(nullif(p_email, '')) limit 1),
    (select p.id from public.profiles p
       join public.user_directory d on lower(d.email) = lower(p.email)
      where lower(d.name) = lower(nullif(p_name, '')) limit 1)
  );
$$;

-- ---- call allotted ---------------------------------------------------------
create or replace function public.notify_call_allotted()
returns trigger language plpgsql security definer set search_path = public as $$
declare uid uuid;
begin
  if coalesce(new.allocated_to, '') = '' then return new; end if;
  if tg_op = 'UPDATE' and new.allocated_to is not distinct from old.allocated_to then return new; end if;
  uid := public.notify_resolve_uid(new.allocated_to_email, new.allocated_to);
  if uid is null then return new; end if;
  insert into public.notifications (recipient_id, recipient_email, kind, title, body, link)
  values (uid, coalesce(new.allocated_to_email, ''), 'call_allotted',
          'Call allotted to you',
          concat_ws(' · ', nullif(coalesce(new.ucn, ''), ''), nullif(coalesce(new.party_name, ''), ''), nullif(coalesce(new.product_name, ''), '')),
          '/' || case public.call_table_for(new.call_type)
                   when 'installation' then 'installations' when 'pm' then 'pm-calls' else 'field-calls' end);
  return new;
end $$;

-- ---- spare dispatched ------------------------------------------------------
create or replace function public.notify_spare_dispatched()
returns trigger language plpgsql security definer set search_path = public as $$
declare uid uuid; r record;
begin
  if coalesce(new.stores_status, '') !~* 'dispatch' then return new; end if;
  if tg_op = 'UPDATE' and coalesce(old.stores_status, '') ~* 'dispatch' then return new; end if;
  select engineer, engineer_email, ucn, party_name into r
    from public.spare_requests where uid = new.request_uid;
  uid := public.notify_resolve_uid(r.engineer_email, r.engineer);
  if uid is null then return new; end if;
  insert into public.notifications (recipient_id, recipient_email, kind, title, body, link)
  values (uid, coalesce(r.engineer_email, ''), 'spare_dispatched',
          'Spare dispatched',
          concat_ws(' · ', nullif(coalesce(new.part, ''), ''), nullif(coalesce(r.ucn, ''), ''), nullif(coalesce(r.party_name, ''), '')),
          '/spare-requests');
  return new;
end $$;

-- ---- attach the triggers ---------------------------------------------------
do $$
declare t text;
begin
  -- call allotted: on whichever call tables exist (split base tables, else calls).
  foreach t in array array['field_calls', 'installation_calls', 'pm_calls', 'calls'] loop
    if to_regclass('public.' || t) is not null
       and (select relkind from pg_class where oid = ('public.' || t)::regclass) = 'r' then
      execute format('drop trigger if exists notify_alloc on public.%I', t);
      execute format('create trigger notify_alloc after insert or update on public.%I for each row execute function public.notify_call_allotted()', t);
    end if;
  end loop;

  if to_regclass('public.spare_request_lines') is not null then
    drop trigger if exists notify_dispatch on public.spare_request_lines;
    create trigger notify_dispatch after update on public.spare_request_lines
      for each row execute function public.notify_spare_dispatched();
  end if;
end $$;

-- ------------------------------------------------------------------------
-- 0054_notify_uid_ambiguous.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Fix: "column reference \"uid\" is ambiguous" when Stores books out a spare.
--
-- notify_spare_dispatched() (0045) declared a plpgsql variable named `uid`, and
-- then looked the request up with `... from public.spare_requests where uid =
-- new.request_uid`. `uid` there is both the variable and spare_requests.uid, so
-- Postgres refuses the reference and the trigger aborts the UPDATE — which is
-- the update Pending Dispatch performs, so booking out failed outright.
--
-- Rename the variable to v_uid and qualify the column via an alias. Same for
-- notify_call_allotted(), which had the same variable name (harmless there, but
-- renamed so the pattern can't bite again).
-- ===========================================================================

create or replace function public.notify_call_allotted()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_uid uuid;
begin
  if coalesce(new.allocated_to, '') = '' then return new; end if;
  if tg_op = 'UPDATE' and new.allocated_to is not distinct from old.allocated_to then return new; end if;
  v_uid := public.notify_resolve_uid(new.allocated_to_email, new.allocated_to);
  if v_uid is null then return new; end if;
  insert into public.notifications (recipient_id, recipient_email, kind, title, body, link)
  values (v_uid, coalesce(new.allocated_to_email, ''), 'call_allotted',
          'Call allotted to you',
          concat_ws(' · ', nullif(coalesce(new.ucn, ''), ''), nullif(coalesce(new.party_name, ''), ''), nullif(coalesce(new.product_name, ''), '')),
          '/' || case public.call_table_for(new.call_type)
                   when 'installation' then 'installations' when 'pm' then 'pm-calls' else 'field-calls' end);
  return new;
end $$;

create or replace function public.notify_spare_dispatched()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_uid uuid; r record;
begin
  if coalesce(new.stores_status, '') !~* 'dispatch' then return new; end if;
  if tg_op = 'UPDATE' and coalesce(old.stores_status, '') ~* 'dispatch' then return new; end if;
  select sr.engineer, sr.engineer_email, sr.ucn, sr.party_name into r
    from public.spare_requests sr where sr.uid = new.request_uid;
  v_uid := public.notify_resolve_uid(r.engineer_email, r.engineer);
  if v_uid is null then return new; end if;
  insert into public.notifications (recipient_id, recipient_email, kind, title, body, link)
  values (v_uid, coalesce(r.engineer_email, ''), 'spare_dispatched',
          'Spare dispatched',
          concat_ws(' · ', nullif(coalesce(new.part, ''), ''), nullif(coalesce(r.ucn, ''), ''), nullif(coalesce(r.party_name, ''), '')),
          '/spare-requests');
  return new;
end $$;

-- ------------------------------------------------------------------------
-- 0046_validation_results.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Validation execution tracker — stores the executed result of each test case
-- (IQ/OQ/PQ) in the database instead of on paper, so the validation evidence
-- lives with the system. One current record per test id (latest execution).
-- QA / admins record results; everyone signed in may read them.
-- ===========================================================================

create table if not exists public.validation_results (
  test_id     text primary key,          -- e.g. 'OQ-02'
  result      text not null default '',   -- Pass | Fail | N/A | (blank = not executed)
  actual      text default '',
  tester      text default '',
  notes       text default '',
  executed_at timestamptz,
  recorded_by uuid references auth.users (id),
  updated_at  timestamptz not null default now()
);

create or replace function public.validation_results_stamp()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  new.updated_at := now();
  if auth.uid() is not null then new.recorded_by := auth.uid(); end if;
  if new.result is not null and new.result <> '' and new.executed_at is null then
    new.executed_at := now();
  end if;
  return new;
end $$;
drop trigger if exists validation_results_stamp on public.validation_results;
create trigger validation_results_stamp before insert or update on public.validation_results
  for each row execute function public.validation_results_stamp();

alter table public.validation_results enable row level security;
grant select, insert, update on public.validation_results to authenticated;

drop policy if exists valres_read on public.validation_results;
create policy valres_read on public.validation_results for select using (auth.role() = 'authenticated');

drop policy if exists valres_write on public.validation_results;
create policy valres_write on public.validation_results for all
  using (public.is_admin() or public.has_perm('config.manage'))
  with check (public.is_admin() or public.has_perm('config.manage'));

-- ------------------------------------------------------------------------
-- 0048_record_audit.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Database-enforced audit trail. The client-side audit_log records user actions,
-- but a defensible Part 11 / QMS audit trail must be created by the database so
-- it cannot be bypassed or altered. record_audit captures every INSERT / UPDATE
-- / DELETE on the quality-record tables, with the acting user, timestamp and the
-- before/after row. It is written only by SECURITY DEFINER triggers, read only
-- by admins, and never updatable/deletable by users.
-- ===========================================================================

create table if not exists public.record_audit (
  id          bigint generated always as identity primary key,
  table_name  text not null,
  op          text not null,           -- INSERT | UPDATE | DELETE
  record_key  text,                    -- ucn / uid / call_number / id
  actor       uuid,
  actor_email text,
  changed_at  timestamptz not null default now(),
  old_data    jsonb,
  new_data    jsonb
);
create index if not exists record_audit_at_idx  on public.record_audit (changed_at desc);
create index if not exists record_audit_tbl_idx on public.record_audit (table_name, changed_at desc);
create index if not exists record_audit_key_idx on public.record_audit (record_key);

create or replace function public.record_audit_fn()
returns trigger language plpgsql security definer set search_path = public as $$
declare j jsonb;
begin
  if tg_op = 'DELETE' then j := to_jsonb(old); else j := to_jsonb(new); end if;
  insert into public.record_audit (table_name, op, record_key, actor, actor_email, old_data, new_data)
  values (
    tg_table_name, tg_op,
    coalesce(j->>'ucn', j->>'uid', j->>'line_uid', j->>'call_number', j->>'id'),
    auth.uid(), auth.email(),
    case when tg_op <> 'INSERT' then to_jsonb(old) else null end,
    case when tg_op <> 'DELETE' then to_jsonb(new) else null end
  );
  return case when tg_op = 'DELETE' then old else new end;
end $$;

alter table public.record_audit enable row level security;
grant select on public.record_audit to authenticated;   -- read only; no insert/update/delete grant
drop policy if exists record_audit_read on public.record_audit;
create policy record_audit_read on public.record_audit for select
  using (public.is_admin() or public.has_perm('audit.view'));

-- Attach to the quality-record tables that exist.
do $$
declare t text;
begin
  foreach t in array array[
    'field_calls', 'installation_calls', 'pm_calls', 'reports',
    'spare_requests', 'spare_request_lines', 'spare_consumption', 'feedback',
    'call_requests', 'pending_registrations'
  ] loop
    if to_regclass('public.' || t) is not null
       and (select relkind from pg_class where oid = ('public.' || t)::regclass) = 'r' then
      execute format('drop trigger if exists record_audit_t on public.%I', t);
      execute format('create trigger record_audit_t after insert or update or delete on public.%I for each row execute function public.record_audit_fn()', t);
    end if;
  end loop;
end $$;

-- ------------------------------------------------------------------------
-- 0049_record_retention_guard.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Record-retention guard. Quality records must be retained, not deleted — an
-- auditor expects that a service record, visit report or spare request cannot
-- be removed. Hard DELETE on these append-only quality tables is blocked; the
-- app uses status / cancel / drop workflows instead, which are captured by the
-- audit trail. (Configuration/operational tables are not covered here.)
-- ===========================================================================

create or replace function public.block_hard_delete()
returns trigger language plpgsql as $$
begin
  -- Application deletion (the authenticated role, via PostgREST) is blocked for
  -- retention. Controlled deletion by a DBA/superuser (e.g. an approved archival
  -- procedure in the SQL editor) is permitted and is still captured by the
  -- database audit trail.
  if current_user = 'authenticated' then
    raise exception
      'RECORD RETENTION: % records cannot be deleted (row %). Use the defined status / cancel / drop workflow.',
      tg_table_name,
      coalesce(to_jsonb(old)->>'ucn', to_jsonb(old)->>'uid', to_jsonb(old)->>'call_number', to_jsonb(old)->>'id');
  end if;
  return old;
end $$;

do $$
declare t text;
begin
  foreach t in array array[
    'field_calls', 'installation_calls', 'pm_calls', 'reports',
    'spare_requests', 'spare_request_lines', 'spare_consumption', 'feedback'
  ] loop
    if to_regclass('public.' || t) is not null
       and (select relkind from pg_class where oid = ('public.' || t)::regclass) = 'r' then
      execute format('drop trigger if exists no_hard_delete on public.%I', t);
      execute format('create trigger no_hard_delete before delete on public.%I for each row execute function public.block_hard_delete()', t);
    end if;
  end loop;
end $$;

-- ------------------------------------------------------------------------
-- 0103_record_audit_not_bulk.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- THE AUDIT TRAIL RECORDS WHAT PEOPLE DO, NOT WHAT A LOAD LOADED.
--
-- `record_audit` (0048) kept a row, with the whole record before and after, for
-- every INSERT / UPDATE / DELETE on the quality tables. That is right for a
-- person changing a record and wrong for a bulk load: migrating the sheet era
-- wrote tens of thousands of audit rows that say nothing a migration report
-- does not say better, and they are the reason the table grew as it did.
--
-- An audit trail exists to answer "who changed this record, and to what". A
-- one-time load is not that question; it is answered by the migration's own
-- verification (the DM checks in the validation package: row counts reconciled,
-- fields sampled, identifiers checked).
--
-- SO A BULK WRITE IS STILL RECORDED — AS ONE EVENT, NOT TEN THOUSAND. The row
-- says who loaded, into which table, how many rows and when. The load remains
-- attributable, which is what Part 11 asks of it; what goes is the per-record
-- duplicate of data that is already in the table it was loaded into.
--
-- HOW THE LINE IS DRAWN. A statement-level trigger with transition tables can
-- count the rows one statement touched, which a row-level trigger cannot. The
-- threshold sits between the largest write a PERSON makes in one statement and
-- the smallest a LOADER makes:
--
--     bulk re-allotment   100 rows per statement  (reallocateCalls, src/lib/supabase.ts)
--     bulk upload         300 or 500 per statement (uploadRows, same file)
--
-- 150 sits between them, and if either chunk size changes this number wants
-- revisiting. But the margin is wider than those numbers suggest, and it is
-- worth knowing why:
--
--   THE BULK USER ACTIONS GO THROUGH THE `calls` VIEW, and 0040's INSTEAD OF
--   triggers write it ROW BY ROW into the typed table. So at the table — which
--   is where this trigger sits — a hundred-call re-allotment arrives as a
--   hundred single-row statements and is audited in full, whatever the
--   threshold. The loaders write to `field_calls`, `spare_requests`,
--   `spare_consumption` and the rest DIRECTLY, in one statement per batch.
--
-- Verified on Postgres, all three: 500 rows loaded into field_calls -> one BULK
-- INSERT row; a re-allotment through the view -> a row each, with before and
-- after intact; a re-load UPDATING 500 rows -> one BULK UPDATE row.
--
-- Everything else is unchanged: written only by a SECURITY DEFINER trigger,
-- readable only by an administrator or `audit.view`, and still not writable or
-- alterable by anyone.
-- ===========================================================================

create or replace function public.record_audit_fn()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  n     bigint;
  bulk  boolean;
begin
  -- How many rows this ONE statement touched.
  if tg_op = 'DELETE' then
    select count(*) into n from old_rows;
  else
    select count(*) into n from new_rows;
  end if;
  if n = 0 then return null; end if;

  bulk := n > 150;

  if bulk then
    -- One row for the whole statement: who, what table, how many, when.
    insert into public.record_audit (table_name, op, record_key, actor, actor_email, old_data, new_data)
    values (tg_table_name, 'BULK ' || tg_op, null, auth.uid(), auth.email(), null,
            jsonb_build_object('rows', n,
                               'note', 'Bulk write — recorded as one event. The records are in ' || tg_table_name || '.'));
    return null;
  end if;

  -- Otherwise exactly what 0048 did, a row at a time, from the transition
  -- tables rather than from OLD / NEW.
  if tg_op = 'INSERT' then
    insert into public.record_audit (table_name, op, record_key, actor, actor_email, old_data, new_data)
    select tg_table_name, tg_op,
           coalesce(j->>'ucn', j->>'uid', j->>'line_uid', j->>'call_number', j->>'id'),
           auth.uid(), auth.email(), null, j
      from (select to_jsonb(r) as j from new_rows r) x;
  elsif tg_op = 'DELETE' then
    insert into public.record_audit (table_name, op, record_key, actor, actor_email, old_data, new_data)
    select tg_table_name, tg_op,
           coalesce(j->>'ucn', j->>'uid', j->>'line_uid', j->>'call_number', j->>'id'),
           auth.uid(), auth.email(), j, null
      from (select to_jsonb(r) as j from old_rows r) x;
  else
    -- UPDATE: the before and after of the same record, paired on the key the
    -- audit is written under. A quality table without one of these keys cannot
    -- be paired, so both images are still written and the key reads null.
    insert into public.record_audit (table_name, op, record_key, actor, actor_email, old_data, new_data)
    select tg_table_name, tg_op,
           coalesce(nj->>'ucn', nj->>'uid', nj->>'line_uid', nj->>'call_number', nj->>'id'),
           auth.uid(), auth.email(), oj, nj
      from (
        select to_jsonb(nr) as nj,
               (select to_jsonb(orow) from old_rows orow
                 where coalesce(to_jsonb(orow)->>'ucn', to_jsonb(orow)->>'uid', to_jsonb(orow)->>'line_uid',
                                to_jsonb(orow)->>'call_number', to_jsonb(orow)->>'id')
                       is not distinct from
                       coalesce(to_jsonb(nr)->>'ucn', to_jsonb(nr)->>'uid', to_jsonb(nr)->>'line_uid',
                                to_jsonb(nr)->>'call_number', to_jsonb(nr)->>'id')
                 limit 1) as oj
          from new_rows nr
      ) x;
  end if;
  return null;
end $$;

-- Re-attach: one trigger PER OPERATION now, because a statement trigger names
-- the transition table it needs and INSERT has no OLD, DELETE no NEW.
do $$
declare t text;
begin
  foreach t in array array[
    'field_calls', 'installation_calls', 'pm_calls', 'reports',
    'spare_requests', 'spare_request_lines', 'spare_consumption', 'feedback',
    'call_requests', 'pending_registrations'
  ] loop
    if to_regclass('public.' || t) is not null
       and (select relkind from pg_class where oid = ('public.' || t)::regclass) = 'r' then
      execute format('drop trigger if exists record_audit_t on public.%I', t);
      execute format('drop trigger if exists record_audit_i on public.%I', t);
      execute format('drop trigger if exists record_audit_u on public.%I', t);
      execute format('drop trigger if exists record_audit_d on public.%I', t);
      execute format('create trigger record_audit_i after insert on public.%I '
                     'referencing new table as new_rows for each statement '
                     'execute function public.record_audit_fn()', t);
      execute format('create trigger record_audit_u after update on public.%I '
                     'referencing old table as old_rows new table as new_rows for each statement '
                     'execute function public.record_audit_fn()', t);
      execute format('create trigger record_audit_d after delete on public.%I '
                     'referencing old table as old_rows for each statement '
                     'execute function public.record_audit_fn()', t);
    end if;
  end loop;
end $$;

-- ------------------------------------------------------------------------
-- 0052_search_indexes.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Search performance. The app searches with substring ILIKE ('%term%') across
-- products, parties and the call registers. A leading wildcard cannot use the
-- existing lower(col) btree indexes, so every search seq-scans the whole table
-- and, once the tables grew, hit the API statement timeout ("canceling
-- statement due to statement timeout") on every page.
--
-- pg_trgm trigram GIN indexes make substring/ILIKE matching index-backed. This
-- block installs pg_trgm and adds a trigram index for each searched column that
-- exists, on each base table that exists — so it works before or after the call
-- split (0040): the `calls` VIEW is skipped, its base tables are indexed.
-- Idempotent (create index if not exists); safe to re-run.
-- ===========================================================================

create extension if not exists pg_trgm;

do $$
declare
  trgm text;   -- schema pg_trgm actually lives in (extensions on Supabase)
  rec  record;
  idx  text;
begin
  select quote_ident(n.nspname) into trgm
    from pg_extension e join pg_namespace n on n.oid = e.extnamespace
   where e.extname = 'pg_trgm';
  if trgm is null then raise notice 'pg_trgm not available — skipping'; return; end if;

  for rec in
    select tbl, col from (values
      ('products','serial_number'), ('products','item_name'), ('products','party_name'),
      ('parties','party_name'),
      ('field_calls','ucn'), ('field_calls','call_number'), ('field_calls','party_name'),
      ('field_calls','serial'), ('field_calls','product_name'), ('field_calls','allocated_to'),
      ('field_calls','city'), ('field_calls','state'), ('field_calls','standard_complaint'),
      ('field_calls','complaint_reported'), ('field_calls','customer_name'),
      ('installation_calls','ucn'), ('installation_calls','call_number'), ('installation_calls','party_name'),
      ('installation_calls','serial'), ('installation_calls','product_name'), ('installation_calls','allocated_to'),
      ('installation_calls','city'), ('installation_calls','state'), ('installation_calls','standard_complaint'),
      ('installation_calls','complaint_reported'), ('installation_calls','customer_name'),
      ('pm_calls','ucn'), ('pm_calls','call_number'), ('pm_calls','party_name'),
      ('pm_calls','serial'), ('pm_calls','product_name'), ('pm_calls','allocated_to'),
      ('pm_calls','city'), ('pm_calls','state'), ('pm_calls','standard_complaint'),
      ('pm_calls','complaint_reported'), ('pm_calls','customer_name'),
      ('calls','ucn'), ('calls','call_number'), ('calls','party_name'),
      ('calls','serial'), ('calls','product_name'), ('calls','allocated_to'),
      ('calls','city'), ('calls','state'), ('calls','standard_complaint'),
      ('calls','complaint_reported'), ('calls','customer_name')
    ) as v(tbl, col)
  loop
    -- table must exist and be an ordinary table (skip the calls VIEW after split)
    if to_regclass('public.' || rec.tbl) is null then continue; end if;
    if (select relkind from pg_class where oid = ('public.' || rec.tbl)::regclass) <> 'r' then continue; end if;
    -- column must exist on it
    if not exists (select 1 from information_schema.columns
                    where table_schema = 'public' and table_name = rec.tbl and column_name = rec.col) then
      continue;
    end if;
    idx := rec.tbl || '_' || rec.col || '_trgm';
    execute format('create index if not exists %I on public.%I using gin (%I %s.gin_trgm_ops)',
                   idx, rec.tbl, rec.col, trgm);
  end loop;
end $$;

-- Btree indexes for the EXACT-match / IN lookups (a trigram index does not
-- serve `=`/`IN`): the request cascade filters products by party_name (and
-- item_name) with eq, and openCallsFor looks up calls by serial / party_name
-- with IN. Without these, those lookups seq-scan and time out too.
do $$
declare rec record; idx text;
begin
  for rec in
    select tbl, col from (values
      ('products','party_name'), ('products','item_name'),
      ('field_calls','serial'), ('field_calls','party_name'),
      ('installation_calls','serial'), ('installation_calls','party_name'),
      ('pm_calls','serial'), ('pm_calls','party_name'),
      ('calls','serial'), ('calls','party_name')
    ) as v(tbl, col)
  loop
    if to_regclass('public.' || rec.tbl) is null then continue; end if;
    if (select relkind from pg_class where oid = ('public.' || rec.tbl)::regclass) <> 'r' then continue; end if;
    if not exists (select 1 from information_schema.columns
                    where table_schema = 'public' and table_name = rec.tbl and column_name = rec.col) then
      continue;
    end if;
    idx := rec.tbl || '_' || rec.col || '_eq';
    execute format('create index if not exists %I on public.%I (%I)', idx, rec.tbl, rec.col);
  end loop;
end $$;

-- Refresh planner stats so the new indexes are used right away.
do $$
declare t text;
begin
  foreach t in array array['products','parties','field_calls','installation_calls','pm_calls','calls'] loop
    if to_regclass('public.' || t) is not null
       and (select relkind from pg_class where oid = ('public.' || t)::regclass) = 'r' then
      execute 'analyze public.' || quote_ident(t);
    end if;
  end loop;
end $$;

-- ------------------------------------------------------------------------
-- 0098_product_register_names.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- THE PRODUCT LIST COMES FROM THE PRODUCT REGISTER.
--
-- Product & Party Search was filling its product dropdown from the `product`
-- master value list. That is a list somebody maintains, and it can be empty,
-- short, or spelled differently from the register — which is what the screen
-- showed. The register itself is the authority on what products exist: a
-- machine is in it or it is not.
--
-- PostgREST cannot ask for `select distinct`, so the distinct list is a view.
-- It carries the count as well, because "MONNAL T75 (1,204)" tells the person
-- choosing far more than the name alone, and it costs nothing to group once.
--
-- The serial dropdown that depends on it needs no view: it is
-- `item_name = <the one chosen>`, which 0052's btree on products(item_name)
-- already serves. (A trigram index does NOT serve equality — that lesson cost
-- this project a fortnight of timeouts.)
-- ===========================================================================

create or replace view public.product_register_names as
  select item_name,
         count(*)::int as machines
    from public.products
   where coalesce(item_name, '') <> ''
   group by item_name;

-- `create or replace view` does NOT carry `security_invoker` forward, so it is
-- asserted every time the view is written. Without it the view would read the
-- register as its owner and hand back rows RLS meant to withhold.
alter view public.product_register_names set (security_invoker = on);

grant select on public.product_register_names to authenticated;

-- ------------------------------------------------------------------------
-- 0099_no_jit.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- THE HAND STOCK TIMEOUT WAS JIT COMPILATION, NOT THE QUERY.
--
-- Hand Stock timed out, then took 11-14 seconds, then 3-5 after 0095. Every
-- reading pointed at row-level security, because switching RLS off made it
-- instant. It was the right symptom and the wrong cause. `EXPLAIN ANALYZE`
-- with the JIT block showing says it plainly:
--
--     Timing: Generation 23 ms, Inlining 145 ms,
--             Optimization 2134 ms, Emission 1440 ms, Total 3742 ms
--     Execution Time: 3912 ms
--
-- Three and three-quarter seconds COMPILING a query that then runs in under
-- two hundred milliseconds. The trigger is `jit_above_cost` (100,000): the
-- planner's ESTIMATE for the nine-arm movement view is half a million, almost
-- all of it invented by the cost of RLS sub-plans it will barely run. So the
-- more access rules a query carries, the more certain Postgres is to spend
-- seconds compiling it — and that is why turning RLS off "fixed" it.
--
-- With JIT off, and NOTHING else changed, the whole 102,893-row history reads
-- in 323 ms. Closed through 2025 it is 174 ms. Measured on a copy of the live
-- data, as the `authenticated` role, with every policy in force.
--
-- Nothing in this application benefits from JIT. These are sub-second API
-- queries; compiling them can only ever cost more than it saves. Off is the
-- right setting for the whole database, not a special case for one screen.
--
-- TO PUT IT BACK: `alter database postgres reset jit;`
--
-- It applies to CONNECTIONS MADE AFTER IT RUNS. Pooled connections already
-- open keep the old setting, so give it a few minutes — or restart the project
-- — before judging whether it worked.
-- ===========================================================================

do $$
begin
  execute format('alter database %I set jit = off', current_database());
  raise notice 'JIT disabled for database % — new connections only.', current_database();
exception
  when insufficient_privilege then
    raise notice 'Could not disable JIT: this role does not own the database. Set it in the Supabase dashboard, or run: alter database postgres set jit = off;';
end $$;

-- ------------------------------------------------------------------------
-- 0101_kpi_views.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- KPIs THAT COME FROM THE RECORD, NOT FROM A SPREADSHEET.
--
-- Three questions the service function actually asks, each answered by an
-- aggregate the database computes rather than a page that pulls forty thousand
-- rows across the wire and adds them up in a browser:
--
--   FAILURE RATE      how often does a product fail, per machine in the field?
--                     A count of calls means nothing on its own — a product with
--                     1,200 machines SHOULD generate more calls than one with 40.
--                     The denominator is the install base, which the Product
--                     Register already holds.
--
--   SPARE USE BY COVER  what do we spend on parts under warranty, under CMC,
--                     under AMC, and out of guarantee? The cover is on the CALL,
--                     the parts are on the consumption; the join is the answer.
--
--   SPARE USE BY REGION  the same figure per region, so a region consuming twice
--                     its share can be looked at rather than guessed at.
--
-- EVERY VIEW IS security_invoker, so an engineer's KPIs are their own calls and
-- a manager's are their team's. The numbers a person sees are the numbers they
-- are allowed to see, without a second set of rules to keep in step.
--
-- `create or replace view` does NOT carry security_invoker over — it is asserted
-- on every one of them, every time.
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- One row per part consumed, carrying what the call says about it. This is the
-- grain everything else rolls up from; it is also worth reading on its own when
-- a number looks wrong.
--
-- The cover (`item_status`) and the region are FACTS ABOUT THE CALL AND THE
-- ENGINEER, not about the part, so they are read from there rather than copied
-- onto the consumption row where they would age.
-- ---------------------------------------------------------------------------
create or replace view public.spare_usage as
  select c.id,
         c.ucn,
         c.call_number,
         c.part,
         public.part_code(c.part)                            as part_code,
         coalesce(c.qty, 0)                                  as qty,
         coalesce(nullif(btrim(c.engineer), ''), '')         as engineer,
         coalesce(nullif(btrim(k.item_status), ''), 'Not stated') as cover,
         coalesce(nullif(btrim(k.product_name), ''), '')     as product,
         coalesce(nullif(btrim(k.call_type), ''), '')        as call_type,
         coalesce(nullif(btrim(k.city), ''), '')             as city,
         coalesce(nullif(btrim(ud.region), ''), 'No region') as region,
         coalesce(nullif(btrim(c.source), ''), 'Engineer')   as source,
         c.created_at                                        as consumed_at
    from public.spare_consumption c
    left join public.calls k on k.ucn = c.ucn
    left join public.user_directory ud
           on lower(btrim(ud.name)) = lower(btrim(coalesce(nullif(c.engineer, ''), k.allocated_to)))
   where coalesce(c.qty, 0) <> 0;
alter view public.spare_usage set (security_invoker = on);
grant select on public.spare_usage to authenticated;

-- ---------------------------------------------------------------------------
-- Spare use by cover, region and product, in one rollup the screen pivots.
--
-- One row per combination rather than three separate views: a few thousand rows
-- at most, and a client that has them can answer "CMC in the South" without
-- another round trip — and, more to the point, without the three views being
-- able to disagree with each other.
-- ---------------------------------------------------------------------------
create or replace view public.spare_usage_rollup as
  select cover, region, product,
         count(*)::int                     as lines,
         sum(qty)                          as qty,
         count(distinct ucn)::int          as calls,
         count(distinct part_code)::int    as parts,
         count(distinct engineer)::int     as engineers
    from public.spare_usage
   group by cover, region, product;
alter view public.spare_usage_rollup set (security_invoker = on);
grant select on public.spare_usage_rollup to authenticated;

-- ---------------------------------------------------------------------------
-- FAILURE RATE — calls per hundred machines in the field, over twelve months.
--
-- `machines` is the install base from the Product Register and is NOT scoped by
-- who is asking: it is a property of the fleet, the same number for everybody.
-- `calls_12m` is scoped, because it is a count of calls. So an engineer reads
-- their own share of a fleet-wide denominator, which is the honest reading of
-- what they can see, and a rate is only comparable between products for someone
-- who can see all the calls. The screen says so.
--
-- Twelve months because a reliability figure needs a period; the same view
-- carries the all-time count beside it so a young product is not read as a
-- reliable one.
-- ---------------------------------------------------------------------------
create or replace view public.failure_rate_by_product as
  with fleet as (
    select coalesce(nullif(btrim(item_name), ''), '') as product, count(*)::int as machines
      from public.products
     where coalesce(btrim(item_name), '') <> ''
     group by 1
  ), calls as (
    select coalesce(nullif(btrim(product_name), ''), '') as product,
           count(*)::int as calls_total,
           count(*) filter (where reg_date >= (current_date - 365))::int as calls_12m,
           count(*) filter (where open_state <> 'Solved')::int as calls_open
      from public.calls
     where coalesce(btrim(product_name), '') <> ''
     group by 1
  )
  select coalesce(f.product, c.product)      as product,
         coalesce(f.machines, 0)             as machines,
         coalesce(c.calls_total, 0)          as calls_total,
         coalesce(c.calls_12m, 0)            as calls_12m,
         coalesce(c.calls_open, 0)           as calls_open,
         case when coalesce(f.machines, 0) > 0
              then round(coalesce(c.calls_12m, 0)::numeric * 100 / f.machines, 1)
         end                                  as per_100_machines
    from fleet f
    full join calls c on c.product = f.product;
alter view public.failure_rate_by_product set (security_invoker = on);
grant select on public.failure_rate_by_product to authenticated;

-- ---------------------------------------------------------------------------
-- HOW a product fails, not just how often. The standard complaint is the field
-- the service desk already chooses from a controlled list, so it is the one
-- thing in the record that groups reliably across thousands of calls.
-- ---------------------------------------------------------------------------
create or replace view public.failure_modes_by_product as
  select coalesce(nullif(btrim(product_name), ''), '')       as product,
         coalesce(nullif(btrim(standard_complaint), ''), 'Not stated') as complaint,
         count(*)::int                                       as calls,
         count(*) filter (where reg_date >= (current_date - 365))::int as calls_12m
    from public.calls
   where coalesce(btrim(product_name), '') <> ''
   group by 1, 2;
alter view public.failure_modes_by_product set (security_invoker = on);
grant select on public.failure_modes_by_product to authenticated;

-- The joins these views make, indexed. `spare_consumption.ucn` is the one that
-- matters: without it every rollup is a hash of the whole consumption history
-- against the whole call register.
create index if not exists spare_consumption_ucn_idx on public.spare_consumption (ucn);
create index if not exists field_calls_product_idx on public.field_calls (product_name);
create index if not exists installation_calls_product_idx on public.installation_calls (product_name);
create index if not exists pm_calls_product_idx on public.pm_calls (product_name);

commit;
